/**
 * Chat routes — multi-pin: get pins, pin, unpin, reorder
 */
import { Express } from 'express';
import { JwtRequest } from '../../src/middleware/jwtAuth.ts';
import { requireAuth } from '../../src/middleware/jwtAuth.ts';
import { validate, PinMessageSchema, PinsReorderSchema } from '../../src/middleware/validate.ts';
import { logger } from '../services/logger.ts';

export function setupChatPinRoutes(app: Express) {
  // GET pins
  app.get('/api/chats/:chatId/pins', requireAuth, async (req: JwtRequest, res) => {
    try {
      const chatId = req.params.chatId;
      const { pinnedMessages: pinnedMessagesTable } = await import('../../src/db/schema.ts');
      const { db } = await import('../../src/db/index.ts');
      const { eq, sql: drizzleSql } = await import('drizzle-orm');
      const { getChat } = await import('../../src/db/helpers.ts');

      const chat: Record<string, unknown> & { id?: number; type?: string; participants?: string[]; members?: string[]; admins?: string[]; creatorId?: number; creatorUid?: string } = await getChat(chatId);
      if (!chat) return res.status(404).json({ error: 'Chat not found' });

      const pins = await db.select().from(pinnedMessagesTable)
        .where(eq(pinnedMessagesTable.chatId, chat.id))
        .orderBy(drizzleSql`${pinnedMessagesTable.pinnedAt} DESC`);
      res.json(pins);
    } catch (err: unknown) {
      logger.error({ err }, "Get pinned messages error");
      res.status(500).json({ error: err.message });
    }
  });

  // Pin message
  app.post('/api/chats/:chatId/pins', requireAuth, validate(PinMessageSchema), async (req: JwtRequest, res) => {
    try {
      const uid = req.user!.uid;
      const chatId = req.params.chatId;
      const { messageUid } = req.body;

      const { getChat } = await import('../../src/db/helpers.ts');
      const chat: Record<string, unknown> & { id?: number; type?: string; participants?: string[]; members?: string[]; admins?: string[]; creatorId?: number; creatorUid?: string } = await getChat(chatId);
      if (!chat) return res.status(404).json({ error: 'Chat not found' });

      const isPrivate = chat.type === 'private' || chat.type === 'direct';
      const { getUserByUid } = await import('../../src/db/auth.ts');
      const userObj = await getUserByUid(uid);
      if (!isPrivate) {
        const isAdmin = chat.admins?.includes(uid);
        const isCreator = chat.creatorId === uid || chat.creatorUid === uid;
        const isGlobalAdmin = userObj?.role === 'admin';
        if (!isAdmin && !isCreator && !isGlobalAdmin) {
          return res.status(403).json({ error: 'Only administrators can pin messages in this chat' });
        }
      }

      const MAX_PINS = parseInt(process.env.MAX_PINS_PER_CHAT || '50', 10);
      const { pinnedMessages: pinnedMessagesTable } = await import('../../src/db/schema.ts');
      const { db } = await import('../../src/db/index.ts');
      const { eq, and, count } = await import('drizzle-orm');

      // Count + duplicate check in one query (reduces N+1)
      const countResult = await db.select({ cnt: count() })
        .from(pinnedMessagesTable)
        .where(eq(pinnedMessagesTable.chatId, chat.id));
      const currentCount = countResult[0]?.cnt || 0;
      if (currentCount >= MAX_PINS) {
        return res.status(400).json({ error: `Maximum pinned messages limit (${MAX_PINS}) reached` });
      }

      const existing = await db.select().from(pinnedMessagesTable)
        .where(and(eq(pinnedMessagesTable.chatId, chat.id), eq(pinnedMessagesTable.messageUid, messageUid)));
      if (existing.length > 0) {
        return res.status(409).json({ error: 'Message is already pinned' });
      }

      const pinnedByName = userObj?.displayName || userObj?.username || 'User';

      const result = await db.insert(pinnedMessagesTable).values({
        chatId: chat.id,
        messageUid,
        pinnedBy: uid,
        pinnedByName,
        sortOrder: 0,
      }).returning();
      const pin = result[0];

      // Broadcast to chat participants via WebSocket
      try {
        const broadcastFn = (globalThis as any).__broadcastPinnedMessagesUpdate;
        if (broadcastFn) {
          const participants: string[] = chat.participants || [];
          broadcastFn(participants, {
            type: 'pinned_messages_update',
            chatId: chatId,
            action: 'pin',
            pin,
          });
        }
      } catch (broadcastErr) {
        logger.warn({ err: broadcastErr }, '[Pin] Broadcast failed');
      }

      res.json(pin);
    } catch (err: unknown) {
      logger.error({ err }, "Pin message error");
      res.status(500).json({ error: err.message });
    }
  });

  // Unpin message
  app.delete('/api/chats/:chatId/pins/:messageUid', requireAuth, async (req: JwtRequest, res) => {
    try {
      const uid = req.user!.uid;
      const chatId = req.params.chatId;
      const messageUid = req.params.messageUid;

      const { getChat } = await import('../../src/db/helpers.ts');
      const chat: Record<string, unknown> & { id?: number; type?: string; participants?: string[]; members?: string[]; admins?: string[]; creatorId?: number; creatorUid?: string } = await getChat(chatId);
      if (!chat) return res.status(404).json({ error: 'Chat not found' });

      const isPrivate = chat.type === 'private' || chat.type === 'direct';
      if (!isPrivate) {
        const isAdmin = chat.admins?.includes(uid);
        const isCreator = chat.creatorId === uid || chat.creatorUid === uid;
        const { getUserByUid } = await import('../../src/db/auth.ts');
        const userObj = await getUserByUid(uid);
        const isGlobalAdmin = userObj?.role === 'admin';
        if (!isAdmin && !isCreator && !isGlobalAdmin) {
          return res.status(403).json({ error: 'Only administrators can unpin messages in this chat' });
        }
      }

      const { pinnedMessages: pinnedMessagesTable } = await import('../../src/db/schema.ts');
      const { db } = await import('../../src/db/index.ts');
      const { eq, and } = await import('drizzle-orm');

      const deleted = await db.delete(pinnedMessagesTable)
        .where(and(eq(pinnedMessagesTable.chatId, chat.id), eq(pinnedMessagesTable.messageUid, messageUid)))
        .returning();
      if (deleted.length === 0) {
        return res.status(404).json({ error: 'Pinned message not found' });
      }

      // Broadcast to chat participants
      try {
        const broadcastFn = (globalThis as any).__broadcastPinnedMessagesUpdate;
        if (broadcastFn) {
          const participants: string[] = chat.participants || [];
          broadcastFn(participants, {
            type: 'pinned_messages_update',
            chatId: chatId,
            action: 'unpin',
            messageUid,
          });
        }
      } catch (broadcastErr) {
          logger.warn({ err: broadcastErr }, '[Unpin] Broadcast failed');
      }

      res.json({ success: true });
    } catch (err: unknown) {
      logger.error({ err }, "Unpin message error");
      res.status(500).json({ error: err.message });
    }
  });

  // Reorder pins
  app.post('/api/chats/:chatId/pins/reorder', requireAuth, validate(PinsReorderSchema), async (req: JwtRequest, res) => {
    try {
      const uid = req.user!.uid;
      const chatId = req.params.chatId;
      const { pins } = req.body;

      const { getChat } = await import('../../src/db/helpers.ts');
      const chat: Record<string, unknown> & { id?: number; type?: string; participants?: string[]; members?: string[]; admins?: string[]; creatorId?: number; creatorUid?: string } = await getChat(chatId);
      if (!chat) return res.status(404).json({ error: 'Chat not found' });

      const { pinnedMessages: pinnedMessagesTable } = await import('../../src/db/schema.ts');
      const { db } = await import('../../src/db/index.ts');
      const { eq } = await import('drizzle-orm');

      for (const pin of pins) {
        await db.update(pinnedMessagesTable)
          .set({ sortOrder: pin.sortOrder })
          .where(eq(pinnedMessagesTable.id, pin.id));
      }
      res.json({ success: true });
    } catch (err: unknown) {
      logger.error({ err }, "Reorder pins error");
      res.status(500).json({ error: err.message });
    }
  });
}