/**
 * Invite tokens store — Redis-backed с fallback на in-memory.
 *
 * Key scheme: invite:token → chatId (string)
 */
import { randomBytes } from 'crypto';
import { getRedis } from './redis.ts';

const PREFIX = 'invite:';
const CHAT_INDEX_PREFIX = 'invite:chat:';

export function generateInviteToken(): string {
  return randomBytes(16).toString('hex');
}

export async function setInviteToken(token: string, chatId: string): Promise<void> {
  const redis = getRedis();
  await redis.set(`${PREFIX}${token}`, chatId);
  // Maintain reverse index for revoke by chatId
  await redis.sAdd(`${CHAT_INDEX_PREFIX}${chatId}`, token);
}

export async function getInviteChatId(token: string): Promise<string | undefined> {
  const redis = getRedis();
  const result = await redis.get(`${PREFIX}${token}`);
  return result ?? undefined;
}

export async function deleteInviteToken(token: string): Promise<void> {
  const redis = getRedis();
  const chatId = await redis.get(`${PREFIX}${token}`);
  await redis.del(`${PREFIX}${token}`);
  if (chatId) {
    await redis.sRem(`${CHAT_INDEX_PREFIX}${chatId}`, token);
  }
}

export async function revokeInviteTokensByChatId(chatId: string): Promise<void> {
  const redis = getRedis();
  const tokens = await redis.sMembers(`${CHAT_INDEX_PREFIX}${chatId}`);
  if (tokens.length > 0) {
    const pipeline = (redis as any).pipeline?.() || null;
    if (pipeline) {
      for (const tok of tokens) {
        pipeline.del(`${PREFIX}${tok}`);
      }
      pipeline.del(`${CHAT_INDEX_PREFIX}${chatId}`);
      await pipeline.exec();
    } else {
      for (const tok of tokens) {
        await redis.del(`${PREFIX}${tok}`);
      }
      await redis.del(`${CHAT_INDEX_PREFIX}${chatId}`);
    }
  }
}