import { db } from './index.ts';
import { accounts, users } from './schema.ts';
import { eq, and } from 'drizzle-orm';

export interface AccountRecord {
  id: number;
  ownerUid: string;
  userUid: string;
  displayName: string | null;
  email: string | null;
  phoneNumber: string | null;
  photoUrl: string | null;
  createdAt: Date | null;
}

/**
 * Получить все аккаунты (профили), привязанные к основному пользователю.
 */
export async function getAccountsByOwnerUid(ownerUid: string): Promise<AccountRecord[]> {
  const result = await db
    .select()
    .from(accounts)
    .where(eq(accounts.ownerUid, ownerUid));
  return result as unknown as AccountRecord[];
}

/**
 * Получить аккаунт по id + owner (для проверки владения).
 */
export async function getAccountByIdAndOwner(id: number, ownerUid: string): Promise<AccountRecord | null> {
  const result = await db
    .select()
    .from(accounts)
    .where(and(eq(accounts.id, id), eq(accounts.ownerUid, ownerUid)))
    .limit(1);
  return (result[0] as unknown as AccountRecord) || null;
}

/**
 * Добавить новый привязанный аккаунт.
 * ownerUid — основной (первичный) пользователь, userUid — привязываемый.
 */
export async function addAccount(data: {
  ownerUid: string;
  userUid: string;
  displayName?: string | null;
  email?: string | null;
  phoneNumber?: string | null;
  photoUrl?: string | null;
}): Promise<AccountRecord> {
  const inserted = await db
    .insert(accounts)
    .values({
      ownerUid: data.ownerUid,
      userUid: data.userUid,
      displayName: data.displayName ?? null,
      email: data.email ?? null,
      phoneNumber: data.phoneNumber ?? null,
      photoUrl: data.photoUrl ?? null,
    })
    .returning();
  return inserted[0] as unknown as AccountRecord;
}

/**
 * Удалить привязанный аккаунт.
 */
export async function removeAccount(id: number, ownerUid: string): Promise<boolean> {
  const result = await db
    .delete(accounts)
    .where(and(eq(accounts.id, id), eq(accounts.ownerUid, ownerUid)))
    .returning();
  return result.length > 0;
}

/**
 * Проверить, привязан ли уже пользователь с данным uid к указанному owner.
 */
export async function isAccountLinked(ownerUid: string, userUid: string): Promise<boolean> {
  const result = await db
    .select({ id: accounts.id })
    .from(accounts)
    .where(and(eq(accounts.ownerUid, ownerUid), eq(accounts.userUid, userUid)))
    .limit(1);
  return result.length > 0;
}

/**
 * Определить uid владельца (main) для текущего пользователя.
 * Если текущий пользователь — основной (сам owner), вернуть его uid.
 * Если текущий пользователь — привязанный, вернуть uid основного.
 * Если пользователь не в группе — вернуть его uid (он сам себе owner).
 */
export async function resolveOwnerUid(currentUid: string): Promise<string> {
  // 1) Проверяем, является ли текущий пользователь owner'ом для кого-то
  const owned = await getAccountsByOwnerUid(currentUid);
  if (owned.length > 0) {
    return currentUid;
  }

  // 2) Проверяем, привязан ли текущий пользователь к кому-то
  const result = await db
    .select({ ownerUid: accounts.ownerUid })
    .from(accounts)
    .where(eq(accounts.userUid, currentUid))
    .limit(1);

  if (result.length > 0) {
    return (result[0] as any).ownerUid;
  }

  // 3) Не привязан ни к кому — он сам себе owner
  return currentUid;
}

/**
 * Найти пользователя по username (для логина нового аккаунта).
 */
export async function findUserByUsername(username: string) {
  const result = await db
    .select()
    .from(users)
    .where(eq(users.username, username))
    .limit(1);
  return (result[0] as any) || null;
}