/**
 * Chat Advanced Routes — V0.8.0 features:
 *   - Username lookup for chats
 *   - Admin permissions (granular)
 *   - Invite links (multiple, with stats)
 *   - Admin action logs
 *   - Members list with search
 *   - Open chat by @username
 */
import { Express } from 'express';
import { JwtRequest } from '../../src/middleware/jwtAuth.ts';
import { requireAuth } from '../../src/middleware/jwtAuth.ts';
import { chatsRateLimit } from '../../src/middleware/security.ts';
import { logger } from '../services/logger.ts';

export function setupChatAdvancedRoutes(app: Express) {
  // ========================================
  // GET /api/chats/by-username/:username — открыть чат/канал по username
  // ========================================
  app.get('/api/chats/by-username/:username', requireAuth, async (req: JwtRequest, res) => {
    try {
      const { username } = req.params;
      if (!username) {
        return res.status(400).json({ error: 'Username is required' });
      }
      const cleanUsername = username.replace(/^@/, '').trim().toLowerCase();
      const { getChatByUsername } = await import('../../src/db/helpers.ts');
      const chat = await getChatByUsername(cleanUsername);
      if (!chat) {
        return res.status(404).json({ error: 'Chat not found by this username' });
      }
      res.json(chat);
    } catch (err: unknown) {
      logger.error({ err }, 'Get chat by username error');
      res.status(500).json({ error: (err as Error).message });
    }
  });

  // ========================================
  // GET /api/chats/:chatId/members/list — список участников с поиском
  // ========================================
  app.get('/api/chats/:chatId/members/list', requireAuth, async (req: JwtRequest, res) => {
    try {
      const uid = req.user!.uid;
      const chatId = req.params.chatId;
      const search = (req.query.search as string) || '';

      const { getChat } = await import('../../src/db/helpers.ts');
      const chat: any = await getChat(chatId);
      if (!chat) {
        return res.status(404).json({ error: 'Chat not found' });
      }

      // Для каналов — список участников только для администраторов
      if (chat.type === 'channel') {
        const { getUserByUid } = await import('../../src/db/auth.ts');
        const userObj = await getUserByUid(uid);
        const isAdmin = chat.admins?.includes(uid);
        const isCreator = chat.creatorId === chat.creatorUid || chat.creatorUid === uid;
        const isGlobalAdmin = userObj?.role === 'admin';
        if (!isAdmin && !isCreator && !isGlobalAdmin) {
          return res.json({ members: [], total: 0 });
        }
      }

      const participantUids: string[] = chat.participants || chat.members || [];
      if (participantUids.length === 0) {
        return res.json({ members: [], total: 0 });
      }

      // Загружаем информацию о пользователях
      const { getUsers } = await import('../../src/db/helpers.ts');
      const allUsers = await getUsers();
      let members = allUsers
        .filter((u: any) => participantUids.includes(u.uid))
        .map((u: any) => ({
          uid: u.uid,
          displayName: u.displayName || u.username || u.uid,
          username: u.username,
          photoURL: u.photoURL,
          status: u.status,
          isCreator: chat.creatorUid === u.uid || chat.creatorId === u.id,
          isAdmin: chat.admins?.includes(u.uid),
        }));

      // Поиск по имени или username
      if (search.trim()) {
        const q = search.toLowerCase().trim();
        members = members.filter(
          (m: any) =>
            m.displayName?.toLowerCase().includes(q) ||
            m.username?.toLowerCase().includes(q)
        );
      }

      res.json({ members, total: members.length });
    } catch (err: unknown) {
      logger.error({ err }, 'Get members list error');
      res.status(500).json({ error: (err as Error).message });
    }
  });

  // ========================================
  // Admin Permissions
  // ========================================

  // GET /api/chats/:chatId/admin-permissions — получить все разрешения
  app.get('/api/chats/:chatId/admin-permissions', requireAuth, async (req: JwtRequest, res) => {
    try {
      const uid = req.user!.uid;
      const chatId = req.params.chatId;

      const { getChat } = await import('../../src/db/helpers.ts');
      const chat: any = await getChat(chatId);
      if (!chat) {
        return res.status(404).json({ error: 'Chat not found' });
      }

      // Только creator или глобальный admin может видеть все разрешения
      const { getUserByUid } = await import('../../src/db/auth.ts');
      const userObj = await getUserByUid(uid);
      const isCreator = chat.creatorUid === uid || chat.creatorId === userObj?.id;
      const isGlobalAdmin = userObj?.role === 'admin';
      if (!isCreator && !isGlobalAdmin) {
        return res.status(403).json({ error: 'Only chat creator can manage admin permissions' });
      }

      const { adminPermissions } = await import('../../src/db/schema.ts');
      const { db } = await import('../../src/db/index.ts');
      const { eq } = await import('drizzle-orm');

      const perms = await db.select().from(adminPermissions)
        .where(eq(adminPermissions.chatId, chat.id));

      res.json(perms);
    } catch (err: unknown) {
      logger.error({ err }, 'Get admin permissions error');
      res.status(500).json({ error: (err as Error).message });
    }
  });

  // POST /api/chats/:chatId/admin-permissions — установить разрешения для пользователя
  app.post('/api/chats/:chatId/admin-permissions', requireAuth, chatsRateLimit, async (req: JwtRequest, res) => {
    try {
      const uid = req.user!.uid;
      const chatId = req.params.chatId;
      const { userUid, ...permissions } = req.body;

      if (!userUid) {
        return res.status(400).json({ error: 'userUid is required' });
      }

      const { getChat } = await import('../../src/db/helpers.ts');
      const chat: any = await getChat(chatId);
      if (!chat) {
        return res.status(404).json({ error: 'Chat not found' });
      }

      const { getUserByUid } = await import('../../src/db/auth.ts');
      const userObj = await getUserByUid(uid);
      const isCreator = chat.creatorUid === uid || chat.creatorId === userObj?.id;
      const isGlobalAdmin = userObj?.role === 'admin';
      if (!isCreator && !isGlobalAdmin) {
        return res.status(403).json({ error: 'Only chat creator can manage admin permissions' });
      }

      const { adminPermissions } = await import('../../src/db/schema.ts');
      const { db } = await import('../../src/db/index.ts');
      const { eq, and } = await import('drizzle-orm');

      // Upsert
      const existing = await db.select().from(adminPermissions)
        .where(and(
          eq(adminPermissions.chatId, chat.id),
          eq(adminPermissions.userUid, userUid)
        ));

      if (existing.length > 0) {
        await db.update(adminPermissions)
          .set({ ...permissions, updatedAt: new Date() })
          .where(eq(adminPermissions.id, existing[0].id));
      } else {
        await db.insert(adminPermissions).values({
          chatId: chat.id,
          userUid,
          ...permissions,
        });
      }

      // Логируем
      const { logAdminAction } = await import('../../src/db/helpers.ts');
      logAdminAction({
        chatId: chat.id,
        actorUid: uid,
        action: 'admin_permissions_changed',
        targetUid: userUid,
        details: permissions,
      });

      res.json({ success: true });
    } catch (err: unknown) {
      logger.error({ err }, 'Set admin permissions error');
      res.status(500).json({ error: (err as Error).message });
    }
  });

  // ========================================
  // Invite Links Management
  // ========================================

  // GET /api/chats/:chatId/invite-links — список ссылок приглашений
  app.get('/api/chats/:chatId/invite-links', requireAuth, async (req: JwtRequest, res) => {
    try {
      const uid = req.user!.uid;
      const chatId = req.params.chatId;

      const { getChat } = await import('../../src/db/helpers.ts');
      const chat: any = await getChat(chatId);
      if (!chat) {
        return res.status(404).json({ error: 'Chat not found' });
      }

      const isAdmin = chat.admins?.includes(uid);
      const isCreator = chat.creatorUid === uid || chat.creatorId === chat.creatorUid;
      if (!isAdmin && !isCreator) {
        return res.status(403).json({ error: 'Only admins can view invite links' });
      }

      const { inviteLinks } = await import('../../src/db/schema.ts');
      const { db } = await import('../../src/db/index.ts');
      const { eq, desc } = await import('drizzle-orm');

      const links = await db.select().from(inviteLinks)
        .where(eq(inviteLinks.chatId, chat.id))
        .orderBy(desc(inviteLinks.createdAt));

      res.json(links);
    } catch (err: unknown) {
      logger.error({ err }, 'Get invite links error');
      res.status(500).json({ error: (err as Error).message });
    }
  });

  // POST /api/chats/:chatId/invite-links — создать новую ссылку
  app.post('/api/chats/:chatId/invite-links', requireAuth, chatsRateLimit, async (req: JwtRequest, res) => {
    try {
      const uid = req.user!.uid;
      const chatId = req.params.chatId;

      const { getChat } = await import('../../src/db/helpers.ts');
      const chat: any = await getChat(chatId);
      if (!chat) {
        return res.status(404).json({ error: 'Chat not found' });
      }

      if (chat.type !== 'group' && chat.type !== 'channel') {
        return res.status(400).json({ error: 'Invite links are only for groups and channels' });
      }

      const isAdmin = chat.admins?.includes(uid);
      const isCreator = chat.creatorUid === uid || chat.creatorId === chat.creatorUid;
      if (!isAdmin && !isCreator) {
        return res.status(403).json({ error: 'Only admins can create invite links' });
      }

      const { generateInviteToken } = await import('../services/invite-store.ts');
      const { inviteLinks } = await import('../../src/db/schema.ts');
      const { db } = await import('../../src/db/index.ts');

      const token = generateInviteToken();
      const result = await db.insert(inviteLinks).values({
        chatId: chat.id,
        token,
        createdBy: uid,
      }).returning();

      const host = req.get('host') || 'localhost:4080';
      const proto = req.protocol || 'http';
      const link = `${proto}://${host}/chat?token=${token}`;

      res.json({ ...result[0], link });
    } catch (err: unknown) {
      logger.error({ err }, 'Create invite link error');
      res.status(500).json({ error: (err as Error).message });
    }
  });

  // DELETE /api/chats/:chatId/invite-links/:linkId — удалить ссылку
  app.delete('/api/chats/:chatId/invite-links/:linkId', requireAuth, async (req: JwtRequest, res) => {
    try {
      const uid = req.user!.uid;
      const { chatId, linkId } = req.params;

      const { getChat } = await import('../../src/db/helpers.ts');
      const chat: any = await getChat(chatId);
      if (!chat) {
        return res.status(404).json({ error: 'Chat not found' });
      }

      const isAdmin = chat.admins?.includes(uid);
      const isCreator = chat.creatorUid === uid;
      if (!isAdmin && !isCreator) {
        return res.status(403).json({ error: 'Only admins can delete invite links' });
      }

      const { inviteLinks } = await import('../../src/db/schema.ts');
      const { db } = await import('../../src/db/index.ts');
      const { eq, and } = await import('drizzle-orm');

      await db.delete(inviteLinks)
        .where(and(
          eq(inviteLinks.id, Number(linkId)),
          eq(inviteLinks.chatId, chat.id)
        ));

      res.json({ success: true });
    } catch (err: unknown) {
      logger.error({ err }, 'Delete invite link error');
      res.status(500).json({ error: (err as Error).message });
    }
  });

  // POST /api/chats/:chatId/invite-links/:linkId/revoke — отозвать ссылку
  app.post('/api/chats/:chatId/invite-links/:linkId/revoke', requireAuth, async (req: JwtRequest, res) => {
    try {
      const uid = req.user!.uid;
      const { chatId, linkId } = req.params;

      const { getChat } = await import('../../src/db/helpers.ts');
      const chat: any = await getChat(chatId);
      if (!chat) {
        return res.status(404).json({ error: 'Chat not found' });
      }

      const isAdmin = chat.admins?.includes(uid);
      const isCreator = chat.creatorUid === uid;
      if (!isAdmin && !isCreator) {
        return res.status(403).json({ error: 'Only admins can revoke invite links' });
      }

      const { inviteLinks } = await import('../../src/db/schema.ts');
      const { db } = await import('../../src/db/index.ts');
      const { eq, and } = await import('drizzle-orm');

      await db.update(inviteLinks)
        .set({ revoked: true, revokedAt: new Date() })
        .where(and(
          eq(inviteLinks.id, Number(linkId)),
          eq(inviteLinks.chatId, chat.id)
        ));

      res.json({ success: true });
    } catch (err: unknown) {
      logger.error({ err }, 'Revoke invite link error');
      res.status(500).json({ error: (err as Error).message });
    }
  });

  // ========================================
  // Admin Logs
  // ========================================

  // GET /api/chats/:chatId/admin-logs — получить логи действий администрации
  app.get('/api/chats/:chatId/admin-logs', requireAuth, async (req: JwtRequest, res) => {
    try {
      const uid = req.user!.uid;
      const chatId = req.params.chatId;
      const limit = Math.min(parseInt(req.query.limit as string) || 50, 200);
      const offset = parseInt(req.query.offset as string) || 0;

      const { getChat } = await import('../../src/db/helpers.ts');
      const chat: any = await getChat(chatId);
      if (!chat) {
        return res.status(404).json({ error: 'Chat not found' });
      }

      // Только владелец и администраторы могут видеть логи
      const { getUserByUid } = await import('../../src/db/auth.ts');
      const userObj = await getUserByUid(uid);
      const isAdmin = chat.admins?.includes(uid);
      const isCreator = chat.creatorUid === uid || chat.creatorId === userObj?.id;
      const isGlobalAdmin = userObj?.role === 'admin';
      if (!isAdmin && !isCreator && !isGlobalAdmin) {
        return res.status(403).json({ error: 'Only admins can view admin logs' });
      }

      const { adminLogs } = await import('../../src/db/schema.ts');
      const { db } = await import('../../src/db/index.ts');
      const { eq, desc: descOrd } = await import('drizzle-orm');

      const logs = await db.select().from(adminLogs)
        .where(eq(adminLogs.chatId, chat.id))
        .orderBy(descOrd(adminLogs.createdAt))
        .limit(limit)
        .offset(offset);

      // Обогащаем логи именами пользователей
      const enrichedLogs = await Promise.all(logs.map(async (log: any) => {
        try {
          const actor = await getUserByUid(log.actorUid);
          let targetName = null;
          if (log.targetUid) {
            const target = await getUserByUid(log.targetUid);
            targetName = target?.displayName || target?.username || log.targetUid;
          }
          return {
            ...log,
            actorName: actor?.displayName || actor?.username || log.actorUid,
            targetName,
          };
        } catch {
          return log;
        }
      }));

      res.json(enrichedLogs);
    } catch (err: unknown) {
      logger.error({ err }, 'Get admin logs error');
      res.status(500).json({ error: (err as Error).message });
    }
  });
}