import { createHmac, createHash, randomBytes, timingSafeEqual } from 'crypto';
import { CSRF_SECRET, MEDIA_SECRET } from '../config.ts';

// ========================================
// Media Signed URLs — HMAC-SHA256 with expiry
// ========================================
export function signMediaUrl(filename: string): { sig: string; exp: number } {
  const exp = Date.now() + 60 * 60 * 1000; // 1 hour
  const sig = createHmac('sha256', MEDIA_SECRET!).update(`${filename}:${exp}`).digest('hex');
  return { sig, exp };
}

export function verifyMediaSignature(filename: string, sig: string, exp: number): boolean {
  if (Date.now() > exp) return false;
  const expected = createHmac('sha256', MEDIA_SECRET!).update(`${filename}:${exp}`).digest('hex');
  try {
    return timingSafeEqual(Buffer.from(sig, 'hex'), Buffer.from(expected, 'hex'));
  } catch {
    return false;
  }
}

// ========================================
// CSRF Protection
// ========================================
export function generateCsrfToken(): string {
  return randomBytes(32).toString('hex');
}

export function signCsrfToken(token: string): string {
  return createHmac('sha256', CSRF_SECRET!).update(token).digest('hex');
}

// ========================================
// Content Hash
// ========================================
export const getContentHash = (buffer: Buffer) => {
  return createHash('sha256').update(buffer).digest('hex');
};