import rateLimit from 'express-rate-limit';
import { Request, Response, NextFunction } from 'express';

// ========================================
// Security Headers Middleware
// ========================================
export function securityHeaders(req: Request, res: Response, next: NextFunction) {
  const isDev = process.env.NODE_ENV !== 'production' && !process.env.FORCE_CSP_STRICT;

  // Content Security Policy
  const scriptSrc = isDev
    ? "script-src 'self' 'unsafe-inline' 'unsafe-eval' https://meet.jit.si https://8x8.vc"
    : "script-src 'self' https://meet.jit.si https://8x8.vc";

  res.setHeader('Content-Security-Policy', [
    "default-src 'self'",
    scriptSrc,
    "style-src 'self' 'unsafe-inline' https://fonts.googleapis.com",
    "img-src 'self' data: blob: https://*.googleapis.com https://*.gstatic.com https://*.giphy.com https://media.giphy.com https://tenor.googleapis.com https://fonts.gstatic.com https://cdn.jsdelivr.net https://cdnjs.cloudflare.com https://i.ytimg.com https://*.ytimg.com https://archive.org https://*.archive.org https://*.audius.co https://*.radio-browser.info https://*.invidious.* https://yewtu.be https://*.googleusercontent.com https://www.transparenttextures.com",
    "font-src 'self' data: https://fonts.gstatic.com",
    "connect-src 'self' wss: ws: https://fonts.googleapis.com https://fonts.gstatic.com https://tenor.googleapis.com https://fcm.googleapis.com https://api.giphy.com https://archive.org https://*.archive.org https://*.audius.co https://discoveryprovider.audius.co https://*.radio-browser.info https://*.invidious.* https://pipedapi.kavin.rocks https://pipedapi.tokhmi.xyz https://api.piped.private.coffee",
    "media-src 'self' blob: data: https://archive.org https://*.archive.org https://*.audius.co https://*.radio-browser.info https://*.googlevideo.com https://*.ytimg.com https://*.radio.co https://*.radioca.st https://*.stream.radioreference.com https:",
    "frame-src 'self' https://meet.jit.si https://meet.ffmuc.net https://jitsi.linux.it https://jitsi.riot.im https://jitsi.hamburg.ccc.de",
    "worker-src 'self' blob:",
    "frame-ancestors 'none'",
    "base-uri 'self'",
    "form-action 'self'",
  ].join('; '));

  // Prevent clickjacking
  res.setHeader('X-Frame-Options', 'DENY');

  // Prevent MIME type sniffing
  res.setHeader('X-Content-Type-Options', 'nosniff');

  // XSS Protection (legacy browsers)
  res.setHeader('X-XSS-Protection', '1; mode=block');

  // Referrer Policy — no-referrer предотвращает утечку JWT токенов в Referer header
  res.setHeader('Referrer-Policy', 'no-referrer');

  // Strict Transport Security (HTTPS only in production)
  if (process.env.NODE_ENV === 'production' || process.env.FORCE_HSTS === 'true') {
    res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains; preload');
  }

  // Permissions Policy — restrict browser features
  res.setHeader('Permissions-Policy', [
    'camera=()',
    'microphone=(self)',
    'geolocation=()',
    'payment=()',
    'usb=()',
    'magnetometer=()',
    'gyroscope=()',
    'accelerometer=()',
    'autoplay=(self)',
  ].join(', '));

  // Cross-Origin policies
  res.setHeader('Cross-Origin-Opener-Policy', 'same-origin');
  res.setHeader('Cross-Origin-Resource-Policy', 'same-origin');

  // Remove fingerprinting headers
  res.removeHeader('X-Powered-By');

  next();
}

// ========================================
// Rate Limiting — express-rate-limit
// ========================================

/**
 * Проверяет, является ли пользователь администратором (role === 'admin').
 * Admin пользователи освобождаются от rate limiting.
 */
function isAdmin(req: Request): boolean {
  try {
    const user = (req as any).user;
    if (user?.role === 'admin') return true;
    // Также проверяем через JWT payload, если middleware requireAuth ещё не отработал
    if (user?.uid) return false;
    return false;
  } catch {
    return false;
  }
}

/**
 * Кастомный key generator: для авторизованных пользователей используется user uid,
 * для неавторизованных — IP-адрес.
 */
function userKeyGenerator(req: Request): string {
  const user = (req as any).user;
  if (user?.uid) return `user:${user.uid}`;
  const ip = req.ip || req.socket?.remoteAddress || 'unknown';
  return `ip:${ip}`;
}

/**
 * Кастомный key generator: всегда по IP-адресу.
 */
function ipKeyGenerator(req: Request): string {
  const ip = req.ip || req.socket?.remoteAddress || 'unknown';
  return `ip:${ip}`;
}

/**
 * Формат ответа при превышении лимита (на русском языке).
 */
function rateLimitResponse(_req: Request, res: Response, _next: NextFunction, options: any) {
  res.status(429).json({
    error: options.message || 'Слишком много запросов. Пожалуйста, попробуйте позже.',
  });
}

// ========================================
// 1) /api/auth/login — 5 запросов в минуту с одного IP
// ========================================
export const loginRateLimit = rateLimit({
  windowMs: 60 * 1000, // 1 минута
  max: 5,
  standardHeaders: true,
  legacyHeaders: false,
  keyGenerator: ipKeyGenerator,
  skip: isAdmin,
  message: 'Слишком много попыток входа. Пожалуйста, попробуйте через минуту.',
  handler: rateLimitResponse,
  validate: false,
});

