// ========================================
// 6) Все остальные API — 200 запросов в минуту (по IP)
// Глобальный safety-net лимит. Конкретные маршруты имеют
// собственные, более строгие лимиты (messages, chats и т.д.).
// Лимит повышен до 200, чтобы не блокировать нормальную работу
// приложения: загрузка страницы + poll + отправка сообщений
// в сумме легко превышают 60 запросов за минуту.
// ========================================
export const defaultApiRateLimit = rateLimit({
  windowMs: 60 * 1000, // 1 минута
  max: 200,
  standardHeaders: true,
  legacyHeaders: false,
  keyGenerator: ipKeyGenerator,
  skip: isAdmin,
  message: 'Превышен лимит запросов. Пожалуйста, подождите перед повторным обращении.',
  handler: rateLimitResponse,
  validate: false,
});

