import { execFile } from 'child_process';
import fs from 'fs';
import path from 'path';
import ffmpegPath from 'ffmpeg-static';
import { logger } from './logger.ts';

const rawFfmpegPath = ffmpegPath as unknown as string | null;
export const FFMPEG_PATH: string | null = (rawFfmpegPath && fs.existsSync(rawFfmpegPath)) ? rawFfmpegPath : null;

if (FFMPEG_PATH) {
  logger.info(`[FFmpeg] ✅ Using bundled ffmpeg-static binary: ${FFMPEG_PATH}`);
} else {
  logger.info('[FFmpeg] ℹ️ ffmpeg binary not found on disk, skipping video transcoding and keeping original files');
}

const runFFmpeg = (args: string[]): Promise<boolean> => {
  return new Promise((resolve) => {
    if (!FFMPEG_PATH) return resolve(false);
    execFile(FFMPEG_PATH, args, { timeout: 180000, maxBuffer: 10 * 1024 * 1024 }, (error) => {
      if (error) {
        logger.warn({ err: error.message }, '[FFmpeg] execFile failed');
        resolve(false);
      } else {
        resolve(true);
      }
    });
  });
};

export const processVideoWithFFmpeg = async (filePath: string): Promise<string> => {
  if (!FFMPEG_PATH || !fs.existsSync(filePath)) {
    logger.info({ filePath: filePath }, '[FFmpeg] ffmpeg not available or file missing, keeping original file:');
    return filePath;
  }

  const ext = path.extname(filePath).toLowerCase();
  const dir = path.dirname(filePath);
  const base = path.basename(filePath, ext);
  const mp4Path = path.join(dir, `${base}_faststart.mp4`);
  logger.info(`[FFmpeg] 🎬 Processing video for maximum browser compatibility: ${path.basename(filePath)}`);

  const isValidOutput = (outPath: string): boolean => {
    if (!fs.existsSync(outPath)) return false;
    const size = fs.statSync(outPath).size;
    return size > 500;
  };

  const isVideoNote = filePath.toLowerCase().includes('video_note');
  const cropArgs = isVideoNote ? ['-vf', 'crop=min(iw\\,ih):min(iw\\,ih)'] : [];

  // Strategy 1: Standard H.264 + AAC + faststart MP4
  const strategy1Args = [
    '-y',
    '-analyzeduration', '100M',
    '-probesize', '100M',
    '-i', filePath,
    ...cropArgs,
    '-c:v', 'libx264',
    '-preset', 'ultrafast',
    '-crf', '28',
    '-pix_fmt', 'yuv420p',
    '-c:a', 'aac',
    '-b:a', '96k',
    '-ac', '2',
    '-max_muxing_queue_size', '1024',
    '-movflags', '+faststart',
    mp4Path,
  ];

  if (await runFFmpeg(strategy1Args) && isValidOutput(mp4Path)) {
    logger.info(`[FFmpeg] ✅ Strategy 1 (H.264/AAC MP4) success: ${path.basename(mp4Path)} (${fs.statSync(mp4Path).size} bytes)`);
    try { if (fs.existsSync(filePath) && !filePath.includes('_faststart')) fs.unlinkSync(filePath); } catch (_) {}
    return mp4Path;
  }

  // Strategy 2: H.264 video only without audio
  const strategy2Args = [
    '-y',
    '-analyzeduration', '100M',
    '-probesize', '100M',
    '-i', filePath,
    '-c:v', 'libx264',
    '-preset', 'ultrafast',
    '-crf', '28',
    '-pix_fmt', 'yuv420p',
    '-an',
    '-movflags', '+faststart',
    mp4Path,
  ];

  if (await runFFmpeg(strategy2Args) && isValidOutput(mp4Path)) {
    logger.info(`[FFmpeg] ✅ Strategy 2 (Video-only H.264 MP4) success: ${path.basename(mp4Path)} (${fs.statSync(mp4Path).size} bytes)`);
    try { if (fs.existsSync(filePath) && !filePath.includes('_faststart')) fs.unlinkSync(filePath); } catch (_) {}
    return mp4Path;
  }

  // Strategy 3: WebM fallback
  const webmPath = path.join(dir, `${base}_fallback.webm`);
  const strategy3Args = [
    '-y',
    '-i', filePath,
    '-c:v', 'libvpx',
    '-crf', '30',
    '-b:v', '0',
    '-c:a', 'libvorbis',
    '-b:a', '64k',
    webmPath,
  ];

  if (await runFFmpeg(strategy3Args) && isValidOutput(webmPath)) {
    logger.info(`[FFmpeg] ✅ Strategy 3 (WebM re-encode) success: ${path.basename(webmPath)} (${fs.statSync(webmPath).size} bytes)`);
    try { if (fs.existsSync(filePath) && !filePath.includes('_faststart')) fs.unlinkSync(filePath); } catch (_) {}
    return webmPath;
  }

  logger.info('[FFmpeg] ⚠️ All transcoding strategies failed, keeping original file');
  if (fs.existsSync(mp4Path)) try { fs.unlinkSync(mp4Path); } catch (_) {}
  if (fs.existsSync(webmPath)) try { fs.unlinkSync(webmPath); } catch (_) {}
  return filePath;
};

export const shouldTranscodeVideo = (filename: string) => {
  const lower = filename.toLowerCase();
  return lower.includes('video_note') ||
         lower.includes('video') ||
         lower.endsWith('.webm') ||
         lower.endsWith('.mp4') ||
         lower.endsWith('.mov') ||
         lower.endsWith('.qt') ||
         lower.endsWith('.avi') ||
         lower.endsWith('.mkv') ||
         lower.endsWith('.3gp');
};