/**
 * Admin routes — фасад, подключающий подмодули:
 *   - admin-users.ts   (пользователи, роли, сессии, проверка панели)
 *   - admin-messages.ts (сообщения, чаты, поиск, стикер-паки)
 *   - admin-reports.ts  (жалобы, аудит, broadcast, статистика)
 */
import { Express } from 'express';
import { setupAdminUserRoutes } from './admin-users.ts';
import { setupAdminMessageRoutes } from './admin-messages.ts';
import { setupAdminReportRoutes } from './admin-reports.ts';

export async function setupAdminRoutes(app: Express) {
  await setupAdminUserRoutes(app);
  await setupAdminMessageRoutes(app);
  await setupAdminReportRoutes(app);
}