import bcrypt from 'bcryptjs';
import { db } from './index.ts';
import { users } from './schema.ts';
import { AppUser } from '../lib/types.ts';
import { eq } from 'drizzle-orm';

export async function getUserByEmail(email: string): Promise<(AppUser & { passwordHash: string | null }) | null> {
  const result = await db.select().from(users).where(eq(users.email, email)).limit(1);
  return (result[0] as any) || null;
}

export async function getUserByUsername(username: string): Promise<(AppUser & { passwordHash: string | null }) | null> {
  const result = await db.select().from(users).where(eq(users.username, username)).limit(1);
  return (result[0] as any) || null;
}

export async function getUserByUid(uid: string): Promise<AppUser | null> {
  const result = await db.select().from(users).where(eq(users.uid, uid)).limit(1);
  if (!result[0]) return null;
  const { passwordHash, ...user } = result[0] as any;
  return user as AppUser;
}

export async function createUserWithPassword(data: {
  uid: string;
  email: string;
  password: string;
  username?: string | null;
  displayName?: string | null;
  photoURL?: string | null;
  status?: string | null;
}): Promise<AppUser> {
  const passwordHash = await bcrypt.hash(data.password, 10);
  // PGlite/sqlite не понимает drizzle default, генерируем id в 32-битном диапазоне
  const idCandidate = Math.floor(Math.random() * 2147483647);
  const inserted = await db.insert(users)
    .values({
      id: idCandidate,
      uid: data.uid,
      email: data.email,
      username: data.username || null,
      displayName: data.displayName || null,
      photoURL: data.photoURL || null,
      status: data.status || 'online',
      lastSeen: new Date(),
      passwordHash,
    })
    .returning();

  const { passwordHash: _, ...user } = inserted[0] as any;
  return user as AppUser;
}

export async function verifyUserPassword(email: string, password: string): Promise<AppUser | null> {
  const result = await db.select().from(users).where(eq(users.email, email)).limit(1);
  const row = result[0] as any;
  if (!row || !row.passwordHash) return null;

  const isValid = await bcrypt.compare(password, row.passwordHash);
  if (!isValid) return null;

  const { passwordHash, ...user } = row;
  return user as AppUser;
}
