import { Express } from 'express';
import { JwtRequest } from '../../src/middleware/jwtAuth.ts';
import { requireAuth } from '../../src/middleware/jwtAuth.ts';
import { validate, PushSubscribeSchema, PushUnsubscribeSchema } from '../../src/middleware/validate.ts';
import { logger } from '../services/logger.ts';
import {
  getVapidPublicKey,
  saveSubscription,
  removeSubscription,
} from '../../src/lib/push.ts';

export function setupPushRoutes(app: Express) {
  app.get("/api/push/vapid-key", (req, res) => {
    res.json({ publicKey: getVapidPublicKey() });
  });

  app.post("/api/push/subscribe", requireAuth, validate(PushSubscribeSchema), async (req: JwtRequest, res) => {
    try {
      const uid = req.user!.uid;
      const { subscription, userAgent } = req.body;
      const { getUserByUid } = await import("../../src/db/auth.ts");
      const user = await getUserByUid(uid);
      if (!user) {
        return res.status(404).json({ error: "User not found" });
      }
      await saveSubscription(user.id, subscription.endpoint, subscription, userAgent);
      res.json({ success: true });
    } catch (err: unknown) {
      logger.error({ err }, "Subscribe error");
      res.status(500).json({ error: err.message });
    }
  });

  app.post("/api/push/unsubscribe", requireAuth, validate(PushUnsubscribeSchema), async (req: JwtRequest, res) => {
    try {
      const { endpoint } = req.body;
      await removeSubscription(endpoint);
      res.json({ success: true });
    } catch (err: unknown) {
      logger.error({ err }, "Unsubscribe error");
      res.status(500).json({ error: err.message });
    }
  });

  app.post("/api/push/validate", requireAuth, async (req: JwtRequest, res) => {
    try {
      const { endpoint } = req.body;
      if (!endpoint) {
        return res.status(400).json({ valid: false, error: "Missing endpoint" });
      }
      const { validateSubscriptionExists } = await import("../../src/lib/push.ts");
      const exists = await validateSubscriptionExists(endpoint);
      res.json({ valid: exists });
    } catch (err: unknown) {
      logger.error({ err }, "Validate subscription error");
      res.json({ valid: true });
    }
  });
}