import { Request, Response, NextFunction } from 'express';
import { verifyJwt } from '../lib/auth.ts';
import { isSessionActive, touchSession } from '../db/sessions.ts';

export interface JwtRequest extends Request {
  user?: { uid: string; email: string; sessionUid?: string; isAdmin?: boolean; role?: string };
}

/**
 * Global JWT authentication middleware.
 * Extracts JWT from Authorization: Bearer header, verifies it,
 * populates req.user with user data. Returns 401 if token is missing/invalid/expired.
 * Applied globally to all /api routes (with exclusions for public endpoints).
 */
export const authenticateToken = async (
  req: JwtRequest,
  res: Response,
  next: NextFunction
) => {
  // Если уже аутентифицированы (например, родительским middleware) — пропускаем
  if (req.user?.uid) return next();

  let token = '';
  const authHeader = req.headers.authorization;
  if (authHeader && authHeader.startsWith('Bearer ')) {
    token = authHeader.split('Bearer ')[1];
  }
  // Query string разрешён ТОЛЬКО для путей загрузки медиа файлов,
  // т.к. <img>/<video> элементы не могут передавать заголовки Authorization.
  else if (req.query && typeof req.query.token === 'string') {
    const requestPath = req.path || '';
    if (/^\/(api\/download|uploads)\//.test(requestPath)) {
      token = req.query.token;
    }
  }

  if (!token) {
    return res.status(401).json({ error: 'Unauthorized: Missing token' });
  }

  try {
    const decoded = verifyJwt(token);
    req.user = { uid: decoded.uid, email: decoded.email, sessionUid: decoded.sessionUid };

    // Проверяем активность сессии (если sessionUid есть в токене)
    if (decoded.sessionUid) {
      const active = await isSessionActive(decoded.sessionUid);
      if (!active) {
        return res.status(401).json({ error: 'Unauthorized: Session revoked' });
      }
      // Обновляем last_active (fire-and-forget, не блокируя запрос)
      touchSession(decoded.sessionUid).catch(() => {});
    }

    next();
  } catch (error) {
    console.error('Error verifying JWT token:', error);
    return res.status(401).json({ error: 'Unauthorized: Invalid token' });
  }
};

/**
 * Route-level auth middleware — short-circuits if authenticateToken already ran.
 * Used as a safety net on individual routes that need explicit auth annotation.
 */
export const requireAuth = async (
  req: JwtRequest,
  res: Response,
  next: NextFunction
) => {
  // Если уже аутентифицированы глобальным middleware — пропускаем
  if (req.user?.uid) return next();

  // Иначе выполняем полную проверку
  authenticateToken(req, res, next);
};
