/**
 * Global error handler middleware.
 *
 * - AppError → { error: message, code, statusCode }
 * -未知 ошибки → 500
 */

export class AppError extends Error {
  public readonly statusCode: number;
  public readonly code: string;

  constructor(message: string, statusCode: number = 500, code?: string) {
    super(message);
    this.name = 'AppError';
    this.statusCode = statusCode;
    this.code = code || `ERR_${statusCode}`;
    // Сохраняем правильный prototype chain
    Object.setPrototypeOf(this, new.target.prototype);
  }

  // Удобные статические фабрики
  static badRequest(message: string, code?: string) {
    return new AppError(message, 400, code || 'BAD_REQUEST');
  }

  static unauthorized(message: string = 'Unauthorized', code?: string) {
    return new AppError(message, 401, code || 'UNAUTHORIZED');
  }

  static forbidden(message: string = 'Forbidden', code?: string) {
    return new AppError(message, 403, code || 'FORBIDDEN');
  }

  static notFound(message: string = 'Not found', code?: string) {
    return new AppError(message, 404, code || 'NOT_FOUND');
  }

  static conflict(message: string, code?: string) {
    return new AppError(message, 409, code || 'CONFLICT');
  }

  static tooMany(message: string = 'Too many requests', code?: string) {
    return new AppError(message, 429, code || 'TOO_MANY_REQUESTS');
  }
}

/**
 * Express error middleware — ловит AppError и неизвестные ошибки.
 *
 * Использование в route handlers:
 *   throw new AppError('Not found', 404);
 *   throw AppError.badRequest('Missing field');
 *
 * Не используйте next(err) — просто throw, middleware поймает.
 */
export function errorHandler(err: any, _req: any, res: any, _next: any) {
  // AppError
  if (err instanceof AppError) {
    return res.status(err.statusCode).json({
      error: err.message,
      code: err.code,
    });
  }

  // Multer / ValidationError
  if (err.name === 'MulterError') {
    return res.status(400).json({
      error: err.message || 'Upload error',
      code: 'UPLOAD_ERROR',
    });
  }

  // SyntaxError from JSON body parser
  if (err instanceof SyntaxError && 'body' in err) {
    return res.status(400).json({
      error: 'Invalid JSON',
      code: 'INVALID_JSON',
    });
  }

  // Неизвестная ошибка
  console.error('[ErrorHandler] Unhandled error:', err);
  return res.status(500).json({
    error: process.env.NODE_ENV === 'production' ? 'Internal server error' : err.message,
    code: 'INTERNAL_ERROR',
  });
}