// --- User Helpers ---

export async function syncUser(uid: string, data: {
  email: string;
  displayName?: string;
  photoURL?: string;
  status?: string;
  bio?: string;
  username?: string;
  phoneNumber?: string;
}) {
  try {
    const existing = await db.select().from(users).where(eq(users.uid, uid)).limit(1);
    const updatePayload: any = {
      email: data.email,
      lastSeen: new Date(),
      updatedAt: new Date(),
    };
    if (data.displayName !== undefined) updatePayload.displayName = data.displayName;
    if (data.photoURL !== undefined) updatePayload.photoURL = data.photoURL;
    if (data.status !== undefined) updatePayload.status = data.status;
    if (data.bio !== undefined) updatePayload.bio = data.bio;
    if (data.username !== undefined) updatePayload.username = data.username;
    if (data.phoneNumber !== undefined) updatePayload.phoneNumber = data.phoneNumber;

    let userData: any;
    if (existing.length > 0) {
      const result = await db.update(users)
        .set(updatePayload)
        .where(eq(users.uid, uid))
        .returning();
      userData = result[0];
    } else {
      const result = await db.insert(users)
        .values({
          uid,
          email: data.email,
          displayName: data.displayName || null,
          photoURL: data.photoURL || null,
          status: data.status || 'online',
          bio: data.bio || null,
          username: data.username || null,
          phoneNumber: data.phoneNumber || null,
        })
        .returning();
      userData = result[0];
    }
    
    const { passwordHash, ...safeUser } = userData;
    return safeUser;
  } catch (error) {
    console.error("Error in syncUser:", error);
    throw new Error("Failed to sync user in database", { cause: error });
  }
}

export async function getUsers() {
  try {
    const allUsers = await db.select().from(users);
    return allUsers.map((user: any) => {
      const { passwordHash, ...safeUser } = user;
      return safeUser;
    });
  } catch (error) {
    console.error("Error in getUsers:", error);
    throw new Error("Failed to fetch users", { cause: error });
  }
}

export async function getUser(uid: string) {
  try {
    const result = await db.select().from(users).where(eq(users.uid, uid)).limit(1);
    if (!result[0]) return null;
    const { passwordHash, ...safeUser } = result[0] as any;
    return safeUser;
  } catch (error) {
    console.error("Error in getUser:", error);
    throw new Error("Failed to fetch user", { cause: error });
  }
}

// --- Chat Helpers ---

export async function getChat(chatId: string | number) {
  try {
    let result;
    if (typeof chatId === 'string') {
      // Поиск по chat_uid
      result = await db.select().from(chats).where(eq(chats.chatUid, chatId)).limit(1);
      // Если не нашли по chatUid — пробуем по numeric id (chatId может быть строкой-числом)
      if (!result[0]) {
        const numericId = parseInt(chatId);
        if (!isNaN(numericId)) {
          result = await db.select().from(chats).where(eq(chats.id, numericId)).limit(1);
        }
      }
    } else {
      // Поиск по numeric id
      result = await db.select().from(chats).where(eq(chats.id, chatId)).limit(1);
    }
    return result[0] || null;
  } catch (error) {
    console.error("Error in getChat:", error);
    throw new Error("Failed to fetch chat", { cause: error });
  }
}

