export async function isChatUsernameTaken(username: string, excludeChatId?: number): Promise<boolean> {
  try {
    const conditions = [eq(chats.username, username)];
    if (excludeChatId) {
      // Need to exclude current chat when updating
      const { not, eq: eqFn } = await import('drizzle-orm');
      const result = await db.select({ id: chats.id }).from(chats).where(
        eqFn(chats.username, username)
      ).limit(5);
      return result.some((r: any) => r.id !== excludeChatId);
    }
    const result = await db.select({ id: chats.id }).from(chats).where(
      eq(chats.username, username)
    ).limit(1);
    return result.length > 0;
  } catch (error) {
    console.error("Error in isChatUsernameTaken:", error);
    return false;
  }
}

