// --- Message Helpers ---

export async function getMessagesForChat(chatId: string | number, limit = 50, offset = 0) {
  try {
    let chatNumericId: number;
    if (typeof chatId === 'string') {
      let chatResult = await db.select({ id: chats.id }).from(chats).where(eq(chats.chatUid, chatId)).limit(1);
      // Если не нашли по chatUid — пробуем по numeric id
      if (!chatResult[0]) {
        const numericId = parseInt(chatId);
        if (!isNaN(numericId)) {
          chatResult = await db.select({ id: chats.id }).from(chats).where(eq(chats.id, numericId)).limit(1);
        }
      }
      if (!chatResult[0]) {
        return [];
      }
      chatNumericId = chatResult[0].id;
    } else {
      chatNumericId = chatId;
    }

    // Получаем сообщения с JOIN к users чтобы получить sender UID
    const msgs = await db.select({
      id: messages.msgUid, // возвращаем msgUid как id для фронтенда
      msgUid: messages.msgUid,
      idNumeric: messages.id, // добавляем numeric ID для reports
      chatId: messages.chatId,
      senderId: users.uid, // возвращаем UID пользователя вместо numeric ID
      senderNumericId: messages.senderId, // на всякий случай
      senderName: messages.senderName,
      senderAvatar: messages.senderAvatar,
      text: messages.text,
      fileUrl: messages.fileUrl,
      fileName: messages.fileName,
      fileType: messages.fileType,
      type: messages.type,
      duration: messages.duration,
      replyTo: messages.replyTo,
      timestamp: messages.createdAt, // фронтенд ожидает timestamp
      createdAt: messages.createdAt,
      reactions: messages.reactions,
      editedAt: messages.editedAt,
    })
      .from(messages)
      .leftJoin(users, eq(messages.senderId, users.id))
      .where(eq(messages.chatId, chatNumericId))
      .orderBy(messages.createdAt)
      .limit(limit)
      .offset(offset);

    // Attach comment counts
    const msgNumericIds = msgs.map((m: any) => m.idNumeric).filter(Boolean);
    const commentCountsMap = new Map<number, number>();
    if (msgNumericIds.length > 0) {
      try {
        const { inArray, sql: drizzleSql } = await import('drizzle-orm');
        const cResult = await db.select({
          messageId: comments.messageId,
          count: drizzleSql<number>`count(*)::int`
        }).from(comments)
          .where(inArray(comments.messageId, msgNumericIds as number[]))
          .groupBy(comments.messageId);
        for (const row of cResult) {
          commentCountsMap.set(row.messageId, Number(row.count) || 0);
        }
      } catch (cErr) {
        // ignore non-fatal
      }
    }

    return msgs.map((m: any) => ({
      ...m,
      senderId: (m.type === 'channel_post') ? `channel_${m.chatId}` : m.senderId,
      isChannelPost: m.type === 'channel_post',
      commentCount: commentCountsMap.get(m.idNumeric) || 0,
    }));
  } catch (error) {
    console.error("Error in getMessagesForChat:", error);
    throw new Error("Failed to fetch messages", { cause: error });
  }
}

export async function getMessagesCount(chatId: string | number) {
  try {
    let chatNumericId: number;
    if (typeof chatId === 'string') {
      const chatResult = await db.select({ id: chats.id }).from(chats).where(eq(chats.chatUid, chatId)).limit(1);
      if (!chatResult[0]) return 0;
      chatNumericId = chatResult[0].id;
    } else {
      chatNumericId = chatId;
    }
    
    const result = await db.select({ count: sql<number>`count(*)` })
      .from(messages)
      .where(eq(messages.chatId, chatNumericId));
    return result[0]?.count || 0;
  } catch (error) {
    console.error("Error in getMessagesCount:", error);
    return 0;
  }
}

export async function createMessage(msg: {
  msgUid: string;
  chatId: string | number;
  senderId: number;
  senderName?: string;
  senderAvatar?: string;
  text?: string;
  fileUrl?: string;
  fileName?: string;
  fileType?: string;
  type?: string;
  duration?: number;
  replyTo?: string;
}) {
  try {
    // Resolve chat numeric ID
    let chatNumericId: number;
    if (typeof msg.chatId === 'string') {
      // Try chatUid lookup first
      let chatResult = await db.select({ id: chats.id }).from(chats).where(eq(chats.chatUid, msg.chatId)).limit(1);
      
      if (!chatResult[0]) {
        // If the chatId is a numeric string, try numeric ID lookup
        const maybeNumeric = parseInt(msg.chatId);
        if (!isNaN(maybeNumeric)) {
          chatResult = await db.select({ id: chats.id }).from(chats).where(eq(chats.id, maybeNumeric)).limit(1);
        }
      }

      if (!chatResult[0]) {
        // Create chat if not exists
        let chatType = 'private';
        let participants: string[] = [];
        if (msg.chatId === 'global_chat') {
          chatType = 'public';
        } else if (msg.chatId.startsWith('private_')) {
          const parts = msg.chatId.split('_');
          participants = parts.slice(1);
        } else {
          participants = [msg.senderId.toString()];
        }

        const chatIdCandidate = Math.floor(Math.random() * 2147483647);
        const newChat = await db.insert(chats).values({
          id: chatIdCandidate,
          chatUid: msg.chatId,
          type: chatType,
          name: msg.chatId === 'global_chat' ? 'Общий Чат' : null,
          participants: participants,
          members: participants,
          updatedAt: new Date(),
        }).returning();
        
        chatNumericId = newChat[0].id;
      } else {
        chatNumericId = chatResult[0].id;
      }
    } else {
      chatNumericId = msg.chatId;
    }

    // Generate numeric ID explicitly for PGLite compatibility
    const messageNumericId = Math.floor(Math.random() * 2147483647);
    
    // Insert message with explicit numeric ID
    const result = await db.insert(messages)
      .values({
        id: messageNumericId,
        msgUid: msg.msgUid,
        chatId: chatNumericId,
        senderId: msg.senderId,
        senderName: msg.senderName || null,
        senderAvatar: msg.senderAvatar || null,
        text: msg.text || null,
        fileUrl: msg.fileUrl || null,
        fileName: msg.fileName || null,
        fileType: msg.fileType || null,
        type: msg.type || 'text',
        duration: msg.duration || null,
        replyTo: msg.replyTo || null,
      })
      .returning();

    // Update chat lastMessage
    const messageSnapshot = result[0];
    await db.update(chats)
      .set({
        lastMessage: {
          text: messageSnapshot.text || (messageSnapshot.type === 'voice' ? 'Голосовое сообщение' : 'Вложение'),
          senderId: messageSnapshot.senderId,
          senderName: messageSnapshot.senderName,
          timestamp: messageSnapshot.createdAt ? messageSnapshot.createdAt.toISOString() : new Date().toISOString(),
        },
        updatedAt: new Date(),
      })
      .where(eq(chats.id, chatNumericId));

    return messageSnapshot;
  } catch (error) {
    console.error("Error in createMessage:", error);
    throw new Error("Failed to create message", { cause: error });
  }
}

export async function deleteMessage(msgId: string | number) {
  try {
    if (typeof msgId === 'string') {
      return await db.delete(messages).where(eq(messages.msgUid, msgId)).returning();
    } else {
      return await db.delete(messages).where(eq(messages.id, msgId)).returning();
    }
  } catch (error) {
    console.error("Error in deleteMessage:", error);
    throw new Error("Failed to delete message", { cause: error });
  }
}

export async function editMessage(msgUid: string, senderUid: string, newText: string) {
  try {
    // Проверяем существование сообщения и право на редактирование
    const existing = await db.select({
      id: messages.id,
      msgUid: messages.msgUid,
      senderId: messages.senderId,
    }).from(messages).where(eq(messages.msgUid, msgUid)).limit(1);

    if (!existing[0]) {
      throw new Error("Message not found");
    }

    // Проверяем, что редактирует автор сообщения или админ
    const sender = await db.select({ id: users.id, role: users.role }).from(users).where(eq(users.uid, senderUid)).limit(1);
    if (!sender[0]) {
      throw new Error("User not found");
    }

    const isAdmin = sender[0].role === 'admin';
    const isOwner = existing[0].senderId === sender[0].id;
    if (!isOwner && !isAdmin) {
      throw new Error("You can only edit your own messages");
    }

    const result = await db.update(messages)
      .set({
        text: newText,
        editedAt: new Date(),
      })
      .where(eq(messages.msgUid, msgUid))
      .returning();

    return result[0];
  } catch (error) {
    console.error("Error in editMessage:", error);
    throw new Error("Failed to edit message", { cause: error });
  }
}

// --- Comment Helpers ---

export async function getCommentsForMessage(msgId: string | number) {
  try {
    let numericId: number;
    if (typeof msgId === 'string') {
      const parsed = parseInt(msgId);
      if (!isNaN(parsed) && String(parsed) === msgId) {
        numericId = parsed;
      } else {
        const found = await db.select({ id: messages.id }).from(messages).where(eq(messages.msgUid, msgId)).limit(1);
        if (!found[0]) return [];
        numericId = found[0].id;
      }
    } else {
      numericId = msgId;
    }

    const cmts = await db.select({
      id: comments.commentUid,
      commentUid: comments.commentUid,
      idNumeric: comments.id,
      messageId: comments.messageId,
      chatId: comments.chatId,
      userId: users.uid,
      userNumericId: comments.userId,
      userName: users.displayName,
      username: users.username,
      userAvatar: users.photoURL,
      senderName: users.displayName,
      senderAvatar: users.photoURL,
      text: comments.text,
      createdAt: comments.createdAt,
      timestamp: comments.createdAt,
    })
      .from(comments)
      .leftJoin(users, eq(comments.userId, users.id))
      .where(eq(comments.messageId, numericId))
      .orderBy(comments.createdAt);

    return cmts.map((c: any) => ({
      ...c,
      id: c.commentUid || String(c.idNumeric),
      userId: c.userId || String(c.userNumericId),
      userName: c.userName || c.username || 'user',
      senderName: c.senderName || c.username || 'user',
      username: c.username || '',
      userAvatar: c.userAvatar || c.senderAvatar || '',
      senderAvatar: c.senderAvatar || c.userAvatar || '',
    }));
  } catch (error) {
    console.error("Error in getCommentsForMessage:", error);
    throw new Error("Failed to fetch comments", { cause: error });
  }
}

