export async function getStickerPacks() {
  try {
    const { stickerPacks, stickers } = await import('./schema.ts');
    const { db } = await import('./index.ts');
    const { eq } = await import('drizzle-orm');
    const { STARTER_PACK } = await import('../lib/starterStickers.ts');

    let packs = await db.select().from(stickerPacks).orderBy(stickerPacks.createdAt);
    
    // Check if STARTER_PACK exists
    let starterInDb = packs.find(p => p.name === STARTER_PACK.name);
    if (!starterInDb) {
      try {
        const [insertedPack] = await db.insert(stickerPacks).values({
          name: STARTER_PACK.name,
          title: STARTER_PACK.title,
          isDefault: 'true',
          thumbnail: STARTER_PACK.thumbnail,
        }).returning();

        if (insertedPack) {
          starterInDb = insertedPack;
          const stickerRows = STARTER_PACK.stickers.map(s => ({
            packId: insertedPack.id,
            imageUrl: s.imageUrl,
            emoji: s.emoji,
            width: s.width,
            height: s.height
          }));
          await db.insert(stickers).values(stickerRows);
          packs = [insertedPack, ...packs];
        }
      } catch (seedErr) {
        console.warn('Failed to seed starter sticker pack into DB:', seedErr);
      }
    } else {
      // Check if starter pack has all 29 stickers, if not re-seed them
      const existingStickers = await db.select().from(stickers).where(eq(stickers.packId, starterInDb.id));
      if (existingStickers.length < STARTER_PACK.stickers.length) {
        try {
          await db.delete(stickers).where(eq(stickers.packId, starterInDb.id));
          const stickerRows = STARTER_PACK.stickers.map(s => ({
            packId: starterInDb!.id,
            imageUrl: s.imageUrl,
            emoji: s.emoji,
            width: s.width,
            height: s.height
          }));
          await db.insert(stickers).values(stickerRows);
        } catch (reseedErr) {
          console.warn('Failed to re-seed stickers into DB:', reseedErr);
        }
      }
    }

    return packs;
  } catch (error) {
    console.error("Error in getStickerPacks:", error);
    throw new Error("Failed to fetch sticker packs", { cause: error });
  }
}

