export async function searchMessages(uid: string, query: string) {
  try {
    if (!query || query.trim() === '') {
      return [];
    }

    const userChats = await getChatsForUser(uid, true);
    const chatIds = userChats.map((c: any) => c.idNumeric); // используем numeric ID для поиска в БД

    if (chatIds.length === 0) {
      return [];
    }

    const results = await db.select()
      .from(messages)
      .where(
        and(
          inArray(messages.chatId, chatIds),
          ilike(messages.text, `%${escapeLikePattern(query)}%`)
        )
      )
      .orderBy(desc(messages.createdAt))
      .limit(50);

    return results;
  } catch (error) {
    console.error("Error in searchMessages:", error);
    throw new Error("Failed to search messages", { cause: error });
  }
}

// --- Delete User Completely ---
export async function deleteUserCompletely(uid: string) {
  try {
    // Получаем numeric ID пользователя
    const userResult = await db.select({ id: users.id }).from(users).where(eq(users.uid, uid)).limit(1);
    if (!userResult[0]) {
      throw new Error('User not found');
    }
    const userNumericId = userResult[0].id;
    
    // 1. Удалить все сообщения пользователя (по numeric ID)
    await db.delete(messages).where(eq(messages.senderId, userNumericId));
    
    // 2. Удалить все комментарии пользователя (по numeric ID)
    await db.delete(comments).where(eq(comments.userId, userNumericId));
    
    // 3. Удалить пользователя из participants всех чатов (по UID строке)
    // Используем JSONB оператор для поиска UID в массиве
    const userChats = await db.select().from(chats).where(sql`${chats.participants}::jsonb @> ${JSON.stringify([uid])}::jsonb`);
    
    for (const chat of userChats) {
      const newParticipants = Array.isArray(chat.participants) ? chat.participants.filter((p: string) => p !== uid) : [];
      const newMembers = Array.isArray(chat.members) ? chat.members.filter((m: string) => m !== uid) : [];
      const newAdmins = Array.isArray(chat.admins) ? chat.admins.filter((a: string) => a !== uid) : [];
      
      // Если это приватный чат и остался только 1 участник - удаляем чат полностью
      if (chat.type === 'private' && newParticipants.length <= 1) {
        await db.delete(chats).where(eq(chats.id, chat.id));
      } else {
        await db.update(chats)
          .set({
            participants: newParticipants,
            members: newMembers,
            admins: newAdmins,
            updatedAt: new Date()
          })
          .where(eq(chats.id, chat.id));
      }
    }
    
    // 4. Удалить самого пользователя из таблицы users
    await db.delete(users).where(eq(users.uid, uid));
    
    return { success: true, message: 'User and all their data deleted completely' };
  } catch (error) {
    console.error("Error in deleteUserCompletely:", error);
    throw new Error("Failed to delete user completely", { cause: error });
  }
}

// --- Delete Chat Completely ---
export async function deleteChatCompletely(chatId: string | number) {
  try {
    // Получаем numeric ID чата
    let chatNumericId: number;
    if (typeof chatId === 'string') {
      const chatResult = await db.select({ id: chats.id }).from(chats).where(eq(chats.chatUid, chatId)).limit(1);
      if (!chatResult[0]) {
        throw new Error('Chat not found');
      }
      chatNumericId = chatResult[0].id;
    } else {
      chatNumericId = chatId;
    }
    
    // 1. Удалить все сообщения в чате
    await db.delete(messages).where(eq(messages.chatId, chatNumericId));
    
    // 2. Удалить все комментарии к сообщениям этого чата
    await db.delete(comments).where(eq(comments.chatId, chatNumericId));
    
    // 3. Удалить сам чат
    await db.delete(chats).where(eq(chats.id, chatNumericId));
    
    return { success: true, message: 'Chat and all its data deleted completely' };
  } catch (error) {
    console.error("Error in deleteChatCompletely:", error);
    throw new Error("Failed to delete chat completely", { cause: error });
  }
}

// ===============================
// Media Center — получение медиа-контента чата
// ===============================

export async function getMediaForChat(
  chatId: string | number,
  opts: { type: string; limit: number; offset: number; search: string; sort: string }
) {
  // 1. Resolve numeric chat ID
  let chatNumericId: number;
  if (typeof chatId === 'string') {
    const chatResult = await db.select({ id: chats.id }).from(chats).where(eq(chats.chatUid, chatId)).limit(1);
    if (!chatResult[0]) return { items: [], total: 0 };
    chatNumericId = chatResult[0].id;
  } else {
    chatNumericId = chatId;
  }

  // 2. Build WHERE conditions
  const conditions: any[] = [eq(messages.chatId, chatNumericId)];

  if (opts.type === 'image') {
    conditions.push(eq(messages.type, 'image'));
  } else if (opts.type === 'video') {
    // video + video_note
    conditions.push(or(eq(messages.type, 'video'), eq(messages.type, 'video_note')) as any);
  } else if (opts.type === 'voice') {
    conditions.push(eq(messages.type, 'voice'));
  } else if (opts.type === 'file') {
    conditions.push(eq(messages.type, 'file'));
  } else if (opts.type === 'link') {
    // ссылки — текстовые сообщения, содержащие URL
    conditions.push(eq(messages.type, 'text'));
    conditions.push(ilike(messages.text, '%http%') as any);
  }

  // Search filter
  if (opts.search) {
    const searchPattern = `%${escapeLikePattern(opts.search)}%`;
    conditions.push(
      or(
        ilike(messages.fileName, searchPattern),
        ilike(messages.text, searchPattern),
        ilike(messages.fileType, searchPattern)
      ) as any
    );
  }

  const whereClause = and(...conditions);

  // 3. Get total count
  const countResult = await db.select({ count: sql<number>`count(*)` })
    .from(messages)
    .where(whereClause);
  const total = countResult[0]?.count || 0;

  // 4. Determine ORDER BY
  let orderByClause: any;
  if (opts.sort === 'oldest') {
    orderByClause = messages.createdAt;
  } else if (opts.sort === 'name') {
    orderByClause = messages.fileName;
  } else {
    // newest (default) — newest first
    orderByClause = desc(messages.createdAt);
  }

  // 5. Fetch items with JOIN to users for sender UID
  const items = await db.select({
    id: messages.msgUid,
    idNumeric: messages.id,
    chatId: messages.chatId,
    senderId: users.uid,
    senderName: messages.senderName,
    senderAvatar: messages.senderAvatar,
    text: messages.text,
    fileUrl: messages.fileUrl,
    fileName: messages.fileName,
    fileType: messages.fileType,
    type: messages.type,
    duration: messages.duration,
    timestamp: messages.createdAt,
    createdAt: messages.createdAt,
  })
    .from(messages)
    .leftJoin(users, eq(messages.senderId, users.id))
    .where(whereClause)
    .orderBy(orderByClause)
    .limit(opts.limit)
    .offset(opts.offset);

  // 6. Estimate file sizes from file system for sorting by size
  let resultItems = items;
  if (opts.sort === 'size' && items.length > 0) {
    const fs = await import('fs');
    const path = await import('path');
    const UPLOADS_DIR = path.join(process.cwd(), 'uploads');
    resultItems = items.map((item: any) => {
      let size = 0;
      if (item.fileUrl) {
        const filename = item.fileUrl.replace('/api/download/', '').replace('/uploads/', '');
        const filePath = path.join(UPLOADS_DIR, filename);
        // Path Traversal: проверяем что путь не выходит за пределы uploads/
        const resolvedPath = path.resolve(filePath);
        if (!resolvedPath.startsWith(path.resolve(UPLOADS_DIR))) {
          size = 0;
        } else {
          try {
            if (fs.existsSync(resolvedPath)) {
              size = fs.statSync(resolvedPath).size;
            }
          } catch {}
        }
      }
      return { ...item, fileSize: size };
    }).sort((a: any, b: any) => b.fileSize - a.fileSize);
  }

  return { items: resultItems, total };
}

export async function toggleMessageReaction(msgUid: string, userUid: string, emoji: string) {
  try {
    const messageResult = await db.select({ reactions: messages.reactions }).from(messages).where(eq(messages.msgUid, msgUid)).limit(1);
    if (!messageResult[0]) {
      throw new Error("Message not found");
    }
    
    const currentReactions = (messageResult[0].reactions || {}) as Record<string, string>;
    
    if (currentReactions[userUid] === emoji) {
      delete currentReactions[userUid];
    } else {
      currentReactions[userUid] = emoji;
    }
    
    const updated = await db.update(messages)
      .set({ reactions: currentReactions })
      .where(eq(messages.msgUid, msgUid))
      .returning();
      
    return updated[0]?.reactions || {};
  } catch (error) {
    console.error("Error in toggleMessageReaction:", error);
    throw new Error("Failed to toggle message reaction", { cause: error });
  }
}

