/**
 * Redis connection — ioredis с fallback на in-memory при недоступности Redis.
 *
 * Использует REDIS_URL из env (по умолчанию redis://localhost:6379).
 * Если REDIS_URL не задан или Redis недоступен — создаётся in-memory MockRedis.
 */
import Redis from 'ioredis';
import { logger } from './logger.ts';

const REDIS_URL = process.env.REDIS_URL || 'redis://localhost:6379';
const REDIS_ENABLED = process.env.REDIS_ENABLED !== 'false';

class MockRedis {
  private store = new Map<string, string>();
  private sets = new Map<string, Set<string>>();
  private hashes = new Map<string, Map<string, string>>();

  async get(key: string) { return this.store.get(key) ?? null; }
  async set(key: string, val: string, ...args: any[]) {
    this.store.set(key, val);
    // Handle EX/PX expiry — store TTL as metadata
    if (args.includes('EX')) {
      const ttlSec = Number(args[args.indexOf('EX') + 1]);
      setTimeout(() => this.store.delete(key), ttlSec * 1000);
    }
    return 'OK';
  }
  async del(...keys: string[]) {
    let count = 0;
    for (const k of keys) { if (this.store.delete(k)) count++; }
    return count;
  }
  async sAdd(key: string, ...members: string[]) {
    if (!this.sets.has(key)) this.sets.set(key, new Set());
    let added = 0;
    for (const m of members) { if (!this.sets.get(key)!.has(m)) { this.sets.get(key)!.add(m); added++; } }
    return added;
  }
  async sMembers(key: string) { return Array.from(this.sets.get(key) ?? []); }
  async sRem(key: string, ...members: string[]) {
    const s = this.sets.get(key);
    if (!s) return 0;
    let removed = 0;
    for (const m of members) { if (s.delete(m)) removed++; }
    return removed;
  }
  async sCard(key: string) { return this.sets.get(key)?.size ?? 0; }
  async expire(_key: string, _seconds: number) { return 1; }
  async ttl(_key: string) { return -1; }
  async keys(pattern: string) {
    const prefix = pattern.replace('*', '');
    return Array.from(this.store.keys()).filter(k => k.startsWith(prefix));
  }
  async hset(key: string, field: string, value: string) {
    if (!this.hashes.has(key)) this.hashes.set(key, new Map());
    this.hashes.get(key)!.set(field, value);
    return 1;
  }
  async hget(key: string, field: string) { return this.hashes.get(key)?.get(field) ?? null; }
  async hgetall(key: string) { return Object.fromEntries(this.hashes.get(key) ?? []); }
  async hdel(key: string, ...fields: string[]) {
    const h = this.hashes.get(key);
    if (!h) return 0;
    let removed = 0;
    for (const f of fields) { if (h.delete(f)) removed++; }
    return removed;
  }
  async lpush(key: string, ...values: string[]) { 
    const existing = JSON.parse(this.store.get(key) || '[]');
    this.store.set(key, JSON.stringify([...values.reverse(), ...existing]));
    return existing.length + values.length;
  }
  async rpop(key: string) {
    const arr = JSON.parse(this.store.get(key) || '[]');
    const val = arr.pop();
    if (arr.length) this.store.set(key, JSON.stringify(arr));
    else this.store.delete(key);
    return val ?? null;
  }
  async lrange(key: string, start: number, stop: number) {
    const arr = JSON.parse(this.store.get(key) || '[]');
    return stop === -1 ? arr.slice(start) : arr.slice(start, stop + 1);
  }
  async llen(key: string) {
    return JSON.parse(this.store.get(key) || '[]').length;
  }
  async ping() { return 'PONG'; }
  on(_event: string, _handler: any) { /* no-op */ }
  async disconnect() { /* no-op */ }
}

let redis: Redis | MockRedis;

export function getRedis(): Redis | MockRedis {
  return redis;
}

async function createRedisConnection(): Promise<Redis | MockRedis> {
  if (!REDIS_ENABLED) {
    logger.warn('[Redis] REDIS_ENABLED=false, using in-memory mock');
    return new MockRedis();
  }

  try {
    const client = new Redis(REDIS_URL, {
      maxRetriesPerRequest: 3,
      retryStrategy(times: number) {
        if (times > 3) {
          logger.warn('[Redis] Max retries reached, falling back to mock');
          return null; // Stop retrying, will use MockRedis
        }
        return Math.min(times * 200, 2000);
      },
      lazyConnect: true,
      connectTimeout: 3000,
    });

    client.on('error', (err: any) => {
      logger.warn({ err: err.message }, '[Redis] Connection error');
    });

    client.on('connect', () => {
      logger.info('[Redis] Connected');
    });

    await Promise.race([
      client.connect(),
      new Promise((_, reject) => setTimeout(() => reject(new Error('Timeout')), 3000)),
    ]);

    // Verify connection
    const pong = await client.ping();
    if (pong === 'PONG') {
      logger.info(`[Redis] Connected to ${REDIS_URL}`);
      return client;
    }
    throw new Error('Ping failed');
  } catch (err: unknown) {
    logger.warn({ err: err.message }, `[Redis] Failed to connect to ${REDIS_URL}, using in-memory mock`);
    return new MockRedis();
  }
}

// Auto-init
redis = await createRedisConnection();

export default redis;