import { db } from './index.ts';
import { sessions } from './schema.ts';
import { eq, and, desc } from 'drizzle-orm';
import { randomUUID } from 'crypto';

// ========================================
// User-Agent парсинг (без внешних зависимостей)
// ========================================

function parseUserAgent(ua: string | null): { browser: string; os: string; deviceType: string } {
  if (!ua) return { browser: 'Unknown', os: 'Unknown', deviceType: 'desktop' };

  // --- Browser ---
  let browser = 'Unknown';
  if (ua.includes('Firefox/') && !ua.includes('Seamonkey')) {
    browser = 'Firefox';
  } else if (ua.includes('Edg/')) {
    browser = 'Edge';
  } else if (ua.includes('OPR/') || ua.includes('Opera')) {
    browser = 'Opera';
  } else if (ua.includes('SamsungBrowser')) {
    browser = 'Samsung Browser';
  } else if (ua.includes('UCBrowser') || ua.includes('UC Browser')) {
    browser = 'UC Browser';
  } else if (ua.includes('Vivaldi')) {
    browser = 'Vivaldi';
  } else if (ua.includes('Brave')) {
    browser = 'Brave';
  } else if (ua.includes('Safari') && !ua.includes('Chrome')) {
    browser = 'Safari';
  } else if (ua.includes('Chrome') && !ua.includes('Edg/')) {
    browser = 'Chrome';
  }

  // --- OS ---
  let os = 'Unknown';
  if (ua.includes('Windows NT 10')) {
    os = 'Windows 10/11';
  } else if (ua.includes('Windows NT 6.3')) {
    os = 'Windows 8.1';
  } else if (ua.includes('Windows NT 6.1')) {
    os = 'Windows 7';
  } else if (ua.includes('Windows')) {
    os = 'Windows';
  } else if (ua.includes('Mac OS X')) {
    const match = ua.match(/Mac OS X (\d+[._]\d+)/);
    os = match ? `macOS ${match[1].replace('_', '.')}` : 'macOS';
  } else if (ua.includes('Android')) {
    const match = ua.match(/Android (\d+[\.\d]*)/);
    os = match ? `Android ${match[1]}` : 'Android';
  } else if (ua.includes('iPhone') || ua.includes('iPad')) {
    const match = ua.match(/OS (\d+_\d+)/);
    os = match ? `iOS ${match[1].replace('_', '.')}` : 'iOS';
  } else if (ua.includes('Linux')) {
    os = 'Linux';
  }

  // --- Device Type ---
  let deviceType = 'desktop';
  if (ua.includes('Mobile') || (ua.includes('Android') && !ua.includes('Tablet')) || ua.includes('iPhone')) {
    deviceType = 'phone';
  } else if (ua.includes('iPad') || ua.includes('Tablet') || (ua.includes('Android') && ua.includes('Tablet'))) {
    deviceType = 'tablet';
  }

  return { browser, os, deviceType };
}

// ========================================
// CRUD операции
// ========================================

/**
 * Создать новую сессию (при логине/регистрации)
 */
export async function createSession(params: {
  userUid: string;
  userAgent: string | null;
  ipAddress: string | null;
}): Promise<{ sessionUid: string }> {
  const { browser, os, deviceType } = parseUserAgent(params.userAgent);
  const sessionUid = randomUUID();

  await db.insert(sessions).values({
    sessionUid,
    userUid: params.userUid,
    browser,
    os,
    deviceType,
    ipAddress: params.ipAddress || null,
    lastActive: new Date(),
    createdAt: new Date(),
    revoked: false,
  });

  return { sessionUid };
}

/**
 * Обновить время последней активности сессии
 */
export async function touchSession(sessionUid: string): Promise<void> {
  try {
    await db.update(sessions)
      .set({ lastActive: new Date() })
      .where(and(
        eq(sessions.sessionUid, sessionUid),
        eq(sessions.revoked, false),
      ));
  } catch {
    // Тихо игнорируем ошибки touch — это не критично
  }
}

/**
 * Проверить, активна ли сессия (не отозвана)
 * Если сессии нет в БД (старые JWT без sessions) — считаем активной
 */
export async function isSessionActive(sessionUid: string): Promise<boolean> {
  const result = await db.select({ revoked: sessions.revoked })
    .from(sessions)
    .where(eq(sessions.sessionUid, sessionUid))
    .limit(1);

  if (result.length === 0) return true; // совместимость со старыми JWT
  return result[0].revoked === false;
}

/**
 * Получить все сессии пользователя
 */
export async function getUserSessions(userUid: string) {
  return db.select({
    sessionUid: sessions.sessionUid,
    browser: sessions.browser,
    os: sessions.os,
    deviceType: sessions.deviceType,
    ipAddress: sessions.ipAddress,
    location: sessions.location,
    lastActive: sessions.lastActive,
    createdAt: sessions.createdAt,
    revoked: sessions.revoked,
  })
    .from(sessions)
    .where(eq(sessions.userUid, userUid))
    .orderBy(desc(sessions.lastActive));
}

/**
 * Отозвать конкретную сессию
 */
export async function revokeSession(sessionUid: string, userUid: string): Promise<boolean> {
  const result = await db.update(sessions)
    .set({ revoked: true })
    .where(and(
      eq(sessions.sessionUid, sessionUid),
      eq(sessions.userUid, userUid),
      eq(sessions.revoked, false),
    ))
    .returning();

  return result.length > 0;
}

/**
 * Отозвать все сессии пользователя, кроме текущей
 */
export async function revokeAllOtherSessions(currentSessionUid: string, userUid: string): Promise<number> {
  // Отзываем все кроме текущей
  await db.update(sessions)
    .set({ revoked: true })
    .where(and(
      eq(sessions.userUid, userUid),
      eq(sessions.revoked, false),
    ));

  // Восстанавливаем текущую сессию
  await db.update(sessions)
    .set({ revoked: false })
    .where(eq(sessions.sessionUid, currentSessionUid));

  // Подсчитаем отозванные
  const allSessions = await db.select({ revoked: sessions.revoked })
    .from(sessions)
    .where(eq(sessions.userUid, userUid));

  return allSessions.filter(s => s.revoked === true).length;
}

/**
 * Удалить старые отозванные сессии (старше 30 дней)
 */
export async function cleanupOldSessions(): Promise<void> {
  await db.delete(sessions).where(eq(sessions.revoked, true));
}