/**
 * Admin routes — сообщения, поиск, флаги, стикер-паки
 */
import { Express } from 'express';
import { JwtRequest } from '../../src/middleware/jwtAuth.ts';
import { requireAdmin } from '../../src/middleware/adminAuth.ts';
import { validate, MessageFlagSchema } from '../../src/middleware/validate.ts';

export async function setupAdminMessageRoutes(app: Express) {
  const {
    getRecentMessages,
    flagMessage,
    deleteMessageAdmin,
    searchMessages,
    getAllChats,
    deleteAllChatMessages,
    getStickerPacks,
    deleteStickerPack,
  } = await import('../../src/db/admin.ts');

  // ========================================
  // MESSAGES
  // ========================================

  // Последние сообщения (модерация)
  app.get('/api/admin/messages', requireAdmin, async (req, res) => {
    try {
      const limit = parseInt(req.query.limit as string) || 50;
      const offset = parseInt(req.query.offset as string) || 0;
      const msgs = await getRecentMessages(limit, offset);
      res.json(msgs);
    } catch (err: unknown) {
      res.status(500).json({ error: err.message });
    }
  });

  // Пометить/снять пометку с сообщения
  app.post('/api/admin/messages/:msgId/flag', requireAdmin, validate(MessageFlagSchema), async (req, res) => {
    try {
      const { msgId } = req.params;
      const { flag } = req.body;
      const updated = await flagMessage(msgId as any, flag ?? null);
      res.json(updated);
    } catch (err: unknown) {
      res.status(500).json({ error: err.message });
    }
  });

  // Удалить сообщение (админ)
  app.delete('/api/admin/messages/:msgId', requireAdmin, async (req, res) => {
    try {
      const { msgId } = req.params;
      const deleted = await deleteMessageAdmin(msgId as any);
      res.json({ deleted: !!deleted });
    } catch (err: unknown) {
      res.status(500).json({ error: err.message });
    }
  });

  app.get('/api/admin/messages/search', requireAdmin, async (req, res) => {
    try {
      const q = (req.query.q as string) || '';
      if (!q.trim()) return res.json([]);
      const results = await searchMessages(q);
      res.json(results);
    } catch (err: unknown) {
      res.status(500).json({ error: err.message });
    }
  });

  // ========================================
  // CHATS (список + удаление чата и его сообщений)
  // ========================================
  app.get('/api/admin/chats', requireAdmin, async (req, res) => {
    try {
      const chatsList = await getAllChats();
      res.json(chatsList);
    } catch (err: unknown) {
      res.status(500).json({ error: err.message });
    }
  });

  app.delete('/api/admin/chats/:chatId', requireAdmin, async (req, res) => {
    try {
      const { chatId } = req.params;
      const { deleteChatCompletely } = await import('../../src/db/helpers.ts');
      const result = await deleteChatCompletely(chatId);
      res.json(result);
    } catch (err: unknown) {
      res.status(500).json({ error: err.message });
    }
  });

  app.delete('/api/admin/chats/:chatId/messages', requireAdmin, async (req, res) => {
    try {
      const chatId = parseInt(req.params.chatId);
      if (isNaN(chatId)) return res.status(400).json({ error: 'Invalid chat id' });
      const count = await deleteAllChatMessages(chatId);
      res.json({ deleted: count });
    } catch (err: unknown) {
      res.status(500).json({ error: err.message });
    }
  });

  // ========================================
  // STICKER PACKS
  // ========================================
  app.get('/api/admin/sticker-packs', requireAdmin, async (req, res) => {
    try {
      const packs = await getStickerPacks();
      res.json(packs);
    } catch (err: unknown) {
      res.status(500).json({ error: err.message });
    }
  });

  app.delete('/api/admin/sticker-packs/:id', requireAdmin, async (req, res) => {
    try {
      const packId = parseInt(req.params.id);
      if (isNaN(packId)) return res.status(400).json({ error: 'Invalid pack id' });
      await deleteStickerPack(packId);
      res.json({ success: true });
    } catch (err: unknown) {
      res.status(500).json({ error: err.message });
    }
  });
}