import { Express } from 'express';
import { randomUUID, randomInt } from 'crypto';
import { logger, ctx } from '../services/logger.ts';
import { JwtRequest } from '../../src/middleware/jwtAuth.ts';
import {
  loginRateLimit,
  registerRateLimit,
  changePasswordRateLimit,
} from '../../src/middleware/security.ts';
import {
  createUserWithPassword,
  verifyUserPassword,
  getUserByEmail,
  getUserByUsername,
  getUserByUid,
} from '../../src/db/auth.ts';
import { signJwt, signRefreshJwt, verifyRefreshJwt } from '../../src/lib/auth.ts';
import { createSession, revokeSession } from '../../src/db/sessions.ts';
import { validate, RegisterSchema, LoginSchema } from '../../src/middleware/validate.ts';
import { requireAuth } from '../../src/middleware/jwtAuth.ts';
import { sendOtpEmail, isSmtpConfigured } from '../services/mail.ts';
import express from 'express';

function setRefreshTokenCookie(res: express.Response, token: string) {
  res.cookie('refresh_token', token, {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'strict',
    path: '/',
    maxAge: 3 * 24 * 60 * 60 * 1000, // 3 дня
  });
}

function clearRefreshTokenCookie(res: express.Response) {
  res.clearCookie('refresh_token', {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'strict',
    path: '/',
  });
}

export async function setupAuthRoutes(app: Express) {
  // ========================================
  // CSRF Token Endpoint
  // ========================================
  const { setCsrfCookie } = await import('../middleware/csrf.ts');

  app.get("/api/csrf-token", (req, res) => {
    const log = ctx(req);
    try {
      const csrfToken = setCsrfCookie(res);
      res.json({ csrfToken });
    } catch (err: unknown) {
      log.error({ err }, '[CSRF] Token generation error');
      res.status(500).json({ error: 'Failed to generate CSRF token' });
    }
  });

  app.post('/api/auth/register', registerRateLimit, validate(RegisterSchema), async (req, res) => {
    const log = ctx(req);
    try {
      const { email, password, username, displayName, photoURL } = req.body;

      const existingEmailUser = await getUserByEmail(email);
      if (existingEmailUser) {
        return res.status(409).json({ error: 'Email already exists.' });
      }
      const existingUsernameUser = await getUserByUsername(username);
      if (existingUsernameUser) {
        return res.status(409).json({ error: 'Username already exists.' });
      }

      const uid = randomUUID();
      const createdUser = await createUserWithPassword({
        uid,
        email,
        password,
        username,
        displayName,
        photoURL,
        status: 'online',
      });

      const userAgent = req.headers['user-agent'] || null;
      const ip = req.ip || req.socket?.remoteAddress || null;
      const { sessionUid } = await createSession({ userUid: uid, userAgent, ipAddress: ip });
      const token = signJwt(createdUser, sessionUid);
      const refreshToken = signRefreshJwt(createdUser, sessionUid);
      setRefreshTokenCookie(res, refreshToken);
      res.json({ token, user: createdUser });
    } catch (err: unknown) {
      log.error({ err }, 'Register error');
      res.status(500).json({ error: err.message || 'Registration failed.' });
    }
  });

  app.post('/api/auth/login', loginRateLimit, validate(LoginSchema), async (req, res) => {
    const log = ctx(req);
    try {
      const { email, password } = req.body;
      log.info({ email }, '[LOGIN] Attempt');

    const userByEmail = await getUserByEmail(email);
    if (!userByEmail) {
      log.warn({ email }, '[LOGIN] User NOT found by email');
      return res.status(401).json({ error: 'Invalid credentials.' });
    }
    log.debug({ email, hasPassword: !!userByEmail.passwordHash }, '[LOGIN] User found by email');

      const user = await verifyUserPassword(email, password);
      log.debug({ email, verified: !!user }, '[LOGIN] verifyUserPassword result');

      if (!user) {
        return res.status(401).json({ error: 'Invalid credentials.' });
      }

      const userAgent = req.headers['user-agent'] || null;
      const ip = req.ip || req.socket?.remoteAddress || null;
      const { sessionUid } = await createSession({ userUid: user.uid, userAgent, ipAddress: ip });
      const token = signJwt(user, sessionUid);
      const refreshToken = signRefreshJwt(user, sessionUid);
      log.info({ email }, '[LOGIN] Success');
      setRefreshTokenCookie(res, refreshToken);
      res.json({ token, user });
    } catch (err: unknown) {
      log.error({ err }, 'Login error');
      res.status(500).json({ error: err.message || 'Login failed.' });
    }
  });

  app.get('/api/auth/me', requireAuth, async (req: JwtRequest, res) => {
    const log = ctx(req);
    try {
      const user = await getUserByUid(req.user!.uid);
      if (!user) {
        return res.status(404).json({ error: 'User not found.' });
      }
      res.json(user);
    } catch (err: unknown) {
      log.error({ err }, 'Auth me error');
      res.status(500).json({ error: err.message || 'Failed to fetch authenticated user.' });
    }
  });

  // ========================================
  // Refresh Token — обновление access token
  // ========================================
  app.post('/api/auth/refresh', async (req, res) => {
    const log = ctx(req);
    try {
      const refreshToken = req.cookies?.refresh_token;
      if (!refreshToken) {
        return res.status(400).json({ error: 'Refresh token is required.' });
      }

      let decoded;
      try {
        decoded = verifyRefreshJwt(refreshToken);
      } catch {
        clearRefreshTokenCookie(res);
        return res.status(401).json({ error: 'Invalid or expired refresh token.' });
      }

      if ((decoded as any).type !== 'refresh') {
        clearRefreshTokenCookie(res);
        return res.status(401).json({ error: 'Invalid token type.' });
      }

      if (decoded.sessionUid) {
        const { isSessionActive: checkSession, revokeSession: revokeOldSession } = await import('../../src/db/sessions.ts');
        const active = await checkSession(decoded.sessionUid);
        if (!active) {
          clearRefreshTokenCookie(res);
          return res.status(401).json({ error: 'Session revoked.' });
        }
        // Refresh token rotation: отзываем старую сессию перед выдачей новой
        await revokeOldSession(decoded.sessionUid, decoded.uid);
      }

      const user = await getUserByUid(decoded.uid);
      if (!user) {
        clearRefreshTokenCookie(res);
        return res.status(401).json({ error: 'User not found.' });
      }

      const { sessionUid: newSessionUid } = await createSession({
        userUid: decoded.uid,
        userAgent: req.headers['user-agent'] || null,
        ipAddress: req.ip || req.socket?.remoteAddress || null,
      });
      const newToken = signJwt(user, newSessionUid);
      const newRefreshToken = signRefreshJwt(user, newSessionUid);
      setRefreshTokenCookie(res, newRefreshToken);
      res.json({ token: newToken });
    } catch (err: unknown) {
      log.error({ err }, 'Refresh token error');
      res.status(500).json({ error: err.message || 'Token refresh failed.' });
    }
  });

  // ========================================
  // Logout — отзыв текущей сессии
  // ========================================
  // ========================================
  // PUT /api/auth/password — смена пароля (currentPassword + newPassword)
  // ========================================
  app.put('/api/auth/password', requireAuth, changePasswordRateLimit, async (req: JwtRequest, res) => {
    const log = ctx(req);
    try {
      const uid = req.user!.uid;
      const { currentPassword, newPassword } = req.body;

      if (!currentPassword || !newPassword) {
        return res.status(400).json({ error: 'currentPassword and newPassword are required.' });
      }
      if (typeof newPassword !== 'string' || newPassword.length < 6) {
        return res.status(400).json({ error: 'New password must be at least 6 characters.' });
      }

      // Получаем пользователя с хешем пароля
      const { getUserByEmail: getFullUserByEmail } = await import('../../src/db/auth.ts');
      const { getUserByUid } = await import('../../src/db/auth.ts');

      // Проверяем текущий пароль
      const { verifyUserPassword } = await import('../../src/db/auth.ts');
      // verifyUserPassword принимает email, но нам нужен просто проверка по uid.
      // Получаем полный объект с passwordHash через getUserByEmail нельзя по uid.
      // Используем прямой запрос.

      const { db } = await import('../../src/db/index.ts');
      const { users } = await import('../../src/db/schema.ts');
      const { eq } = await import('drizzle-orm');
      const bcrypt = (await import('bcryptjs')).default;

      const result = await db.select().from(users).where(eq(users.uid, uid)).limit(1);
      const row = result[0] as any;
      if (!row) {
        return res.status(404).json({ error: 'User not found.' });
      }

      const currentHash = row.passwordHash as string | null;
      if (!currentHash) {
        return res.status(400).json({ error: 'Account does not have a password set (social login).' });
      }

      const isValid = await bcrypt.compare(currentPassword, currentHash);
      if (!isValid) {
        log.warn({ uid }, '[PASSWORD] Incorrect current password');
        return res.status(401).json({ error: 'Current password is incorrect.' });
      }

      const newHash = await bcrypt.hash(newPassword, 10);
      await db.update(users).set({ passwordHash: newHash }).where(eq(users.uid, uid));

      log.info({ uid }, '[PASSWORD] Password changed successfully');
      res.json({ success: true });
    } catch (err: unknown) {
      log.error({ err }, 'Change password error');
      res.status(500).json({ error: err.message || 'Failed to change password.' });
    }
  });

  // ========================================
  // ВОССТАНОВЛЕНИЕ ПАРОЛЯ ПО OTP
  // ========================================

  // POST /api/auth/forgot-password — отправить OTP-код на привязанную почту
  // Принимает email (recovery_email привязанный к аккаунту)
  app.post('/api/auth/forgot-password', loginRateLimit, async (req, res) => {
    const log = ctx(req);
    try {
      const { email } = req.body;
      if (!email || typeof email !== 'string') {
        return res.status(400).json({ error: 'Email is required.' });
      }

      const { db: dbConn } = await import('../../src/db/index.ts');
      const { users } = await import('../../src/db/schema.ts');
      const { eq: eqFn, sql } = await import('drizzle-orm');

      // Ищем пользователя по recovery_email
      const rows = await dbConn.select({ uid: users.uid, email: users.email })
        .from(users)
        .where(eqFn(users.recoveryEmail, email))
        .limit(1);

      // Всегда возвращаем одинаковый ответ (защита от user enumeration)
      if (!rows.length) {
        return res.json({ success: true, message: 'If the email exists, an OTP code has been sent.' });
      }

      const userUid = (rows[0] as any).uid;
      const recoveryEmail = email;

      // Генерируем 6-значный OTP
      const code = String(randomInt(100000, 999999));
      const expiresAt = new Date(Date.now() + 10 * 60 * 1000); // 10 минут
      const expiresAtUtc = expiresAt.toISOString(); // явно UTC

      // Удаляем старые OTP для этого пользователя
      await dbConn.execute(sql`DELETE FROM otp_codes WHERE user_uid = ${userUid} AND purpose = 'recovery' AND used = false`);

      // Сохраняем OTP
      await dbConn.execute(sql`
        INSERT INTO otp_codes (user_uid, email, code, purpose, attempts, expires_at, used)
        VALUES (${userUid}, ${recoveryEmail}, ${code}, 'recovery', 0, ${expiresAtUtc}::timestamp, false)
      `);

      // Отправляем email
      const sent = await sendOtpEmail(recoveryEmail, code, 'recovery');
      if (!sent) {
        log.error({ uid: userUid }, '[FORGOT-PASSWORD] Failed to send OTP email');
        return res.status(500).json({ error: 'Failed to send OTP email. Please try again later.' });
      }

      log.info({ uid: userUid, email: recoveryEmail }, '[FORGOT-PASSWORD] OTP sent');
      res.json({ success: true, message: 'If the email exists, an OTP code has been sent.' });
    } catch (err: unknown) {
      log.error({ err }, 'Forgot password error');
      res.status(500).json({ error: err.message || 'Failed to process request.' });
    }
  });

  // POST /api/auth/verify-otp — проверить OTP-код и сбросить пароль
  app.post('/api/auth/verify-otp', loginRateLimit, async (req, res) => {
    const log = ctx(req);
    try {
      const { email, code, newPassword } = req.body;

      if (!email || !code || !newPassword) {
        return res.status(400).json({ error: 'email, code, and newPassword are required.' });
      }
      if (typeof newPassword !== 'string' || newPassword.length < 6) {
        return res.status(400).json({ error: 'New password must be at least 6 characters.' });
      }

      const { db: dbConn } = await import('../../src/db/index.ts');
      const { otpCodes, users } = await import('../../src/db/schema.ts');
      const { sql, eq: eqFn } = await import('drizzle-orm');
      const bcrypt = (await import('bcryptjs')).default;

      // Ищем пользователя по recovery_email
      const userRows = await dbConn.select({ uid: users.uid })
        .from(users)
        .where(eqFn(users.recoveryEmail, email))
        .limit(1);

      if (!userRows.length) {
        return res.status(400).json({ error: 'Invalid or expired OTP code.' });
      }

      const userUid = (userRows[0] as any).uid;

      // Ищем последний неиспользованный OTP
      const otpRows = await dbConn.execute(sql`
        SELECT * FROM otp_codes
        WHERE user_uid = ${userUid} AND purpose = 'recovery' AND used = false
        ORDER BY created_at DESC LIMIT 1
      `);
      const rows = otpRows?.rows || [];
      if (!rows.length) {
        return res.status(400).json({ error: 'No OTP code found. Please request a new one.' });
      }

      const otpRow = rows[0] as any;

      // Проверяем срок действия (PGlite может хранить timestamp без timezone — добавляем Z для корректного сравнения)
      const expiresAtStr = String(otpRow.expires_at);
      const expiresAtDate = new Date(expiresAtStr.endsWith('Z') ? expiresAtStr : expiresAtStr + 'Z');
      if (expiresAtDate < new Date()) {
        await dbConn.execute(sql`UPDATE otp_codes SET used = true WHERE id = ${otpRow.id}`);
        return res.status(400).json({ error: 'OTP code has expired. Please request a new one.' });
      }

      // Проверяем количество попыток (макс 5)
      if ((otpRow.attempts || 0) >= 5) {
        await dbConn.execute(sql`UPDATE otp_codes SET used = true WHERE id = ${otpRow.id}`);
        return res.status(400).json({ error: 'Too many attempts. Please request a new OTP code.' });
      }

      // Проверяем код
      if (otpRow.code !== code) {
        await dbConn.execute(sql`UPDATE otp_codes SET attempts = (attempts + 1) WHERE id = ${otpRow.id}`);
        log.warn({ uid: userUid }, '[VERIFY-OTP] Incorrect code');
        return res.status(400).json({ error: 'Incorrect OTP code.' });
      }

      // Код верный — меняем пароль
      const newHash = await bcrypt.hash(newPassword, 10);
      await dbConn.update(users).set({ passwordHash: newHash }).where(eqFn(users.uid, userUid));

      // Помечаем OTP как использованный
      await dbConn.execute(sql`UPDATE otp_codes SET used = true WHERE id = ${otpRow.id}`);

      // Получаем email аккаунта для автоматического входа на фронте
      const userAccountRows = await dbConn.select({ email: users.email }).from(users).where(eqFn(users.uid, userUid)).limit(1);
      const accountEmail = (userAccountRows[0] as any)?.email || null;

      log.info({ uid: userUid }, '[VERIFY-OTP] Password reset successfully');
      res.json({ success: true, message: 'Password has been reset.', accountEmail });
    } catch (err: unknown) {
      log.error({ err }, 'Verify OTP error');
      res.status(500).json({ error: err.message || 'Failed to verify OTP.' });
    }
  });

  // ========================================
  // ПРИВЯЗКА EMAIL ДЛЯ ВОССТАНОВЛЕНИЯ
  // ========================================

  // GET /api/auth/recovery-email — получить текущий recovery_email
  app.get('/api/auth/recovery-email', requireAuth, async (req: JwtRequest, res) => {
    const log = ctx(req);
    try {
      const { db: dbConn } = await import('../../src/db/index.ts');
      const { users } = await import('../../src/db/schema.ts');
      const { eq: eqFn } = await import('drizzle-orm');

      const uid = req.user!.uid;
      const rows = await dbConn.select({ recoveryEmail: users.recoveryEmail }).from(users).where(eqFn(users.uid, uid)).limit(1);
      const email = (rows[0] as any)?.recoveryEmail || null;
      res.json({ email });
    } catch (err: unknown) {
      log.error({ err }, 'Get recovery email error');
      res.status(500).json({ error: err.message || 'Failed to get recovery email.' });
    }
  });

  // POST /api/auth/recovery-email — привязать новый recovery_email (отправляет OTP для подтверждения)
  app.post('/api/auth/recovery-email', requireAuth, loginRateLimit, async (req: JwtRequest, res) => {
    const log = ctx(req);
    try {
      const { email } = req.body;
      const uid = req.user!.uid;

      if (!email || typeof email !== 'string') {
        return res.status(400).json({ error: 'Email is required.' });
      }

      // Валидация формата email
      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      if (!emailRegex.test(email)) {
        return res.status(400).json({ error: 'Invalid email format.' });
      }

      const { db: dbConn } = await import('../../src/db/index.ts');
      const { otpCodes } = await import('../../src/db/schema.ts');
      const { sql } = await import('drizzle-orm');

      // Генерируем OTP для подтверждения
      const code = String(randomInt(100000, 999999));
      const expiresAt = new Date(Date.now() + 10 * 60 * 1000);
      const expiresAtUtc = expiresAt.toISOString();

      // Удаляем старые OTP verify для этого пользователя
      await dbConn.execute(sql`DELETE FROM otp_codes WHERE user_uid = ${uid} AND purpose = 'verify' AND used = false`);

      // Сохраняем OTP
      await dbConn.execute(sql`
        INSERT INTO otp_codes (user_uid, email, code, purpose, attempts, expires_at, used)
        VALUES (${uid}, ${email}, ${code}, 'verify', 0, ${expiresAtUtc}::timestamp, false)
      `);

      // Отправляем OTP
      const sent = await sendOtpEmail(email, code, 'verify');
      if (!sent) {
        log.error({ uid }, '[RECOVERY-EMAIL] Failed to send verification email');
        return res.status(500).json({ error: 'Failed to send verification email.' });
      }

      log.info({ uid, email }, '[RECOVERY-EMAIL] Verification OTP sent');
      res.json({ success: true, message: 'OTP code sent to the new email.' });
    } catch (err: unknown) {
      log.error({ err }, 'Set recovery email error');
      res.status(500).json({ error: err.message || 'Failed to send verification email.' });
    }
  });

  // POST /api/auth/confirm-recovery-email — подтвердить OTP и сохранить email
  app.post('/api/auth/confirm-recovery-email', requireAuth, loginRateLimit, async (req: JwtRequest, res) => {
    const log = ctx(req);
    try {
      const { email, code } = req.body;
      const uid = req.user!.uid;

      if (!email || !code) {
        return res.status(400).json({ error: 'email and code are required.' });
      }

      const { db: dbConn } = await import('../../src/db/index.ts');
      const { otpCodes, users } = await import('../../src/db/schema.ts');
      const { sql, eq: eqFn } = await import('drizzle-orm');

      // Ищем OTP
      const otpRows = await dbConn.execute(sql`
        SELECT * FROM otp_codes
        WHERE user_uid = ${uid} AND email = ${email} AND purpose = 'verify' AND used = false
        ORDER BY created_at DESC LIMIT 1
      `);
      const rows = otpRows?.rows || [];
      if (!rows.length) {
        return res.status(400).json({ error: 'No OTP code found. Please request a new one.' });
      }

      const otpRow = rows[0] as any;

      // PGlite может хранить timestamp без timezone — добавляем Z для корректного сравнения
      const expiresAtStr2 = String(otpRow.expires_at);
      const expiresAtDate2 = new Date(expiresAtStr2.endsWith('Z') ? expiresAtStr2 : expiresAtStr2 + 'Z');
      if (expiresAtDate2 < new Date()) {
        await dbConn.execute(sql`UPDATE otp_codes SET used = true WHERE id = ${otpRow.id}`);
        return res.status(400).json({ error: 'OTP code has expired.' });
      }

      if ((otpRow.attempts || 0) >= 5) {
        await dbConn.execute(sql`UPDATE otp_codes SET used = true WHERE id = ${otpRow.id}`);
        return res.status(400).json({ error: 'Too many attempts. Please request a new code.' });
      }

      if (otpRow.code !== code) {
        await dbConn.execute(sql`UPDATE otp_codes SET attempts = (attempts + 1) WHERE id = ${otpRow.id}`);
        return res.status(400).json({ error: 'Incorrect OTP code.' });
      }

      // Код верный — сохраняем recovery_email
      await dbConn.update(users).set({ recoveryEmail: email }).where(eqFn(users.uid, uid));
      await dbConn.execute(sql`UPDATE otp_codes SET used = true WHERE id = ${otpRow.id}`);

      log.info({ uid, email }, '[CONFIRM-RECOVERY-EMAIL] Email verified and saved');
      res.json({ success: true, email });
    } catch (err: unknown) {
      log.error({ err }, 'Confirm recovery email error');
      res.status(500).json({ error: err.message || 'Failed to confirm email.' });
    }
  });

  // DELETE /api/auth/recovery-email — удалить привязку
  app.delete('/api/auth/recovery-email', requireAuth, async (req: JwtRequest, res) => {
    const log = ctx(req);
    try {
      const uid = req.user!.uid;
      const { db: dbConn } = await import('../../src/db/index.ts');
      const { users } = await import('../../src/db/schema.ts');
      const { eq: eqFn } = await import('drizzle-orm');

      await dbConn.update(users).set({ recoveryEmail: null }).where(eqFn(users.uid, uid));
      log.info({ uid }, '[RECOVERY-EMAIL] Email unlinked');
      res.json({ success: true });
    } catch (err: unknown) {
      log.error({ err }, 'Remove recovery email error');
      res.status(500).json({ error: err.message || 'Failed to remove recovery email.' });
    }
  });

  // GET /api/auth/smtp-status — проверить, настроен ли SMTP
  app.get('/api/auth/smtp-status', (_req, res) => {
    res.json({ configured: isSmtpConfigured() });
  });

  app.post('/api/auth/logout', requireAuth, async (req: JwtRequest, res) => {
    try {
      const uid = req.user!.uid;
      const sessionUid = req.user!.sessionUid;
      if (sessionUid) {
        const { revokeSession } = await import('../../src/db/sessions.ts');
        await revokeSession(sessionUid, uid);
        try {
          const broadcastFn = (globalThis as any).__broadcastStatusUpdate;
          if (broadcastFn) {
            broadcastFn([uid], { type: 'session_revoked', sessionUid });
          }
        } catch {}
      }
      clearRefreshTokenCookie(res);
      res.json({ success: true });
    } catch (err: unknown) {
      log.error({ err }, 'Logout error');
      res.status(500).json({ error: err.message || 'Logout failed.' });
    }
  });
}