import { pgTable, text, timestamp, integer, jsonb, bigserial, bigint, index, boolean } from 'drizzle-orm/pg-core';

export const users = pgTable('users', {
  id: bigserial('id', { mode: 'number' }).primaryKey(),
  uid: text('uid').unique().notNull(),
  email: text('email').notNull(),
  passwordHash: text('password_hash'),
  displayName: text('display_name'),
  photoURL: text('photo_url'),
  status: text('status').default('offline'),
  lastSeen: timestamp('last_seen').defaultNow(),
  bio: text('bio'),
  username: text('username').unique(),
  phoneNumber: text('phone_number'),
  privacySettings: jsonb('privacy_settings').default({
    online_status: 'everyone',
    bio: 'everyone',
    avatar: 'everyone',
    username: 'everyone',
    messages: 'everyone',
  }),
  role: text('role').default('user'), // 'user' | 'admin' | 'banned'
  recoveryEmail: text('recovery_email'), // почта для восстановления пароля
  createdAt: timestamp('created_at').defaultNow(),
  updatedAt: timestamp('updated_at').defaultNow(),
});

// ========================================
// OTP-коды (восстановление пароля, подтверждение почты)
// ========================================
export const otpCodes = pgTable('otp_codes', {
  id: bigserial('id', { mode: 'number' }).primaryKey(),
  userUid: text('user_uid').notNull(),
  email: text('email').notNull(),
  code: text('code').notNull(), // 6-значный код
  purpose: text('purpose').notNull(), // 'recovery' | 'verify'
  attempts: integer('attempts').default(0),
  expiresAt: timestamp('expires_at').notNull(),
  used: boolean('used').default(false),
  createdAt: timestamp('created_at').defaultNow(),
}, (table) => [
  index('otp_codes_user_uid_idx').on(table.userUid),
  index('otp_codes_email_idx').on(table.email),
]);

// ========================================
// Контакты пользователей
// ========================================
export const userContacts = pgTable('user_contacts', {
  id: bigserial('id', { mode: 'number' }).primaryKey(),
  ownerUid: text('owner_uid').notNull(),
  contactUid: text('contact_uid').notNull(),
  alias: text('alias'),
  createdAt: timestamp('created_at').defaultNow(),
});

export const chats = pgTable('chats', {
  id: bigserial('id', { mode: 'number' }).primaryKey(),
  chatUid: text('chat_uid').unique(),
  type: text('type').notNull(), // 'private' | 'group' | 'channel'
  name: text('name'),
  description: text('description'),
  avatar: text('avatar'),
  creatorId: bigint('creator_id', { mode: 'number' }),
  members: jsonb('members').default([]), // array of user uids
  participants: jsonb('participants').default([]), // array of user uids
  linkedChatId: bigint('linked_chat_id', { mode: 'number' }),
  mutedBy: jsonb('muted_by').default([]), // array of user uids
  typing: jsonb('typing').default({}), // map of uid -> boolean
  createdAt: timestamp('created_at').defaultNow(),
  updatedAt: timestamp('updated_at').defaultNow(),
  lastMessage: jsonb('last_message'),
  slowMode: integer('slow_mode').default(0), // { text, senderId, senderName, timestamp }
  bannedUsers: jsonb('banned_users').default([]), // array of user uids
  admins: jsonb('admins').default([]),
  adminPerms: jsonb('admin_perms').default({}), // array of user uids
  pinnedMessageUid: text('pinned_message_uid'),
  username: text('username'),
  activeCall: jsonb('active_call'),
});

export const messages = pgTable('messages', {
  id: bigserial('id', { mode: 'number' }).primaryKey(),
  msgUid: text('msg_uid').unique(),
  chatId: bigint('chat_id', { mode: 'number' }).references(() => chats.id, { onDelete: 'cascade' }).notNull(),
  senderId: bigint('sender_id', { mode: 'number' }).notNull(),
  senderName: text('sender_name'),
  senderAvatar: text('sender_avatar'),
  text: text('text'),
  createdAt: timestamp('created_at').defaultNow(),
  fileUrl: text('file_url'),
  fileName: text('file_name'),
  fileType: text('file_type'),
  type: text('type').default('text'), // 'text' | 'voice' | 'file' | 'image' | 'video'
  duration: integer('duration'),
  replyTo: text('reply_to'),
  readBy: jsonb('read_by').default([]),
  flagged: text('flagged'), // null | 'reported' - помечено модератором
  reactions: jsonb('reactions').default({}), // map of user_uid -> emoji
  editedAt: timestamp('edited_at'),
  viewedBy: jsonb('viewed_by').default([]), // время последнего редактирования
});

export const comments = pgTable('comments', {
  id: bigserial('id', { mode: 'number' }).primaryKey(),
  commentUid: text('comment_uid').unique(),
  messageId: bigint('message_id', { mode: 'number' }).references(() => messages.id, { onDelete: 'cascade' }).notNull(),
  chatId: bigint('chat_id', { mode: 'number' }).notNull(),
  userId: bigint('user_id', { mode: 'number' }).notNull(),
  userName: text('user_name'),
  userAvatar: text('user_avatar'),
  text: text('text').notNull(),
  createdAt: timestamp('created_at').defaultNow(),
});

// ========================================
// Закреплённые сообщения (мульти-закреп)
// ========================================
export const pinnedMessages = pgTable('pinned_messages', {
  id: bigserial('id', { mode: 'number' }).primaryKey(),
  chatId: bigint('chat_id', { mode: 'number' }).references(() => chats.id, { onDelete: 'cascade' }).notNull(),
  messageUid: text('message_uid').notNull(), // msgUid из таблицы messages
  pinnedBy: text('pinned_by').notNull(), // uid пользователя, который закрепил
  pinnedByName: text('pinned_by_name'), // displayName для быстрого отображения
  pinnedAt: timestamp('pinned_at').defaultNow().notNull(),
  sortOrder: integer('sort_order').default(0), // для ручной сортировки
}, (table) => [
  index('pinned_messages_chat_id_idx').on(table.chatId),
  index('pinned_messages_message_uid_idx').on(table.messageUid),
]);

// ========================================
// Push-уведомления
// ========================================
export const pushSubscriptions = pgTable('push_subscriptions', {
  id: bigserial('id', { mode: 'number' }).primaryKey(),
  userId: bigint('user_id', { mode: 'number' }).references(() => users.id, { onDelete: 'cascade' }).notNull(),
  endpoint: text('endpoint').notNull(),
  subscription: jsonb('subscription').notNull(),
  userAgent: text('user_agent'),
  createdAt: timestamp('created_at').defaultNow(),
});

// ========================================
// Стикеры
// ========================================
export const stickerPacks = pgTable('sticker_packs', {
  id: bigserial('id', { mode: 'number' }).primaryKey(),
  name: text('name').unique().notNull(),
  title: text('title').notNull(),
  authorId: bigint('author_id', { mode: 'number' }).references(() => users.id, { onDelete: 'set null' }),
  isDefault: text('is_default').default('false'), // 'true' для встроенных наборов
  thumbnail: text('thumbnail'),
  createdAt: timestamp('created_at').defaultNow(),
});

export const stickers = pgTable('stickers', {
  id: bigserial('id', { mode: 'number' }).primaryKey(),
  packId: bigint('pack_id', { mode: 'number' }).references(() => stickerPacks.id, { onDelete: 'cascade' }).notNull(),
  imageUrl: text('image_url').notNull(),
  emoji: text('emoji').default('😊'),
  width: integer('width'),
  height: integer('height'),
  createdAt: timestamp('created_at').defaultNow(),
});

// ========================================
// Жалобы на сообщения
// ========================================
export const reports = pgTable('reports', {
  id: bigserial('id', { mode: 'number' }).primaryKey(),
  messageId: bigint('message_id', { mode: 'number' }).references(() => messages.id, { onDelete: 'cascade' }).notNull(),
  reporterId: bigint('reporter_id', { mode: 'number' }).references(() => users.id, { onDelete: 'cascade' }).notNull(),
  reason: text('reason').notNull(), // причина жалобы
  createdAt: timestamp('created_at').defaultNow(),
  resolved: text('resolved').default('false'), // 'true' если обработана
});

// ========================================
// Общие темы (для шаринга по ссылке)
// ========================================
export const sharedThemes = pgTable('shared_themes', {
  id: bigserial('id', { mode: 'number' }).primaryKey(),
  shareId: text('share_id').unique().notNull(), // короткий ID для ссылки
  themeData: jsonb('theme_data').notNull(), // полный объект ThemeConfig
  creatorUid: text('creator_uid'), // uid создателя (если авторизован)
  creatorUsername: text('creator_username'), // username создателя
  createdAt: timestamp('created_at').defaultNow(),
});

// ========================================
// Блокировки пользователей (двунаправленные)
// ========================================
export const userBlocks = pgTable('user_blocks', {
  id: bigserial('id', { mode: 'number' }).primaryKey(),
  blockerUid: text('blocker_uid').notNull(), // кто заблокировал
  blockedUid: text('blocked_uid').notNull(), // кого заблокировали
  createdAt: timestamp('created_at').defaultNow(),
});

// ========================================
// Жалобы на пользователей
// ========================================
export const userReports = pgTable('user_reports', {
  id: bigserial('id', { mode: 'number' }).primaryKey(),
  targetUid: text('target_uid').notNull(), // на кого жалуются
  reporterUid: text('reporter_uid').notNull(), // кто жалуется
  reason: text('reason').notNull(), // причина жалобы
  description: text('description'), // дополнительное описание
  status: text('status').default('pending'), // 'pending' | 'resolved' | 'dismissed'
  adminNote: text('admin_note'), // заметка админа
  createdAt: timestamp('created_at').defaultNow(),
  resolvedAt: timestamp('resolved_at'),
});

// ========================================
// Статусы push-уведомлений и сообщений
// ========================================
export const messageStatuses = pgTable('message_statuses', {
  id: bigserial('id', { mode: 'number' }).primaryKey(),
  messageId: bigint('message_id', { mode: 'number' }).references(() => messages.id, { onDelete: 'cascade' }).notNull(),
  userId: bigint('user_id', { mode: 'number' }).references(() => users.id, { onDelete: 'cascade' }).notNull(),
  status: text('status').notNull(), // 'pending' | 'sent' | 'delivered' | 'opened' | 'read'
  pushSentAt: timestamp('push_sent_at'),
  pushDeliveredAt: timestamp('push_delivered_at'),
  openedAt: timestamp('opened_at'),
  readAt: timestamp('read_at'),
  createdAt: timestamp('created_at').defaultNow(),
  updatedAt: timestamp('updated_at').defaultNow(),
});

// ========================================
// Мульти-аккаунты (как в Telegram)
// ========================================
export const accounts = pgTable('accounts', {
  id: bigserial('id', { mode: 'number' }).primaryKey(),
  ownerUid: text('owner_uid').notNull(),   // uid основного (первичного) аккаунта
  userUid: text('user_uid').notNull().unique(), // uid привязанного аккаунта
  displayName: text('display_name'),
  email: text('email'),
  phoneNumber: text('phone_number'),
  photoUrl: text('photo_url'),
  createdAt: timestamp('created_at').defaultNow(),
}, (table) => [
  index('accounts_owner_uid_idx').on(table.ownerUid),
]);

// ========================================
// Активные сессии / Устройства
// ========================================
export const sessions = pgTable('sessions', {
  id: bigserial('id', { mode: 'number' }).primaryKey(),
  sessionUid: text('session_uid').unique().notNull(),
  userUid: text('user_uid').notNull(),
  browser: text('browser'),
  os: text('os'),
  deviceType: text('device_type').default('desktop'),
  ipAddress: text('ip_address'),
  location: text('location'),
  lastActive: timestamp('last_active').defaultNow(),
  createdAt: timestamp('created_at').defaultNow(),
  revoked: boolean('revoked').default(false),
}, (table) => [
  index('sessions_user_uid_idx').on(table.userUid),
]);

// ========================================
// Admin Permissions (V0.8.0)
// ========================================
export const adminPermissions = pgTable('admin_permissions', {
  id: bigserial('id', { mode: 'number' }).primaryKey(),
  chatId: bigint('chat_id', { mode: 'number' }).references(() => chats.id, { onDelete: 'cascade' }).notNull(),
  userUid: text('user_uid').notNull(),
  canEditInfo: boolean('can_edit_info').default(false),
  canEditAvatar: boolean('can_edit_avatar').default(false),
  canDeleteMessages: boolean('can_delete_messages').default(false),
  canRemoveMembers: boolean('can_remove_members').default(false),
  canInviteMembers: boolean('can_invite_members').default(false),
  canManageAdmins: boolean('can_manage_admins').default(false),
  canEditUsername: boolean('can_edit_username').default(false),
  canManageInvites: boolean('can_manage_invites').default(false),
  canPinMessages: boolean('can_pin_messages').default(false),
  createdAt: timestamp('created_at').defaultNow(),
  updatedAt: timestamp('updated_at').defaultNow(),
}, (table) => [
  index('admin_permissions_chat_id_idx').on(table.chatId),
  index('admin_permissions_user_uid_idx').on(table.userUid),
]);

// ========================================
// Invite Links (V0.8.0)
// ========================================
export const inviteLinks = pgTable('invite_links', {
  id: bigserial('id', { mode: 'number' }).primaryKey(),
  chatId: bigint('chat_id', { mode: 'number' }).references(() => chats.id, { onDelete: 'cascade' }).notNull(),
  token: text('token').unique().notNull(),
  createdBy: text('created_by').notNull(),
  createdAt: timestamp('created_at').defaultNow(),
  clickCount: integer('click_count').default(0),
  joinCount: integer('join_count').default(0),
  revoked: boolean('revoked').default(false),
  revokedAt: timestamp('revoked_at'),
}, (table) => [
  index('invite_links_chat_id_idx').on(table.chatId),
  index('invite_links_token_idx').on(table.token),
]);

// ========================================
// Admin Logs (V0.8.0)
// ========================================
export const adminLogs = pgTable('admin_logs', {
  id: bigserial('id', { mode: 'number' }).primaryKey(),
  chatId: bigint('chat_id', { mode: 'number' }).references(() => chats.id, { onDelete: 'set null' }),
  actorUid: text('actor_uid').notNull(),
  action: text('action').notNull(),
  targetUid: text('target_uid'),
  details: jsonb('details'),
  createdAt: timestamp('created_at').defaultNow(),
}, (table) => [
  index('admin_logs_chat_id_idx').on(table.chatId),
]);

// ========================================
// User Music Status (Now Playing & Static)
// ========================================
export const userMusicStatus = pgTable('user_music_status', {
  userUid: text('user_uid').primaryKey(),
  isPlaying: boolean('is_playing').default(false),
  currentTrack: jsonb('current_track'),
  playbackPosition: integer('playback_position').default(0),
  staticTrack: jsonb('static_track'),
  broadcastEnabled: boolean('broadcast_enabled').default(true),
  privacy: text('privacy').default('everyone'), // 'everyone' | 'contacts' | 'nobody'
  updatedAt: timestamp('updated_at').defaultNow(),
});

// ========================================
// User Music Favorites
// ========================================
export const userMusicFavorites = pgTable('user_music_favorites', {
  id: bigserial('id', { mode: 'number' }).primaryKey(),
  userUid: text('user_uid').notNull(),
  trackId: text('track_id').notNull(),
  trackData: jsonb('track_data').notNull(),
  createdAt: timestamp('created_at').defaultNow(),
}, (table) => [
  index('user_music_favorites_user_uid_idx').on(table.userUid),
  index('user_music_favorites_track_id_idx').on(table.trackId),
]);

// ========================================
// User Music History
// ========================================
export const userMusicHistory = pgTable('user_music_history', {
  id: bigserial('id', { mode: 'number' }).primaryKey(),
  userUid: text('user_uid').notNull(),
  trackId: text('track_id').notNull(),
  trackData: jsonb('track_data').notNull(),
  playedAt: timestamp('played_at').defaultNow(),
}, (table) => [
  index('user_music_history_user_uid_idx').on(table.userUid),
]);

