/**
 * Chat routes — CRUD: list, create, update, delete, invite, join
 */
import { Express } from 'express';
import { JwtRequest } from '../../src/middleware/jwtAuth.ts';
import { requireAuth } from '../../src/middleware/jwtAuth.ts';
import { chatsRateLimit } from '../../src/middleware/security.ts';
import {
  getChatsForUser,
  createChat,
  updateChat,
  getUser,
  deleteChatCompletely,
} from '../../src/db/helpers.ts';
import { validate, ChatSchema, ChatUpdateSchema } from '../../src/middleware/validate.ts';
import { logger } from '../services/logger.ts';
import {
  setInviteToken,
  getInviteChatId,
  deleteInviteToken,
  revokeInviteTokensByChatId,
  generateInviteToken,
} from '../services/invite-store.ts';

export function setupChatCrudRoutes(app: Express) {
  // Список чатов пользователя
  app.get('/api/chats', requireAuth, chatsRateLimit, async (req: JwtRequest, res) => {
    try {
      const uid = req.user!.uid;
      const all = req.query.all === 'true';
      const userChats = await getChatsForUser(uid, all);

      // Add unread message count for each chat
      try {
        const { db: dbConn } = await import('../../src/db/index.ts');
        const { sql: drizzleSql } = await import('drizzle-orm');

        // Get user numeric ID
        const userResult = await dbConn.execute(drizzleSql`SELECT id FROM users WHERE uid = ${uid}`);
        const userId = userResult?.rows?.[0]?.id;
        if (userId) {
          // Count unread messages per chat
          const unreadResult = await dbConn.execute(drizzleSql`
            SELECT chat_id, COUNT(*)::int as unread_count
            FROM messages m
            LEFT JOIN message_statuses ms ON ms.message_id = m.id AND ms.user_id = ${userId}
            WHERE m.sender_id != ${userId}
              AND ms.id IS NULL
            GROUP BY chat_id
          `);
          const unreadMap = new Map<number, number>();
          for (const row of (unreadResult?.rows || [])) {
            unreadMap.set(Number(row.chat_id), Number(row.unread_count));
          }

          // Merge unread counts into chat objects
          for (const chat of userChats) {
            (chat as any).unreadCount = unreadMap.get((chat as any).idNumeric || 0) || 0;
          }
        }
      } catch (unreadErr) {
        logger.warn({ err: unreadErr }, 'Failed to fetch unread counts (non-fatal)');
      }

      res.json(userChats);
    } catch (err: unknown) {
      logger.error({ err }, "Get chats error");
      res.status(500).json({ error: err.message });
    }
  });

  // Создание чата
  app.post('/api/chats', requireAuth, validate(ChatSchema), async (req: JwtRequest, res) => {
    try {
      const chatData = { ...req.body };
      if (chatData.id && !chatData.chatUid) {
        chatData.chatUid = chatData.id;
        delete chatData.id;
      }
      if (chatData.creatorId && typeof chatData.creatorId === 'string') {
        const creator = await getUser(chatData.creatorId);
        if (creator) {
          chatData.creatorId = creator.id;
        } else {
          return res.status(404).json({ error: 'Creator user not found' });
        }
      }

      // Валидация username: проверка уникальности (без учёта регистра)
      if (chatData.username) {
        const cleanUsername = chatData.username.trim().toLowerCase();
        if (cleanUsername.length < 5) {
          return res.status(400).json({ error: 'Username чата должен содержать минимум 5 символов' });
        }
        if (!/^[a-zA-Z0-9_]+$/.test(cleanUsername)) {
          return res.status(400).json({ error: 'Username чата должен содержать только латинские буквы, цифры и подчёркивание' });
        }
        const { isChatUsernameTaken } = await import('../../src/db/helpers.ts');
        if (await isChatUsernameTaken(cleanUsername)) {
          return res.status(409).json({ error: 'Этот username уже занят. Выберите другой.' });
        }
        chatData.username = cleanUsername;
      }

      // Дедупликация приватных чатов: если уже есть приватный чат между теми же участниками — возвращаем его
      if (chatData.type === 'private' && Array.isArray(chatData.participants) && chatData.participants.length === 2) {
        const existingChats = await getChatsForUser(chatData.participants[0], false);
        for (const existing of existingChats) {
          if (existing.type === 'private') {
            const eps = existing.participants || [];
            if (eps.includes(chatData.participants[0]) && eps.includes(chatData.participants[1])) {
              logger.info(`[Chat] 🔄 Duplicate private chat detected, returning existing: ${existing.id}`);
              return res.json(existing);
            }
          }
        }
      }

      // Для каналов и групп: добавляем создателя как админа (по UID)
      if ((chatData.type === 'channel' || chatData.type === 'group') && req.user?.uid) {
        if (!chatData.admins) chatData.admins = [];
        if (!chatData.admins.includes(req.user.uid)) {
          chatData.admins = [...chatData.admins, req.user.uid];
        }
      }

      const chat = await createChat(chatData);

      // Логируем создание канала/группы
      if (chatData.type === 'channel' || chatData.type === 'group') {
        const { logAdminAction } = await import('../../src/db/helpers.ts');
        logAdminAction({
          chatId: chat.id,
          actorUid: req.user!.uid,
          action: chatData.type === 'channel' ? 'channel_created' : 'group_created',
        });
      }
      // Всегда возвращаем chatUid как id для фронтенда
      res.json({
        ...chat,
        id: chat.chatUid || String(chat.id),
        idNumeric: chat.id,
      });
    } catch (err: unknown) {
      logger.error({ err }, "Create chat error");
      res.status(500).json({ error: err.message });
    }
  });

  // Обновление чата
  app.post('/api/chats/:chatId/update', requireAuth, validate(ChatUpdateSchema), async (req: JwtRequest, res) => {
    try {
      const uid = req.user!.uid;
      const chatId = req.params.chatId;
      logger.info(`[UPDATE CHAT] chatId: ${chatId}, type: ${typeof chatId}, body:`, req.body);

      const { getChat } = await import('../../src/db/helpers.ts');
      const currentChat: Record<string, unknown> | null = await getChat(chatId);

      const sensitiveFields = ['avatar', 'name', 'description', 'admins', 'bannedUsers', 'mutedBy', 'username'];
      const isGroupOrChannel = currentChat && (currentChat.type === 'group' || currentChat.type === 'channel');
      const hasSensitiveUpdate = Object.keys(req.body).some(key => sensitiveFields.includes(key));
      const isPinningInGroup = isGroupOrChannel && req.body.pinnedMessageUid !== undefined;

      if (hasSensitiveUpdate || isPinningInGroup) {
        if (currentChat) {
          const isAdmin = currentChat.admins?.includes(uid);
          const isCreator = currentChat.creatorId === uid || currentChat.creatorUid === uid;
          const { getUserByUid } = await import('../../src/db/auth.ts');
          const userObj = await getUserByUid(uid);
          const isGlobalAdmin = userObj?.role === 'admin';
          if (!isAdmin && !isCreator && !isGlobalAdmin) {
            return res.status(403).json({ error: 'Only chat administrators can modify this field' });
          }
        }
      }

      // Валидация username при обновлении
      if (req.body.username !== undefined && req.body.username !== null && req.body.username !== '') {
        const cleanUsername = String(req.body.username).trim().toLowerCase();
        if (cleanUsername.length < 5) {
          return res.status(400).json({ error: 'Username чата должен содержать минимум 5 символов' });
        }
        if (!/^[a-zA-Z0-9_]+$/.test(cleanUsername)) {
          return res.status(400).json({ error: 'Username чата должен содержать только латинские буквы, цифры и подчёркивание' });
        }
        const { isChatUsernameTaken } = await import('../../src/db/helpers.ts');
        const excludeId = currentChat?.id;
        if (await isChatUsernameTaken(cleanUsername, excludeId)) {
          return res.status(409).json({ error: 'Этот username уже занят. Выберите другой.' });
        }
        req.body.username = cleanUsername;
      }

      const chat = await updateChat(chatId, req.body);
      if (!chat) {
        return res.status(404).json({ error: 'Chat not found' });
      }

      // Логируем敏感ные действия
      if (isGroupOrChannel) {
        const { logAdminAction } = await import('../../src/db/helpers.ts');
        const loggableActions: Record<string, string> = {
          name: 'name_changed',
          description: 'description_changed',
          avatar: 'avatar_changed',
          admins: 'admins_changed',
          username: 'username_changed',
        };
        for (const key of Object.keys(req.body)) {
          if (loggableActions[key]) {
            logAdminAction({
              chatId: chat.id,
              actorUid: uid,
              action: loggableActions[key],
              details: { field: key },
            });
          }
        }
      }

      res.json(chat);
    } catch (err: unknown) {
      logger.error({ err }, "Update chat error");
      res.status(500).json({ error: err.message });
    }
  });

  // Invite link generation
  app.post('/api/chats/:chatId/invite', requireAuth, async (req: JwtRequest, res) => {
    try {
      const uid = req.user!.uid;
      const chatId = req.params.chatId;

      const { getChat } = await import('../../src/db/helpers.ts');
      const chat: Record<string, unknown> & { id?: number; type?: string; participants?: string[]; members?: string[]; admins?: string[]; creatorId?: number; creatorUid?: string } = await getChat(chatId);
      if (!chat) {
        return res.status(404).json({ error: 'Chat not found' });
      }

      if (chat.type !== 'group' && chat.type !== 'channel') {
        return res.status(400).json({ error: 'Invite links are only for groups and channels' });
      }

      const isAdmin = chat.admins?.includes(uid);
      const isCreator = chat.creatorId === uid || chat.creatorUid === uid;
      if (!isAdmin && !isCreator) {
        return res.status(403).json({ error: 'Only admins can generate invite links' });
      }

      const token = generateInviteToken();
      await setInviteToken(token, chatId);

      const host = req.get('host') || 'localhost:4080';
      const proto = req.protocol || 'http';
      const link = `${proto}://${host}/chat?token=${token}`;
      res.json({ token, link });
    } catch (err: unknown) {
      logger.error({ err }, "Generate invite error");
      res.status(500).json({ error: err.message });
    }
  });

  // Join chat by invite token
  app.post('/api/chats/join/:token', requireAuth, async (req: JwtRequest, res) => {
    try {
      const uid = req.user!.uid;
      const { token } = req.params;
      if (!token) {
        return res.status(400).json({ error: 'Token is required' });
      }

      const chatId = await getInviteChatId(token);
      if (!chatId) {
        return res.status(404).json({ error: 'Invalid or expired invite token' });
      }

      const { getChat, updateChat } = await import('../../src/db/helpers.ts');
      const chat: Record<string, unknown> & { id?: number; type?: string; participants?: string[]; members?: string[]; admins?: string[]; creatorId?: number; creatorUid?: string } = await getChat(chatId);
      if (!chat) {
        return res.status(404).json({ error: 'Chat not found' });
      }

      const participants = chat.participants || [];
      const members = chat.members || [];

      if (!participants.includes(uid)) {
        participants.push(uid);
      }
      if (!members.includes(uid)) {
        members.push(uid);
      }

      await updateChat(chatId, { participants, members });
      await deleteInviteToken(token);
      res.json({ success: true, chatId });
    } catch (err: unknown) {
      logger.error({ err }, "Join by token error");
      res.status(500).json({ error: err.message });
    }
  });

  // Revoke all invite links for a chat
  app.post('/api/chats/:chatId/revoke-invites', requireAuth, async (req: JwtRequest, res) => {
    try {
      const uid = req.user!.uid;
      const chatId = req.params.chatId;

      const { getChat } = await import('../../src/db/helpers.ts');
      const chat: Record<string, unknown> & { id?: number; type?: string; participants?: string[]; members?: string[]; admins?: string[]; creatorId?: number; creatorUid?: string } = await getChat(chatId);
      if (!chat) {
        return res.status(404).json({ error: 'Chat not found' });
      }

      const isAdmin = chat.admins?.includes(uid);
      const isCreator = chat.creatorId === uid || chat.creatorUid === uid;
      if (!isAdmin && !isCreator) {
        return res.status(403).json({ error: 'Only admins can revoke invite links' });
      }

      await revokeInviteTokensByChatId(chatId);
      res.json({ success: true });
    } catch (err: unknown) {
      logger.error({ err }, "Revoke invites error");
      res.status(500).json({ error: err.message });
    }
  });

  // Удалить чат (via /delete)
  app.delete('/api/chats/:chatId/delete', requireAuth, async (req: JwtRequest, res) => {
    try {
      const uid = req.user!.uid;
      const chatId = req.params.chatId;

      const { getUserByUid } = await import('../../src/db/auth.ts');
      const user = await getUserByUid(uid);
      if (!user) {
        return res.status(404).json({ error: 'User not found' });
      }

      const { getChat } = await import('../../src/db/helpers.ts');
      const chat: Record<string, unknown> & { id?: number; type?: string; participants?: string[]; members?: string[]; admins?: string[]; creatorId?: number; creatorUid?: string } = await getChat(chatId);
      if (!chat) {
        return res.status(404).json({ error: 'Chat not found' });
      }

      const isCreator = chat.creatorId === user.id;
      const isChatAdmin = chat.admins?.includes(uid);
      const isSuperAdmin = user.role === 'admin';
      if (!isCreator && !isChatAdmin && !isSuperAdmin) {
        return res.status(403).json({ error: 'Only chat creator, chat administrators or super administrators can delete this chat' });
      }

      const result = await deleteChatCompletely(chatId);
      res.json(result);
    } catch (err: unknown) {
      res.status(500).json({ error: err.message });
    }
  });

  // Удалить чат (via direct DELETE /api/chats/:chatId)
  app.delete('/api/chats/:chatId', requireAuth, async (req: JwtRequest, res) => {
    try {
      const uid = req.user!.uid;
      const chatId = req.params.chatId;

      const { getUserByUid } = await import('../../src/db/auth.ts');
      const user = await getUserByUid(uid);
      if (!user) {
        return res.status(404).json({ error: 'User not found' });
      }

      const { getChat } = await import('../../src/db/helpers.ts');
      const chat: Record<string, unknown> & { id?: number; type?: string; participants?: string[]; members?: string[]; admins?: string[]; creatorId?: number; creatorUid?: string } = await getChat(chatId);
      if (!chat) {
        return res.status(404).json({ error: 'Chat not found' });
      }

      const isCreator = chat.creatorId === user.id;
      const isChatAdmin = chat.admins?.includes(uid);
      const isSuperAdmin = user.role === 'admin';
      if (!isCreator && !isChatAdmin && !isSuperAdmin) {
        return res.status(403).json({ error: 'Only chat creator, chat administrators or super administrators can delete this chat' });
      }

      const result = await deleteChatCompletely(chatId);
      res.json(result);
    } catch (err: unknown) {
      res.status(500).json({ error: err.message });
    }
  });
}