import { Express } from 'express';
import { randomUUID } from 'crypto';
import { logger, ctx } from '../services/logger.ts';
import { JwtRequest } from '../../src/middleware/jwtAuth.ts';
import { requireAuth } from '../../src/middleware/jwtAuth.ts';
import {
  getAccountsByOwnerUid,
  getAccountByIdAndOwner,
  addAccount,
  removeAccount,
  isAccountLinked,
  findUserByUsername,
  resolveOwnerUid,
} from '../../src/db/accounts.ts';
import { getUserByUid, verifyUserPassword } from '../../src/db/auth.ts';
import { createUserWithPassword } from '../../src/db/auth.ts';
import { createSession } from '../../src/db/sessions.ts';
import { signJwt, signRefreshJwt } from '../../src/lib/auth.ts';
import express from 'express';

function setRefreshTokenCookie(res: express.Response, token: string) {
  res.cookie('refresh_token', token, {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'strict',
    path: '/',
    maxAge: 3 * 24 * 60 * 60 * 1000, // 3 дня
  });
}

export async function setupAccountsRoutes(app: Express) {
  // ========================================
  // GET /api/accounts — список всех аккаунтов текущего пользователя
  // ========================================
  app.get('/api/accounts', requireAuth, async (req: JwtRequest, res) => {
    const log = ctx(req);
    try {
      const ownerUid = await resolveOwnerUid(req.user!.uid);
      const accountList = await getAccountsByOwnerUid(ownerUid);

      // Добавляем текущий (основной) аккаунт в начало списка
      const currentUser = await getUserByUid(ownerUid);
      const mainAccount = currentUser
        ? {
            id: 0, // 0 = основной аккаунт (не в таблице accounts)
            ownerUid: ownerUid,
            userUid: ownerUid,
            displayName: currentUser.displayName,
            email: currentUser.email,
            phoneNumber: currentUser.phoneNumber,
            photoUrl: currentUser.photoURL,
            createdAt: currentUser.createdAt,
            isMain: true,
          }
        : null;

      res.json({
        accounts: [
          ...(mainAccount ? [mainAccount] : []),
          ...accountList.map((a) => ({ ...a, isMain: false })),
        ],
      });
    } catch (err: unknown) {
      log.error({ err }, '[ACCOUNTS] List error');
      res.status(500).json({ error: err.message || 'Failed to list accounts.' });
    }
  });

  // ========================================
  // POST /api/accounts — добавить новый аккаунт (регистрация)
  // ========================================
  app.post('/api/accounts', requireAuth, async (req: JwtRequest, res) => {
    const log = ctx(req);
    try {
      const ownerUid = await resolveOwnerUid(req.user!.uid);
      const { username, password, displayName } = req.body;

      if (!username || !password) {
        return res.status(400).json({ error: 'Username and password are required.' });
      }
      if (typeof password !== 'string' || password.length < 6) {
        return res.status(400).json({ error: 'Password must be at least 6 characters.' });
      }

      const cleanUsername = username.trim().toLowerCase();
      if (!/^[a-z0-9_\-]+$/.test(cleanUsername)) {
        return res.status(400).json({ error: 'Invalid username. Use lowercase letters, numbers, underscores, and hyphens.' });
      }

      // Проверяем, не существует ли уже пользователь с таким username
      const existingUser = await findUserByUsername(cleanUsername);
      if (existingUser) {
        return res.status(409).json({ error: 'Username already exists.' });
      }

      // Создаём нового пользователя (email = username@qwcroll.com, как в Auth.tsx)
      const email = `${cleanUsername}@qwcroll.com`;
      const uid = randomUUID();
      const createdUser = await createUserWithPassword({
        uid,
        email,
        password,
        username: cleanUsername,
        displayName: displayName || cleanUsername,
        status: 'online',
      });

      // Привязываем к основному аккаунту
      let accountRecord;
      try {
        accountRecord = await addAccount({
          ownerUid,
          userUid: uid,
          displayName: createdUser.displayName,
          email: createdUser.email,
          phoneNumber: createdUser.phoneNumber,
          photoUrl: createdUser.photoURL,
        });
      } catch (addErr: any) {
        log.warn({ err: addErr, ownerUid, uid }, '[ACCOUNTS] Failed to link account in DB');
        accountRecord = { id: 0, ownerUid, userUid: uid, displayName: createdUser.displayName, email: createdUser.email, phoneNumber: null, photoUrl: null, createdAt: new Date() };
      }

      // Создаём сессию для нового аккаунта
      const userAgent = req.headers['user-agent'] || null;
      const ip = req.ip || req.socket?.remoteAddress || null;
      const { sessionUid } = await createSession({ userUid: uid, userAgent, ipAddress: ip });
      const token = signJwt(createdUser, sessionUid);
      const refreshToken = signRefreshJwt(createdUser, sessionUid);
      setRefreshTokenCookie(res, refreshToken);

      log.info({ ownerUid, newAccountUid: uid }, '[ACCOUNTS] New account added');
      res.json({
        token,
        user: createdUser,
        account: { ...accountRecord, isMain: false },
      });
    } catch (err: unknown) {
      log.error({ err }, '[ACCOUNTS] Add error');
      res.status(500).json({ error: err.message || 'Failed to add account.' });
    }
  });

  // ========================================
  // POST /api/accounts/login — войти в существующий аккаунт и привязать
  // ========================================
  app.post('/api/accounts/login', requireAuth, async (req: JwtRequest, res) => {
    const log = ctx(req);
    try {
      const ownerUid = await resolveOwnerUid(req.user!.uid);
      const { username, password } = req.body;

      if (!username || !password) {
        return res.status(400).json({ error: 'Username and password are required.' });
      }

      // Формируем email из username, как в Auth.tsx
      const email = `${username.trim().toLowerCase()}@qwcroll.com`;

      // Проверяем учётные данные
      const user = await verifyUserPassword(email, password);
      if (!user) {
        return res.status(401).json({ error: 'Invalid credentials.' });
      }

      // Нельзя привязать самого себя
      if (user.uid === ownerUid) {
        return res.status(400).json({ error: 'Cannot add your own account.' });
      }

      // Проверяем, не привязан ли уже
      const alreadyLinked = await isAccountLinked(ownerUid, user.uid);
      if (alreadyLinked) {
        return res.status(409).json({ error: 'Account is already linked.' });
      }

      // Привязываем
      let accountRecord;
      try {
        accountRecord = await addAccount({
          ownerUid,
          userUid: user.uid,
          displayName: user.displayName,
          email: user.email,
          phoneNumber: user.phoneNumber,
          photoUrl: user.photoURL,
        });
      } catch (addErr: any) {
        log.warn({ err: addErr, ownerUid, linkedUid: user.uid }, '[ACCOUNTS] Failed to link account in DB (may already be linked)');
        accountRecord = { id: 0, ownerUid, userUid: user.uid, displayName: user.displayName, email: user.email, phoneNumber: null, photoUrl: null, createdAt: new Date() };
      }

      // Создаём сессию для привязываемого аккаунта
      const userAgent = req.headers['user-agent'] || null;
      const ip = req.ip || req.socket?.remoteAddress || null;
      const { sessionUid } = await createSession({ userUid: user.uid, userAgent, ipAddress: ip });
      const token = signJwt(user, sessionUid);
      const refreshToken = signRefreshJwt(user, sessionUid);
      setRefreshTokenCookie(res, refreshToken);

      log.info({ ownerUid, linkedUid: user.uid }, '[ACCOUNTS] Existing account linked');
      res.json({
        token,
        user,
        account: { ...accountRecord, isMain: false },
      });
    } catch (err: unknown) {
      log.error({ err }, '[ACCOUNTS] Login-link error');
      res.status(500).json({ error: err.message || 'Failed to link account.' });
    }
  });

  // ========================================
  // PUT /api/accounts/:id/switch — переключиться на привязанный аккаунт
  // ========================================
  app.put('/api/accounts/:id/switch', requireAuth, async (req: JwtRequest, res) => {
    const log = ctx(req);
    try {
      const ownerUid = await resolveOwnerUid(req.user!.uid);
      const targetId = parseInt(req.params.id, 10);

      if (isNaN(targetId)) {
        return res.status(400).json({ error: 'Invalid account id.' });
      }

      // Если id === 0, переключаемся на основной аккаунт
      if (targetId === 0) {
        const mainUser = await getUserByUid(ownerUid);
        if (!mainUser) {
          return res.status(404).json({ error: 'Main account not found.' });
        }

        const userAgent = req.headers['user-agent'] || null;
        const ip = req.ip || req.socket?.remoteAddress || null;
        const { sessionUid } = await createSession({ userUid: ownerUid, userAgent, ipAddress: ip });
        const token = signJwt(mainUser, sessionUid);
        const refreshToken = signRefreshJwt(mainUser, sessionUid);
        setRefreshTokenCookie(res, refreshToken);

        log.info({ ownerUid }, '[ACCOUNTS] Switched to main account');
        res.json({ token, user: mainUser });
        return;
      }

      // Проверяем владение
      const account = await getAccountByIdAndOwner(targetId, ownerUid);
      if (!account) {
        return res.status(404).json({ error: 'Account not found.' });
      }

      // Получаем данные пользователя
      const targetUser = await getUserByUid(account.userUid);
      if (!targetUser) {
        return res.status(404).json({ error: 'Linked user not found (may have been deleted).' });
      }

      // Создаём новую сессию
      const userAgent = req.headers['user-agent'] || null;
      const ip = req.ip || req.socket?.remoteAddress || null;
      const { sessionUid } = await createSession({ userUid: account.userUid, userAgent, ipAddress: ip });
      const token = signJwt(targetUser, sessionUid);
      const refreshToken = signRefreshJwt(targetUser, sessionUid);
      setRefreshTokenCookie(res, refreshToken);

      log.info({ ownerUid, switchToUid: account.userUid }, '[ACCOUNTS] Switched account');
      res.json({ token, user: targetUser });
    } catch (err: unknown) {
      log.error({ err }, '[ACCOUNTS] Switch error');
      res.status(500).json({ error: err.message || 'Failed to switch account.' });
    }
  });

  // ========================================
  // DELETE /api/accounts/:id — удалить привязанный аккаунт
  // ========================================
  app.delete('/api/accounts/:id', requireAuth, async (req: JwtRequest, res) => {
    const log = ctx(req);
    try {
      const ownerUid = await resolveOwnerUid(req.user!.uid);
      const targetId = parseInt(req.params.id, 10);

      if (isNaN(targetId)) {
        return res.status(400).json({ error: 'Invalid account id.' });
      }

      if (targetId === 0) {
        return res.status(400).json({ error: 'Cannot delete the main account from here.' });
      }

      const deleted = await removeAccount(targetId, ownerUid);
      if (!deleted) {
        return res.status(404).json({ error: 'Account not found.' });
      }

      log.info({ ownerUid, removedId: targetId }, '[ACCOUNTS] Account unlinked');
      res.json({ success: true });
    } catch (err: unknown) {
      log.error({ err }, '[ACCOUNTS] Delete error');
      res.status(500).json({ error: err.message || 'Failed to delete account.' });
    }
  });
}