import fs from 'fs';
import path from 'path';
import multer from 'multer';
import sharp from 'sharp';
import { randomUUID } from 'crypto';
import { UPLOADS_DIR, ALLOWED_MIMETYPES, getMaxSizeForMime, validateMagicBytes } from '../config.ts';

export const findExistingUpload = (uploadDir: string, hash: string) => {
  const files = fs.readdirSync(uploadDir);
  return files.find(file => file.startsWith(hash));
};

// ========================================
// Secure Multer Storage Engine
// ========================================
export const secureUploadStorage: multer.StorageEngine = {
  _handleFile(req, file, callback) {
    const ext = path.extname(file.originalname || '').toLowerCase();
    const uniqueName = `${randomUUID()}${ext}`;
    const dest = path.join(UPLOADS_DIR, uniqueName);
    const maxBytes = getMaxSizeForMime(file.mimetype);
    const writeStream = fs.createWriteStream(dest);
    let totalBytes = 0;
    let magicChecked = false;
    let rejected = false;
    const header = Buffer.alloc(16);
    let headerPos = 0;

    file.stream.on('data', (chunk: Buffer) => {
      if (rejected) return;
      totalBytes += chunk.length;
      // Enforce per-category size limit
      if (totalBytes > maxBytes) {
        rejected = true;
        file.stream.destroy();
        writeStream.destroy(() => fs.unlink(dest, () => {}));
        const mb = Math.round(maxBytes / (1024 * 1024));
        return callback(new Error(`Размер файла превышает лимит для ${file.mimetype.split('/')[0]}-файлов (${mb} MB)`));
      }
      // Validate magic bytes from the first 4–16 bytes
      if (!magicChecked && headerPos < 16) {
        const copyLen = Math.min(chunk.length, 16 - headerPos);
        chunk.copy(header, headerPos, 0, copyLen);
        headerPos += copyLen;
        if (headerPos >= 4) {
          magicChecked = true;
          if (!validateMagicBytes(file.mimetype, header)) {
            rejected = true;
            file.stream.destroy();
            writeStream.destroy(() => fs.unlink(dest, () => {}));
            return callback(new Error(`Файл не соответствует указанному типу: magic bytes не совпадают с ${file.mimetype}`));
          }
        }
      }
      writeStream.write(chunk);
    });

    file.stream.on('end', () => {
      if (rejected) return;
      writeStream.end(() => {
        callback(null, { path: dest, size: totalBytes, filename: uniqueName });
      });
    });

    file.stream.on('error', (err) => {
      writeStream.destroy();
      fs.unlink(dest, () => {});
      callback(err);
    });
  },
  _removeFile(req, file, callback) {
    fs.unlink(file.path, callback);
  },
};

/**
 * Генерирует thumbnail (150x150) и medium (600x600) для image/* файлов.
 * Возвращает { thumbUrl, mediumUrl } или null если не image.
 */
export async function generateThumbnails(filePath: string): Promise<{ thumbUrl: string; mediumUrl: string } | null> {
  const ext = path.extname(filePath).toLowerCase();
  const imageExts = ['.jpg', '.jpeg', '.png', '.gif', '.webp', '.bmp', '.tiff'];
  if (!imageExts.includes(ext)) return null;

  try {
    const dir = path.dirname(filePath);
    const baseName = path.basename(filePath, ext);
    const thumbName = `${baseName}_thumb.webp`;
    const mediumName = `${baseName}_medium.webp`;
    const thumbPath = path.join(dir, thumbName);
    const mediumPath = path.join(dir, mediumName);

    // Thumbnail 150x150
    await sharp(filePath)
      .resize(150, 150, { fit: 'cover' })
      .webp({ quality: 80 })
      .toFile(thumbPath);

    // Medium 600x600
    await sharp(filePath)
      .resize(600, 600, { fit: 'inside' })
      .webp({ quality: 82 })
      .toFile(mediumPath);

    return {
      thumbUrl: `/api/download/${thumbName}`,
      mediumUrl: `/api/download/${mediumName}`,
    };
  } catch (err) {
    // Non-critical — log and return null
    console.warn('[Upload] Thumbnail generation failed:', err.message);
    return null;
  }
}

export function createUploadMiddleware() {
  return multer({
    storage: secureUploadStorage,
    fileFilter: (req, file, cb) => {
      if (ALLOWED_MIMETYPES.has(file.mimetype)) {
        cb(null, true);
      } else {
        cb(new Error(`Разрешены только: ${[...ALLOWED_MIMETYPES].join(', ')}`));
      }
    },
    limits: { fileSize: 100 * 1024 * 1024 },
  });
}