/**
 * Health check endpoint — проверка PostgreSQL, uptime, version
 */
import { Express, Request, Response } from 'express';

const START_TIME = Date.now();

export function setupHealthRoutes(app: Express) {
  app.get('/api/health', async (_req: Request, res: Response) => {
    const checks: Record<string, any> = {};
    let isHealthy = true;

    // 1) PostgreSQL check — SELECT 1
    try {
      const { db } = await import('../../src/db/index.ts');
      const { sql } = await import('drizzle-orm');
      const start = Date.now();
      await db.execute(sql`SELECT 1`);
      const latencyMs = Date.now() - start;
      checks.postgres = { status: 'ok', latencyMs };
    } catch (err: unknown) {
      checks.postgres = { status: 'error', message: err.message };
      isHealthy = false;
    }

    // 2) Uptime
    const uptimeMs = Date.now() - START_TIME;
    const uptimeSec = Math.floor(uptimeMs / 1000);
    const hours = Math.floor(uptimeSec / 3600);
    const minutes = Math.floor((uptimeSec % 3600) / 60);
    const seconds = uptimeSec % 60;

    // 3) Version from package.json
    let version = 'unknown';
    try {
      const fs = await import('fs');
      const path = await import('path');
      const pkgPath = path.resolve('package.json');
      const pkg = JSON.parse(fs.readFileSync(pkgPath, 'utf8'));
      version = pkg.version || 'unknown';
    } catch {}

    res.status(isHealthy ? 200 : 503).json({
      status: isHealthy ? 'ok' : 'degraded',
      version,
      uptime: `${hours}h ${minutes}m ${seconds}s`,
      uptimeMs,
      timestamp: new Date().toISOString(),
      checks,
    });
  });
}