import { Express } from 'express';
import { randomUUID } from 'crypto';
import { JwtRequest } from '../../src/middleware/jwtAuth.ts';
import { requireAuth } from '../../src/middleware/jwtAuth.ts';
import {
  chatsRateLimit,
  searchRateLimit,
} from '../../src/middleware/security.ts';
import {
  syncUser,
  getUsers,
  getUser,
  deleteUserCompletely,
} from '../../src/db/helpers.ts';
import { validate, UserSyncSchema, PrivacySettingsSchema, ContactSchema } from '../../src/middleware/validate.ts';
import { logger } from '../services/logger.ts';

export function setupUserRoutes(app: Express) {
  app.post("/api/users/sync", requireAuth, validate(UserSyncSchema), async (req: JwtRequest, res) => {
    try {
      const uid = req.user!.uid;
      const data = req.body;
      const user = await syncUser(uid, data);
      res.json(user);
    } catch (err: unknown) {
      logger.error({ err }, "Sync user error");
      res.status(500).json({ error: err.message });
    }
  });

  app.get("/api/users", requireAuth, async (req: JwtRequest, res) => {
    try {
      const requesterUid = req.user!.uid;
      const usersList = await getUsers();
      const sanitized = usersList.map((u: any) => {
        if (u.uid === requesterUid || req.user?.role === 'admin') return u;
        const { email, recoveryEmail, phoneNumber, passwordHash, ...publicData } = u;
        return publicData;
      });
      res.json(sanitized);
    } catch (err: unknown) {
      logger.error({ err }, "Get users error");
      res.status(500).json({ error: (err as any).message });
    }
  });

  app.get("/api/users/:uid", requireAuth, async (req: JwtRequest, res) => {
    try {
      logger.info(`[GET USER] uid: ${req.params.uid}`);
      const user = await getUser(req.params.uid);
      if (!user) {
        logger.info(`[GET USER] ❌ User not found: ${req.params.uid}`);
        return res.status(404).json({ error: "User not found" });
      }
      logger.info(`[GET USER] ✅ Found user: ${user.displayName}`);

      const requesterUid = req.user!.uid;
      const targetUid = req.params.uid;
      const { getBlockDirection } = await import("../../src/db/admin.ts");
      const blockDir = await getBlockDirection(requesterUid, targetUid);
      const safeUser: any = { ...user };

      if (blockDir === 'by_me') {
        safeUser._blockedByMe = true;
      } else if (blockDir === 'by_them' || blockDir === 'both') {
        safeUser.photoURL = null;
        safeUser.lastSeen = null;
        safeUser._blockedMe = true;
      }

      // Apply privacy settings (only for other users viewing this profile)
      if (requesterUid !== targetUid && !safeUser._blockedByMe) {
        const privacy: any = user.privacySettings || {
          online_status: 'everyone', bio: 'everyone', avatar: 'everyone',
          username: 'everyone', messages: 'everyone',
        };

        // Check if requester is in contacts
        const { db } = await import("../../src/db/index.ts");
        const { userContacts } = await import("../../src/db/schema.ts");
        const { eq, and } = await import("drizzle-orm");
        const contactCheck = await db.select().from(userContacts)
          .where(and(eq(userContacts.ownerUid, targetUid), eq(userContacts.contactUid, requesterUid)))
          .limit(1);
        const isContact = contactCheck.length > 0;

        // Apply online_status privacy
        if (privacy.online_status === 'nobody' || (privacy.online_status === 'contacts' && !isContact)) {
          safeUser.status = 'offline';
          safeUser.lastSeen = null;
          safeUser._onlineHidden = true;
        }

        // Apply avatar privacy
        if (privacy.avatar === 'nobody' || (privacy.avatar === 'contacts' && !isContact)) {
          safeUser.photoURL = null;
          safeUser._avatarHidden = true;
        }

        // Apply username privacy
        if (privacy.username === 'nobody' || (privacy.username === 'contacts' && !isContact)) {
          safeUser.username = null;
          safeUser._usernameHidden = true;
        }

        // Apply bio privacy
        if (privacy.bio === 'nobody' || (privacy.bio === 'contacts' && !isContact)) {
          safeUser.bio = null;
          safeUser._bioHidden = true;
        }
      }

      res.json(safeUser);
    } catch (err: unknown) {
      logger.error({ err }, "Get user error");
      res.status(500).json({ error: err.message });
    }
  });

  // Пункт 4: Легковесный список чатов
  app.get("/api/chats/list", requireAuth, chatsRateLimit, async (req: JwtRequest, res) => {
    try {
      const uid = req.user!.uid;
      const all = req.query.all === 'true';
      const { getChatsListForUser } = await import("../../src/db/helpers.ts");
      const chatsList = await getChatsListForUser(uid, all);
      res.json(chatsList);
    } catch (err: unknown) {
      logger.error({ err }, "Get chats list error");
      res.status(500).json({ error: err.message });
    }
  });

  // ========================================
  // GET /api/users/search?q=... — поиск по username, displayName (без паролей)
  // ========================================
  app.get("/api/users/search", requireAuth, searchRateLimit, async (req: JwtRequest, res) => {
    try {
      const q = (req.query.q as string || '').trim();
      if (q.length < 2) {
        return res.json([]);
      }

      const { db } = await import("../../src/db/index.ts");
      const { users } = await import("../../src/db/schema.ts");
      const { or, ilike } = await import("drizzle-orm");

      const likePattern = `%${q}%`;
      const results = await db
        .select({
          uid: users.uid,
          email: users.email,
          username: users.username,
          displayName: users.displayName,
          photoURL: users.photoURL,
          status: users.status,
          lastSeen: users.lastSeen,
          bio: users.bio,
        })
        .from(users)
        .where(
          or(
            ilike(users.username, likePattern),
            ilike(users.displayName, likePattern),
          )
        )
        .limit(20);

      res.json(results);
    } catch (err: unknown) {
      logger.error({ err }, "User search error");
      res.status(500).json({ error: err.message });
    }
  });

  // ========================================
  // Privacy Settings
  // ========================================

  // GET /api/user/privacy — получить настройки приватности текущего пользователя
  app.get("/api/user/privacy", requireAuth, async (req: JwtRequest, res) => {
    try {
      const uid = req.user!.uid;
      const { db } = await import("../../src/db/index.ts");
      const { users } = await import("../../src/db/schema.ts");
      const { eq } = await import("drizzle-orm");

      const result = await db.select({ privacySettings: users.privacySettings })
        .from(users)
        .where(eq(users.uid, uid))
        .limit(1);

      if (!result[0]) {
        return res.status(404).json({ error: "User not found" });
      }

      res.json(result[0].privacySettings || {
        online_status: 'everyone',
        bio: 'everyone',
        avatar: 'everyone',
        username: 'everyone',
        messages: 'everyone',
      });
    } catch (err: unknown) {
      logger.error({ err }, "Get privacy settings error");
      res.status(500).json({ error: err.message });
    }
  });

  // PUT /api/user/privacy — обновить настройки приватности
  app.put("/api/user/privacy", requireAuth, validate(PrivacySettingsSchema), async (req: JwtRequest, res) => {
    try {
      const uid = req.user!.uid;
      const { db } = await import("../../src/db/index.ts");
      const { users } = await import("../../src/db/schema.ts");
      const { eq } = await import("drizzle-orm");

      const result = await db.update(users)
        .set({ privacySettings: req.body.privacySettings, updatedAt: new Date() })
        .where(eq(users.uid, uid))
        .returning();

      if (!result[0]) {
        return res.status(404).json({ error: "User not found" });
      }

      res.json(result[0].privacySettings);
    } catch (err: unknown) {
      logger.error({ err }, "Update privacy settings error");
      res.status(500).json({ error: err.message });
    }
  });

  // ========================================
  // Contacts
  // ========================================

  // GET /api/user/contacts — список контактов
  app.get("/api/user/contacts", requireAuth, async (req: JwtRequest, res) => {
    try {
      const uid = req.user!.uid;
      const { db } = await import("../../src/db/index.ts");
      const { userContacts, users } = await import("../../src/db/schema.ts");
      const { eq } = await import("drizzle-orm");

      const contacts = await db
        .select({
          id: userContacts.id,
          contactUid: userContacts.contactUid,
          alias: userContacts.alias,
          createdAt: userContacts.createdAt,
          displayName: users.displayName,
          photoURL: users.photoURL,
          username: users.username,
          status: users.status,
          lastSeen: users.lastSeen,
        })
        .from(userContacts)
        .leftJoin(users, eq(userContacts.contactUid, users.uid))
        .where(eq(userContacts.ownerUid, uid));

      res.json(contacts);
    } catch (err: unknown) {
      logger.error({ err }, "Get contacts error");
      res.status(500).json({ error: err.message });
    }
  });

  // POST /api/user/contacts — добавить контакт
  app.post("/api/user/contacts", requireAuth, validate(ContactSchema), async (req: JwtRequest, res) => {
    try {
      const uid = req.user!.uid;
      const { contactUid, alias } = req.body;
      const { db } = await import("../../src/db/index.ts");
      const { userContacts } = await import("../../src/db/schema.ts");
      const { eq, and } = await import("drizzle-orm");

      // Проверяем, нет ли уже такого контакта
      const existing = await db.select().from(userContacts)
        .where(and(eq(userContacts.ownerUid, uid), eq(userContacts.contactUid, contactUid)))
        .limit(1);

      if (existing.length > 0) {
        return res.status(409).json({ error: "Contact already exists" });
      }

      const result = await db.insert(userContacts)
        .values({ ownerUid: uid, contactUid, alias: alias || null })
        .returning();

      res.json(result[0]);
    } catch (err: unknown) {
      logger.error({ err }, "Add contact error");
      res.status(500).json({ error: err.message });
    }
  });

  // DELETE /api/user/contacts/:contactUid — удалить контакт
  app.delete("/api/user/contacts/:contactUid", requireAuth, async (req: JwtRequest, res) => {
    try {
      const uid = req.user!.uid;
      const { contactUid } = req.params;
      const { db } = await import("../../src/db/index.ts");
      const { userContacts } = await import("../../src/db/schema.ts");
      const { eq, and } = await import("drizzle-orm");

      await db.delete(userContacts)
        .where(and(eq(userContacts.ownerUid, uid), eq(userContacts.contactUid, contactUid)));

      res.json({ success: true });
    } catch (err: unknown) {
      logger.error({ err }, "Delete contact error");
      res.status(500).json({ error: err.message });
    }
  });

  // PUT /api/user/contacts/:contactUid — обновить контакт (alias)
  app.put("/api/user/contacts/:contactUid", requireAuth, async (req: JwtRequest, res) => {
    try {
      const uid = req.user!.uid;
      const { contactUid } = req.params;
      const { alias } = req.body;
      const { db } = await import("../../src/db/index.ts");
      const { userContacts } = await import("../../src/db/schema.ts");
      const { eq, and } = await import("drizzle-orm");

      const result = await db.update(userContacts)
        .set({ alias: alias || null })
        .where(and(eq(userContacts.ownerUid, uid), eq(userContacts.contactUid, contactUid)))
        .returning();

      res.json(result[0] || { success: true });
    } catch (err: unknown) {
      logger.error({ err }, "Update contact error");
      res.status(500).json({ error: err.message });
    }
  });

  app.delete("/api/user/delete-all-data", requireAuth, async (req: JwtRequest, res) => {
    try {
      const uid = req.user!.uid;
      const result = await deleteUserCompletely(uid);
      res.json(result);
    } catch (err: unknown) {
      res.status(500).json({ error: err.message });
    }
  });
}
