/** Реакция на сообщение */
export const ReactionSchema = z.object({
  emoji: z
    .string()
    .min(1, "Эмодзи обязателен")
    .refine(
      (val) => {
        // Проверяем, что строка содержит ровно один grapheme-кластер с emoji
        if (typeof Intl !== "undefined" && (Intl as any).Segmenter) {
          const segmenter = new (Intl as any).Segmenter("en", { granularity: "grapheme" });
          const segments = [...segmenter.segment(val)];
          if (segments.length !== 1) return false;
          return /\p{Emoji_Presentation}|\p{Extended_Pictographic}/u.test(segments[0].segment);
        }
        // Fallback: простая проверка (один символ, emoji-диапазон)
        return val.length <= 8 && /\p{Emoji_Presentation}|\p{Extended_Pictographic}/u.test(val);
      },
      { message: "Должен быть ровно один Unicode emoji" }
    ),
});

