/**
 * Sticker routes — CRUD стикер-паков и стикеров
 *
 * POST   /api/stickers/market            — каталог с количеством (auth)
 * POST   /api/admin/sticker-packs        — создать пак (admin)
 * POST   /api/stickers/:packId/add       — добавить стикер в пак (admin)
 * DELETE /api/stickers/:packId/stickers/:id — удалить стикер (admin)
 */
import { Express } from 'express';
import { JwtRequest } from '../../src/middleware/jwtAuth.ts';
import { requireAuth } from '../../src/middleware/jwtAuth.ts';
import { requireAdmin } from '../../src/middleware/adminAuth.ts';
import { logger } from '../services/logger.ts';

export function setupStickerRoutes(app: Express) {
  // ========================================
  // GET /api/stickers/market — каталог стикер-паков с количеством стикеров
  // ========================================
  app.get('/api/stickers/market', requireAuth, async (_req: JwtRequest, res) => {
    try {
      const { db } = await import('../../src/db/index.ts');
      const { stickerPacks, stickers } = await import('../../src/db/schema.ts');
      const { eq, count, sql } = await import('drizzle-orm');

      // Получаем все паки с подсчётом стикеров
      const result = await db.execute(sql`
        SELECT
          sp.id,
          sp.name,
          sp.title,
          sp.is_default,
          sp.thumbnail,
          sp.created_at,
          sp.author_id,
          COUNT(s.id)::int AS sticker_count
        FROM sticker_packs sp
        LEFT JOIN stickers s ON s.pack_id = sp.id
        GROUP BY sp.id
        ORDER BY sp.created_at DESC
      `);

      res.json(result?.rows || result);
    } catch (err: unknown) {
      logger.error({ err }, 'Sticker market error');
      res.status(500).json({ error: err.message });
    }
  });

  // ========================================
  // POST /api/admin/sticker-packs — создать стикер-пак (admin only)
  // Body: { name, title, thumbnail?, isDefault? }
  // ========================================
  app.post('/api/admin/sticker-packs', requireAdmin, async (req: JwtRequest, res) => {
    try {
      const { name, title, thumbnail, isDefault } = req.body;

      if (!name || !title) {
        return res.status(400).json({ error: 'name and title are required.' });
      }

      const { db } = await import('../../src/db/index.ts');
      const { stickerPacks } = await import('../../src/db/schema.ts');

      const inserted = await db.insert(stickerPacks).values({
        name,
        title,
        thumbnail: thumbnail || null,
        isDefault: isDefault ? 'true' : 'false',
        authorId: req.user!.id,
      }).returning();

      logger.info(`[Stickers] Pack created: ${name} by ${req.user!.uid}`);
      res.json(inserted[0]);
    } catch (err: unknown) {
      if (err.code === '23505') { // unique violation
        return res.status(409).json({ error: 'Pack with this name already exists.' });
      }
      logger.error({ err }, 'Create sticker pack error');
      res.status(500).json({ error: err.message });
    }
  });

  // ========================================
  // POST /api/stickers/:packId/add — добавить стикер в пак (admin only)
  // Body: { imageUrl, emoji?, width?, height? }
  // ========================================
  app.post('/api/stickers/:packId/add', requireAdmin, async (req: JwtRequest, res) => {
    try {
      const packId = parseInt(req.params.packId);
      if (isNaN(packId)) {
        return res.status(400).json({ error: 'Invalid pack id.' });
      }

      const { imageUrl, emoji, width, height } = req.body;

      if (!imageUrl) {
        return res.status(400).json({ error: 'imageUrl is required.' });
      }

      const { db } = await import('../../src/db/index.ts');
      const { stickers, stickerPacks } = await import('../../src/db/schema.ts');
      const { eq } = await import('drizzle-orm');

      // Проверяем что пак существует
      const pack = await db.select().from(stickerPacks).where(eq(stickerPacks.id, packId)).limit(1);
      if (!pack.length) {
        return res.status(404).json({ error: 'Sticker pack not found.' });
      }

      const inserted = await db.insert(stickers).values({
        packId,
        imageUrl,
        emoji: emoji || '😊',
        width: width || null,
        height: height || null,
      }).returning();

      logger.info(`[Stickers] Sticker added to pack ${packId}`);
      res.json(inserted[0]);
    } catch (err: unknown) {
      logger.error({ err }, 'Add sticker error');
      res.status(500).json({ error: err.message });
    }
  });

  // ========================================
  // DELETE /api/stickers/:packId/stickers/:id — удалить стикер (admin only)
  // ========================================
  app.delete('/api/stickers/:packId/stickers/:id', requireAdmin, async (req: JwtRequest, res) => {
    try {
      const stickerId = parseInt(req.params.id);
      if (isNaN(stickerId)) {
        return res.status(400).json({ error: 'Invalid sticker id.' });
      }

      const { db } = await import('../../src/db/index.ts');
      const { stickers } = await import('../../src/db/schema.ts');
      const { eq } = await import('drizzle-orm');

      const deleted = await db.delete(stickers).where(eq(stickers.id, stickerId)).returning();

      if (!deleted.length) {
        return res.status(404).json({ error: 'Sticker not found.' });
      }

      logger.info(`[Stickers] Sticker ${stickerId} deleted`);
      res.json({ success: true, deleted: deleted[0] });
    } catch (err: unknown) {
      logger.error({ err }, 'Delete sticker error');
      res.status(500).json({ error: err.message });
    }
  });
}