import { Express } from 'express';
import { JwtRequest } from '../../src/middleware/jwtAuth.ts';
import { requireAuth } from '../../src/middleware/jwtAuth.ts';
import { randomBytes } from 'crypto';
import { validate, ThemeShareSchema } from '../../src/middleware/validate.ts';
import { logger } from '../services/logger.ts';

export function setupThemeRoutes(app: Express) {
  app.post("/api/themes/share", requireAuth, validate(ThemeShareSchema), async (req: JwtRequest, res) => {
    try {
      const uid = req.user?.uid;
      const { themeData, creatorUsername } = req.body;
      let shareId = randomBytes(4).toString('hex').substring(0, 6);

      const { db, ensureDbReady } = await import("../../src/db/index.ts");
      const { sharedThemes } = await import("../../src/db/schema.ts");
      await ensureDbReady();

      await db.insert(sharedThemes).values({
        shareId,
        themeData,
        creatorUid: uid || null,
        creatorUsername: creatorUsername || null,
      });

      res.json({ shareId, url: `/theme/${shareId}` });
    } catch (err: unknown) {
      logger.error({ err }, "Share theme error");
      res.status(500).json({ error: err.message });
    }
  });

  app.get("/api/themes/share/:shareId", async (req, res) => {
    try {
      const { shareId } = req.params;
      if (!shareId) {
        return res.status(400).json({ error: "shareId is required" });
      }

      const { db, ensureDbReady } = await import("../../src/db/index.ts");
      const { sharedThemes } = await import("../../src/db/schema.ts");
      const { eq } = await import("drizzle-orm");
      await ensureDbReady();

      const results = await db.select().from(sharedThemes).where(eq(sharedThemes.shareId, shareId)).limit(1);
      if (results.length === 0) {
        return res.status(404).json({ error: "Theme not found" });
      }

      const row = results[0];
      res.json({
        shareId: row.shareId,
        themeData: typeof row.themeData === 'string' ? JSON.parse(row.themeData) : row.themeData,
        creatorUid: row.creatorUid,
        creatorUsername: row.creatorUsername,
        createdAt: row.createdAt,
      });
    } catch (err: unknown) {
      logger.error({ err, cause: err?.cause }, "Get shared theme detailed error:");
      res.status(500).json({ error: err.message, cause: err?.cause?.message || err?.cause });
    }
  });
}