/**
 * WebRTC call signals store — Redis-backed с fallback на in-memory.
 *
 * Key scheme:
 *   call:signals                    — Sorted Set (score = timestamp, member = JSON)
 *   call:delivered:{uid}            — Set of delivered signal IDs
 *   call:user:{uid}                 — Set of signal IDs for a user (for cleanup)
 */
import { getRedis } from './redis.ts';
import { randomUUID } from 'crypto';

export interface CallSignal {
  id: string;
  fromUid: string;
  fromName: string;
  fromAvatar?: string;
  toUid: string;
  type: 'offer' | 'answer' | 'candidate' | 'decline' | 'end';
  isVideo: boolean;
  data?: any;
  timestamp: number;
}

const SIGNALS_KEY = 'call:signals';
const DELIVERED_PREFIX = 'call:delivered:';
const USER_SIGNALS_PREFIX = 'call:user:';

export async function addCallSignal(signal: CallSignal): Promise<void> {
  const redis = getRedis();
  if (!signal.id) signal.id = randomUUID();
  if (!signal.timestamp) signal.timestamp = Date.now();

  const json = JSON.stringify(signal);

  if ((redis as any).zAdd) {
    // Real Redis — use Sorted Set
    await (redis as any).zAdd(SIGNALS_KEY, { score: signal.timestamp, value: json });
    await redis.sAdd(`${USER_SIGNALS_PREFIX}${signal.fromUid}`, signal.id);
    await redis.sAdd(`${USER_SIGNALS_PREFIX}${signal.toUid}`, signal.id);
  } else {
    // MockRedis fallback — use list
    await redis.lpush(SIGNALS_KEY, json);
  }
}

export async function getSignalsForUser(uid: string): Promise<CallSignal[]> {
  const redis = getRedis();
  const now = Date.now();
  const maxAge = 30000;

  if ((redis as any).zRangeByScore) {
    // Real Redis
    const raw = await (redis as any).zRangeByScore(SIGNALS_KEY, String(now - maxAge), String(now));
    return raw
      .map((s: string) => { try { return JSON.parse(s); } catch { return null; } })
      .filter((s: CallSignal | null) => s && (s.toUid === uid || s.fromUid === uid));
  }

  // MockRedis fallback
  const all = await redis.lrange(SIGNALS_KEY, 0, -1);
  return all
    .map((s: string) => { try { return JSON.parse(s); } catch { return null; } })
    .filter((s: CallSignal | null) => s && (s.toUid === uid || s.fromUid === uid) && now - s.timestamp < maxAge);
}

export async function markSignalDelivered(uid: string, signalId: string): Promise<void> {
  const redis = getRedis();
  await redis.sAdd(`${DELIVERED_PREFIX}${uid}`, signalId);
}

export async function getDeliveredSignalIds(uid: string): Promise<Set<string>> {
  const redis = getRedis();
  const ids = await redis.sMembers(`${DELIVERED_PREFIX}${uid}`);
  return new Set(ids);
}

export async function cleanOldSignals(maxAge: number = 30000): Promise<void> {
  const redis = getRedis();
  const cutoff = Date.now() - maxAge;

  if ((redis as any).zRemRangeByScore) {
    await (redis as any).zRemRangeByScore(SIGNALS_KEY, '-inf', String(cutoff));
  }
  // MockRedis: list-based, no efficient range delete — skip
}

export async function removeUserCallSignals(uid: string): Promise<void> {
  const redis = getRedis();
  await redis.del(`${DELIVERED_PREFIX}${uid}`);
  await redis.del(`${USER_SIGNALS_PREFIX}${uid}`);
}

// Legacy sync exports for backward compatibility (non-async callers)
export let callSignals: CallSignal[] = [];
export const deliveredCallSignals = new Map<string, Set<string>>();

export function setCallSignals(signals: CallSignal[]): void { callSignals = signals; }
export function filterCallSignals(predicate: (s: CallSignal) => boolean): void { callSignals = callSignals.filter(predicate); }