import { Request, Response, NextFunction } from "express";
import { timingSafeEqual } from "crypto";
import { getUserByUid } from "../db/auth.ts";
import { JwtRequest, requireAuth } from "./jwtAuth.ts";

export interface AdminRequest extends JwtRequest {
  adminUser?: any;
}

/**
 * Middleware для админ-роутов.
 * Проверяет JWT аутентификацию + роль admin у пользователя.
 * Также можно передать X-Admin-Secret для доступа без JWT.
 */
export const requireAdmin = async (req: JwtRequest & AdminRequest, res: Response, next: NextFunction) => {
  try {
    // Вариант 1: Секретный заголовок (для прямого доступа)
    // Принимаем только серверные ADMIN_SECRET или ADMIN_KEY (без VITE_ префикса)
    const adminSecret = req.headers['x-admin-secret'];
    if (adminSecret && typeof adminSecret === 'string') {
      const allowedSecrets = [process.env.ADMIN_SECRET, process.env.ADMIN_KEY].filter(
        (s): s is string => typeof s === 'string' && s.length > 0
      );
      const a = Buffer.from(adminSecret);
      for (const secret of allowedSecrets) {
        const b = Buffer.from(secret);
        if (a.length === b.length && timingSafeEqual(a, b)) {
          return next();
        }
      }
    }

    // Вариант 2: Переданное состояние req.user с флагом isAdmin
    if (req.user && req.user.isAdmin) {
      return next();
    }

    // Вариант 3: Выполнение аутентификации JWT если req.user еще не заполнено
    const runAuth = async () => {
      try {
        const uid = req.user?.uid;
        if (!uid) {
          return res.status(401).json({ error: "Not authenticated" });
        }

        const user = await getUserByUid(uid);
        if (!user) {
          return res.status(401).json({ error: "User not found" });
        }

        const isAdmin = user.role === 'admin';
        req.user.isAdmin = isAdmin;
        req.user.role = user.role;

        if (!isAdmin) {
          return res.status(403).json({ error: 'Forbidden: Admin access required' });
        }

        req.adminUser = user;
        next();
      } catch (err) {
        console.error("Admin auth error:", err);
        res.status(500).json({ error: "Admin authentication failed" });
      }
    };

    if (req.user) {
      await runAuth();
    } else {
      requireAuth(req, res, () => {
        runAuth();
      });
    }
  } catch (err) {
    console.error("Admin middleware error:", err);
    res.status(500).json({ error: "Admin middleware failed" });
  }
};

/**
 * Проверяет, является ли пользователь забаненным.
 * Используется в обычных роутах для блокировки действий.
 */
export const checkNotBanned = async (req: AdminRequest, res: Response, next: NextFunction) => {
  try {
    const { requireAuth } = await import("./jwtAuth.ts");
    requireAuth(req as any, res, async () => {
      try {
        const uid = (req as any).user?.uid;
        if (!uid) return res.status(401).json({ error: "Not authenticated" });

        const user = await getUserByUid(uid);
        if (user?.role === 'banned') {
          return res.status(403).json({ error: "Your account has been banned." });
        }

        next();
      } catch (err) {
        console.error("Ban check error:", err);
        res.status(500).json({ error: "Ban check failed" });
      }
    });
  } catch (err) {
    console.error("Ban check middleware error:", err);
    res.status(500).json({ error: "Ban check middleware failed" });
  }
};