/**
 * WebSocket server — typing, presence (Redis-backed), heartbeat (3 miss → close).
 *
 * Features:
 *   - Typing indicators: client → {type:"typing", chatId} → broadcast to chat members
 *   - Presence: connect → online in Redis (TTL 60s), disconnect → offline + broadcast
 *   - Heartbeat: ping every 30s, 3 consecutive misses → terminate
 *   - permessage-deflate compression
 *   - EventEmitter-based broadcast
 *   - Rate limiting per connection (60 msg/min)
 */
import { WebSocketServer, WebSocket } from 'ws';
import { IncomingMessage } from 'http';
import { Server } from 'http';
import { EventEmitter } from 'events';
import { verifyJwt } from '../../src/lib/auth.ts';
import { logger } from './logger.ts';
import { getRedis } from './redis.ts';

// ── Types ──────────────────────────────────────────────────────────────────

interface PresenceInfo {
  uid: string;
  status: 'online' | 'offline';
  lastSeen: number;
  offlineAt?: number;
}

interface ClientMeta {
  uid: string;
  isAlive: boolean;
  missedPongs: number;
  rateCount: number;
  rateResetAt: number;
}

// ── State ──────────────────────────────────────────────────────────────────

const wsClients = new Map<string, Set<WebSocket>>();
const clientMeta = new WeakMap<WebSocket, ClientMeta>();

const HEARTBEAT_INTERVAL = 30_000;  // 30 seconds
const MAX_MISSED_PONGS = 3;         // 3 misses → terminate
const PRESENCE_TTL = 60;            // Redis TTL 60 seconds
const RATE_LIMIT = 60;              // messages per minute

// ── EventEmitter for broadcasts ────────────────────────────────────────────

export const wsEvents = new EventEmitter();
wsEvents.setMaxListeners(100);

// ── Helpers ────────────────────────────────────────────────────────────────

export function authenticateWsRequest(req: IncomingMessage): string | null {
  try {
    const url = new URL(req.url!, `http://${req.headers.host}`);
    const token = url.searchParams.get('token');
    if (!token) return null;
    const decoded = verifyJwt(token);
    return decoded.uid || null;
  } catch {
    return null;
  }
}

// ── Broadcast ──────────────────────────────────────────────────────────────

export function broadcastStatusUpdate(targetUids: string[], data: any) {
  const payload = JSON.stringify(data);
  for (const uid of targetUids) {
    const clients = wsClients.get(uid);
    if (clients) {
      for (const ws of clients) {
        if (ws.readyState === WebSocket.OPEN) {
          ws.send(payload);
        }
      }
      logger.info(`[WS] Broadcast to ${uid}: ${clients.size} clients`);
    }
  }
  wsEvents.emit('broadcast', targetUids, data);
}

export function broadcastAll(data: any) {
  const payload = JSON.stringify(data);
  wss?.clients?.forEach((client) => {
    if (client.readyState === WebSocket.OPEN) {
      client.send(payload);
    }
  });
}

// ── Presence (Redis-backed with TTL) ───────────────────────────────────────

export function getPresence(uid: string): PresenceInfo | undefined {
  // Try Redis first, fallback to in-memory
  return undefined; // Will be fetched async via getPresenceAsync
}

export async function getPresenceAsync(uid: string): Promise<PresenceInfo | null> {
  const redis = getRedis();
  try {
    const raw = await redis.get(`presence:${uid}`);
    if (raw) return JSON.parse(raw) as PresenceInfo;
  } catch {}
  return null;
}

export function getAllPresence(): PresenceInfo[] {
  return []; // Use getAllPresenceAsync for Redis-backed
}

export async function getAllPresenceAsync(): Promise<PresenceInfo[]> {
  const redis = getRedis();
  try {
    const keys = await redis.keys('presence:*');
    const results: PresenceInfo[] = [];
    for (const key of keys) {
      const raw = await redis.get(key);
      if (raw) results.push(JSON.parse(raw));
    }
    return results;
  } catch {
    return [];
  }
}

export function getPresenceForUids(uids: string[]): PresenceInfo[] {
  return []; // Use getPresenceForUidsAsync
}

export async function getPresenceForUidsAsync(uids: string[]): Promise<PresenceInfo[]> {
  const redis = getRedis();
  const results: PresenceInfo[] = [];
  for (const uid of uids) {
    try {
      const raw = await redis.get(`presence:${uid}`);
      if (raw) results.push(JSON.parse(raw));
    } catch {}
  }
  return results;
}

async function setOnline(uid: string): Promise<void> {
  const redis = getRedis();
  const info: PresenceInfo = {
    uid,
    status: 'online',
    lastSeen: Date.now(),
    offlineAt: undefined,
  };
  try {
    await redis.set(`presence:${uid}`, JSON.stringify(info), 'EX', PRESENCE_TTL);
  } catch {}

  // Broadcast presence to all connected clients
  broadcastStatusUpdate([], {
    type: 'presence_update',
    presence: [info],
  });
}

async function setOffline(uid: string): Promise<void> {
  const redis = getRedis();
  const info: PresenceInfo = {
    uid,
    status: 'offline',
    lastSeen: Date.now(),
    offlineAt: Date.now(),
  };
  try {
    await redis.set(`presence:${uid}`, JSON.stringify(info), 'EX', PRESENCE_TTL);
  } catch {}

  // Broadcast presence to all connected clients
  broadcastStatusUpdate([], {
    type: 'presence_update',
    presence: [info],
  });
}

async function refreshPresenceTTL(uid: string): Promise<void> {
  const redis = getRedis();
  try {
    await redis.expire(`presence:${uid}`, PRESENCE_TTL);
  } catch {}
}

// ── Typing ─────────────────────────────────────────────────────────────────

async function handleTyping(uid: string, chatId: string, chatParticipants: string[]): Promise<void> {
  if (!chatId || !Array.isArray(chatParticipants)) return;

  const payload = JSON.stringify({
    type: 'typing',
    uid,
    chatId,
    timestamp: Date.now(),
  });

  for (const participantUid of chatParticipants) {
    if (participantUid === uid) continue; // Don't send to self
    const clients = wsClients.get(participantUid);
    if (clients) {
      for (const ws of clients) {
        if (ws.readyState === WebSocket.OPEN) {
          ws.send(payload);
        }
      }
    }
  }
}

// ── WebSocket Server ───────────────────────────────────────────────────────

let wss: WebSocketServer;

export function getWebSocketServer(): WebSocketServer | null {
  return wss || null;
}

export function closeAllWebSocketConnections(): Promise<void> {
  return new Promise((resolve) => {
    if (!wss) { resolve(); return; }
    let openCount = 0;
    wss.clients.forEach((client) => {
      if (client.readyState === WebSocket.OPEN) {
        client.close(1001, 'Server shutting down');
        openCount++;
      }
    });
    logger.info(`[WS] Closed ${openCount} active connections`);

    const doClose = () => {
      wss.close(() => {
        logger.info('[WS] WebSocketServer closed');
        resolve();
      });
    };

    if (openCount === 0) {
      try { wss.close(); } catch {}
      resolve();
    } else {
      setTimeout(doClose, 1000);
    }
  });
}

export function setupWebSocket(httpServer: Server) {
  wss = new WebSocketServer({
    server: httpServer,
    path: '/ws',
    perMessageDeflate: {
      zlibDeflateOptions: {
        chunkSize: 1024,
        memLevel: 7,
        level: 3,
      },
      zlibInflateOptions: {
        chunkSize: 10 * 1024,
      },
      threshold: 256,
      concurrencyLimit: 10,
      clientNoContextTakeover: true,
      serverNoContextTakeover: true,
    },
  });

  // ── Heartbeat: ping every 30s, 3 misses → terminate ────────────────
  const heartbeatInterval = setInterval(() => {
    wss.clients.forEach((ws) => {
      const meta = clientMeta.get(ws);
      if (!meta) return;

      if (!meta.isAlive) {
        meta.missedPongs++;

        if (meta.missedPongs >= MAX_MISSED_PONGS) {
          logger.info(`[WS] Terminating unresponsive client: ${meta.uid} (missed ${meta.missedPongs} pongs)`);
          // Set offline before terminating
          setOffline(meta.uid);
          ws.terminate();
          return;
        }

        logger.debug(`[WS] Client ${meta.uid} missed pong #${meta.missedPongs}/${MAX_MISSED_PONGS}`);
      }

      meta.isAlive = false;
      if (ws.readyState === WebSocket.OPEN) {
        ws.ping();
      }
    });
  }, HEARTBEAT_INTERVAL);

  heartbeatInterval.unref();

  wss.on('close', () => {
    clearInterval(heartbeatInterval);
  });

  // ── Connection handler ─────────────────────────────────────────────
  wss.on('connection', (ws: WebSocket, req: IncomingMessage) => {
    const uid = authenticateWsRequest(req);
    if (!uid) {
      ws.close(4001, 'Unauthorized');
      return;
    }

    logger.info(`[WS] Client connected: ${uid}`);

    // Register client
    if (!wsClients.has(uid)) wsClients.set(uid, new Set());
    wsClients.get(uid)!.add(ws);

    // Set metadata
    clientMeta.set(ws, {
      uid,
      isAlive: true,
      missedPongs: 0,
      rateCount: 0,
      rateResetAt: Date.now() + 60_000,
    });

    // Set online in Redis + broadcast
    setOnline(uid);

    // ── Pong handler (heartbeat response) ───────────────────────────
    ws.on('pong', () => {
      const meta = clientMeta.get(ws);
      if (meta) {
        meta.isAlive = true;
        meta.missedPongs = 0;
        // Refresh presence TTL on every pong
        refreshPresenceTTL(uid);
      }
    });

    // ── Close handler ───────────────────────────────────────────────
    ws.on('close', () => {
      logger.info(`[WS] Client disconnected: ${uid}`);

      const clients = wsClients.get(uid);
      if (clients) {
        clients.delete(ws);
        if (clients.size === 0) {
          wsClients.delete(uid);
          // Last connection for this user — mark offline
          setOffline(uid);
        }
      }

      clientMeta.delete(ws);
    });

    // ── Error handler ───────────────────────────────────────────────
    ws.on('error', (err: any) => {
      logger.warn({ err: err.message }, `[WS] Client error: ${uid}`);
    });

    // ── Message handler with rate limiting ──────────────────────────
    ws.on('message', (data: any) => {
      const meta = clientMeta.get(ws);
      if (!meta) return;

      // Rate limit check
      const now = Date.now();
      if (now > meta.rateResetAt) {
        meta.rateCount = 0;
        meta.rateResetAt = now + 60_000;
      }
      meta.rateCount++;

      if (meta.rateCount > RATE_LIMIT) {
        ws.close(4003, 'Rate limit exceeded');
        return;
      }

      try {
        const msg = JSON.parse(data.toString());

        // ── Typing indicator ────────────────────────────────────────
        if (msg.type === 'typing' && msg.chatId) {
          const chatParticipants: string[] = msg.participants || [];
          handleTyping(uid, msg.chatId, chatParticipants);
          return;
        }

        // ── Presence query ─────────────────────────────────────────
        if (msg.type === 'get_presence' && msg.uids) {
          getPresenceForUidsAsync(msg.uids).then((presence) => {
            if (ws.readyState === WebSocket.OPEN) {
              ws.send(JSON.stringify({ type: 'presence_update', presence }));
            }
          });
          return;
        }

        // ── Music Sync Broadcast ───────────────────────────────────
        if (msg.type === 'music_sync_broadcast') {
          broadcastAll({
            type: 'user_music_status',
            uid,
            isPlaying: Boolean(msg.isPlaying),
            currentTrack: msg.currentTrack || null,
            playbackPosition: typeof msg.playbackPosition === 'number' ? msg.playbackPosition : 0,
            updatedAt: Date.now()
          });
          return;
        }

        // Emit message event for other listeners
        wsEvents.emit('message', { uid, ...msg });

        if (msg.type === 'read_chat' && msg.chatId) {
          logger.info(`[WS] Read request from ${uid} for chat ${msg.chatId}`);
        }
      } catch {}
    });

    // ── Send initial connected event ────────────────────────────────
    ws.send(JSON.stringify({
      type: 'connected',
      uid,
      timestamp: Date.now(),
    }));
  });

  return wss;
}