import express, { Express } from 'express';
import fs from 'fs';
import path from 'path';
import { randomUUID } from 'crypto';
import { JwtRequest } from '../../src/middleware/jwtAuth.ts';
import { requireAuth } from '../../src/middleware/jwtAuth.ts';
import { uploadRateLimit } from '../../src/middleware/security.ts';
import { UPLOADS_DIR } from '../config.ts';
import { createUploadMiddleware, generateThumbnails } from '../services/upload.ts';
import { processVideoWithFFmpeg, shouldTranscodeVideo } from '../services/ffmpeg.ts';
import { logger } from '../services/logger.ts';

export async function setupUploadRoutes(app: Express) {
  const uploadMiddleware = createUploadMiddleware();

  // Explicit download endpoint for media files (requires auth)
  app.get("/api/download/:filename", requireAuth, async (req: JwtRequest, res) => {
    try {
      const filename = req.params.filename;
      const filePath = path.join(UPLOADS_DIR, filename);

      if (!filePath.startsWith(UPLOADS_DIR)) {
        return res.status(403).json({ error: "Access denied" });
      }
      if (!fs.existsSync(filePath)) {
        return res.status(404).json({ error: "File not found" });
      }

      const stats = fs.statSync(filePath);
      const ext = path.extname(filename).toLowerCase();
      const mimeTypes: Record<string, string> = {
        '.jpg': 'image/jpeg',
        '.jpeg': 'image/jpeg',
        '.png': 'image/png',
        '.gif': 'image/gif',
        '.webp': 'image/webp',
        '.svg': 'image/svg+xml',
        '.pdf': 'application/pdf',
        '.mp4': 'video/mp4',
        '.webm': 'video/webm',
        '.mp3': 'audio/mpeg',
        '.wav': 'audio/wav',
        '.ogg': 'audio/ogg',
        '.m4a': 'audio/mp4',
        '.aac': 'audio/aac',
      };

      let contentType = mimeTypes[ext] || 'application/octet-stream';
      if (filename.includes('voice_')) {
        contentType = (ext === '.mp4' || ext === '.m4a') ? 'audio/mp4' : (ext === '.ogg' ? 'audio/ogg' : 'audio/webm');
      } else if (filename.includes('video_note')) {
        contentType = ext === '.mp4' ? 'video/mp4' : 'video/webm';
      }

      // Check magic bytes for precise Content-Type
      try {
        if (stats.size >= 8) {
          const fd = fs.openSync(filePath, 'r');
          const buffer = Buffer.alloc(12);
          fs.readSync(fd, buffer, 0, 12, 0);
          fs.closeSync(fd);
          const isWebm = buffer[0] === 0x1A && buffer[1] === 0x45 && buffer[2] === 0xDF && buffer[3] === 0xA3;
          const isFtyp = (buffer[4] === 0x66 && buffer[5] === 0x74 && buffer[6] === 0x79 && buffer[7] === 0x70) ||
                         (buffer[0] === 0x66 && buffer[1] === 0x74 && buffer[2] === 0x79 && buffer[3] === 0x70);
          const isOgg = buffer[0] === 0x4F && buffer[1] === 0x67 && buffer[2] === 0x67 && buffer[3] === 0x53;
          if (isWebm) {
            contentType = (filename.includes('video_note') || ext === '.webm') && !filename.includes('voice_') ? 'video/webm' : 'audio/webm';
          } else if (isFtyp) {
            contentType = (filename.includes('video_note') || ext === '.mp4') && !filename.includes('voice_') ? 'video/mp4' : 'audio/mp4';
          } else if (isOgg) {
            contentType = 'audio/ogg';
          }
        }
      } catch (_) {}

      // Handle Range Requests for video/audio streaming
      const range = req.headers.range;
      if (range) {
        const parts = range.replace(/bytes=/, "").split("-");
        const start = parseInt(parts[0], 10);
        const end = parts[1] ? parseInt(parts[1], 10) : stats.size - 1;

        if (start >= stats.size || end >= stats.size) {
          res.setHeader('Content-Range', `bytes */${stats.size}`);
          return res.status(416).json({ error: "Requested Range Not Satisfiable" });
        }

        const chunksize = (end - start) + 1;
        const fileStream = fs.createReadStream(filePath, { start, end });

        res.writeHead(206, {
          'Content-Range': `bytes ${start}-${end}/${stats.size}`,
          'Accept-Ranges': 'bytes',
          'Content-Length': chunksize,
          'Content-Type': contentType,
        });
        fileStream.pipe(res);
        return;
      }

      // Set headers for standard response
      res.setHeader('Content-Type', contentType);
      res.setHeader('Content-Length', stats.size);
      res.setHeader('Accept-Ranges', 'bytes');

      if (!contentType.startsWith('image/') && !contentType.startsWith('video/') && !contentType.startsWith('audio/')) {
        res.setHeader('Content-Disposition', `attachment; filename="${encodeURIComponent(filename)}"`);
      }

      // Stream the file
      const fileStream = fs.createReadStream(filePath);
      fileStream.pipe(res);

      fileStream.on('error', (err) => {
        logger.error({ err }, "File stream error");
        if (!res.headersSent) {
          res.status(500).json({ error: "Failed to stream file" });
        }
      });
    } catch (err: unknown) {
      logger.error({ err }, "Download error");
      res.status(500).json({ error: err.message || "Download failed" });
    }
  });

  // Multipart FormData Upload Endpoint
  app.post("/api/upload", requireAuth, uploadRateLimit, uploadMiddleware.single("file"), async (req: JwtRequest, res) => {
    try {
      if (!req.file) {
        return res.status(400).json({ error: "No file uploaded" });
      }
      let filePath = req.file.path;
      if (shouldTranscodeVideo(req.file.originalname) || shouldTranscodeVideo(req.file.filename)) {
        filePath = await processVideoWithFFmpeg(filePath);
      }
      const finalName = path.basename(filePath);
      const result: Record<string, string> = { url: `/api/download/${finalName}` };

      // Генерируем thumbnails для image/* файлов
      if (req.file.mimetype?.startsWith('image/')) {
        const thumbs = await generateThumbnails(filePath);
        if (thumbs) {
          result.thumbUrl = thumbs.thumbUrl;
          result.mediumUrl = thumbs.mediumUrl;
        }
      }

      res.json(result);
    } catch (err: unknown) {
      logger.error({ err }, "Multipart upload error");
      res.status(500).json({ error: err.message || "Failed to save upload" });
    }
  });

  // Endpoint to handle raw binary uploads (requires auth)
  app.post(
    "/api/upload-binary",
    requireAuth,
    uploadRateLimit,
    express.raw({ type: "*/*", limit: "50mb" }),
    async (req: JwtRequest, res) => {
      const startTime = Date.now();
      try {
        const filename = (req.headers["x-filename"] as string) || "upload.bin";
        logger.info(`📤 Binary upload started: ${filename}, size: ${req.body?.length || 0} bytes`);

        if (!req.body || !(req.body instanceof Buffer) || req.body.length === 0) {
          logger.error("❌ Upload failed: Missing or empty body");
          return res.status(400).json({ error: "Missing binary upload body" });
        }

        const buffer = req.body as Buffer;
        const safeFilename = path.basename(filename).replace(/[^a-zA-Z0-9_.-]/g, "_");
        const shortId = randomUUID().substring(0, 8);
        const uniqueName = `${Date.now()}_${shortId}_${safeFilename}`;
        let filePath = path.join(UPLOADS_DIR, uniqueName);
        fs.writeFileSync(filePath, buffer);

        if (shouldTranscodeVideo(filename) || shouldTranscodeVideo(uniqueName)) {
          filePath = await processVideoWithFFmpeg(filePath);
        }

        const finalName = path.basename(filePath);
        logger.info(`✅ Upload completed: ${finalName} in ${Date.now() - startTime} ms`);
        const result: Record<string, string> = { url: `/api/download/${finalName}` };

        // Генерируем thumbnails для image/* файлов
        if (filename.match(/\.(jpg|jpeg|png|gif|webp|bmp|tiff)$/i)) {
          const thumbs = await generateThumbnails(filePath);
          if (thumbs) {
            result.thumbUrl = thumbs.thumbUrl;
            result.mediumUrl = thumbs.mediumUrl;
          }
        }

        res.json(result);
      } catch (err: unknown) {
        logger.error({ err }, `❌ Upload error after ${Date.now() - startTime} ms`);
        res.status(500).json({ error: err.message || "Failed to save upload" });
      }
    }
  );

  // 🔧 Эндпоинт для ретранскодирования уже загруженных видео
  app.post("/api/reprocess-video/:filename", requireAuth, async (req: JwtRequest, res) => {
    try {
      const filename = req.params.filename;
      const filePath = path.join(UPLOADS_DIR, filename);

      if (!filePath.startsWith(UPLOADS_DIR)) {
        return res.status(403).json({ error: "Access denied" });
      }
      if (!fs.existsSync(filePath)) {
        return res.status(404).json({ error: "File not found" });
      }

      if (filename.includes('_faststart')) {
        logger.info(`[FFmpeg] ⏭️ ${filename} already reprocessed`);
        return res.json({ url: `/api/download/${filename}`, reprocessed: false });
      }

      logger.info(`[FFmpeg] 🔄 Reprocessing existing video: ${filename}`);
      const reprocessedPath = await processVideoWithFFmpeg(filePath);
      const finalName = path.basename(reprocessedPath);
      logger.info(`[FFmpeg] ✅ Reprocessed video: ${finalName}`);
      res.json({ url: `/api/download/${finalName}`, reprocessed: reprocessedPath !== filePath });
    } catch (err: unknown) {
      logger.error({ err }, "[FFmpeg] ❌ Reprocess error");
      res.status(500).json({ error: err.message || "Reprocessing failed" });
    }
  });

  // Endpoint to handle Base64 file uploads
  app.post("/api/upload-base64", requireAuth, uploadRateLimit, async (req: JwtRequest, res) => {
    try {
      const { base64, filename, mimeType } = req.body;
      if (!base64 || !filename) {
        return res.status(400).json({ error: "Missing base64 or filename" });
      }

      const safeFilename = path.basename(filename).replace(/[^a-zA-Z0-9_.-]/g, "_");
      const buffer = Buffer.from(base64, "base64");

      if (buffer.length < 1000) {
        logger.error(`❌ Base64 upload rejected: suspiciously small payload (${buffer.length} bytes) for ${filename}.`);
        return res.status(400).json({ error: `Upload appears empty or corrupted (${buffer.length} bytes received). Please try recording again.` });
      }

      const shortId = randomUUID().substring(0, 8);
      const uniqueName = `${Date.now()}_${shortId}_${safeFilename}`;
      let filePath = path.join(UPLOADS_DIR, uniqueName);
      fs.writeFileSync(filePath, buffer);

      if (shouldTranscodeVideo(filename) || shouldTranscodeVideo(uniqueName)) {
        filePath = await processVideoWithFFmpeg(filePath);
      }

        const finalName = path.basename(filePath);
          logger.info(`✅ Base64 upload completed: ${finalName}`);
        const result64: Record<string, string> = { url: `/api/download/${finalName}` };

        // Генерируем thumbnails для image/* файлов
        if (filename.match(/\.(jpg|jpeg|png|gif|webp|bmp|tiff)$/i)) {
          const thumbs = await generateThumbnails(filePath);
          if (thumbs) {
            result64.thumbUrl = thumbs.thumbUrl;
            result64.mediumUrl = thumbs.mediumUrl;
          }
        }

        res.json(result64);
    } catch (err: unknown) {
      logger.error({ err }, "Base64 upload error");
      res.status(500).json({ error: err.message || "Failed to save upload" });
    }
  });

  // ========================================
  // MEDIA SIGNED URLS — безопасная раздача медиа
  // ========================================
  const { signMediaUrl, verifyMediaSignature } = await import('../services/crypto.ts');

  app.get("/api/media-sign/:filename", requireAuth, (req: JwtRequest, res) => {
    try {
      const filename = path.basename(req.params.filename);
      const filePath = path.join(UPLOADS_DIR, filename);

      if (!filePath.startsWith(UPLOADS_DIR)) {
        return res.status(403).json({ error: "Access denied" });
      }
      if (!fs.existsSync(filePath)) {
        return res.status(404).json({ error: "File not found" });
      }

      const { sig, exp } = signMediaUrl(filename);
      const signedUrl = `/api/media/${filename}?sig=${sig}&exp=${exp}`;
      res.json({ url: signedUrl });
    } catch (err: unknown) {
      logger.error({ err }, "[MediaSign] Error");
      res.status(500).json({ error: err.message });
    }
  });

  app.get("/api/media/:filename", (req, res) => {
    try {
      const filename = path.basename(req.params.filename);
      const sig = req.query.sig as string;
      const exp = parseInt(req.query.exp as string, 10);

      if (!sig || isNaN(exp)) {
        return res.status(401).json({ error: "Missing signature parameters" });
      }

      if (!verifyMediaSignature(filename, sig, exp)) {
        return res.status(403).json({ error: "Invalid or expired media signature" });
      }

      const filePath = path.join(UPLOADS_DIR, filename);

      if (!filePath.startsWith(UPLOADS_DIR)) {
        return res.status(403).json({ error: "Access denied" });
      }
      if (!fs.existsSync(filePath)) {
        return res.status(404).json({ error: "File not found" });
      }

      const stats = fs.statSync(filePath);
      const ext = path.extname(filename).toLowerCase();
      const mimeTypes: Record<string, string> = {
        '.jpg': 'image/jpeg',
        '.jpeg': 'image/jpeg',
        '.png': 'image/png',
        '.gif': 'image/gif',
        '.webp': 'image/webp',
        '.svg': 'image/svg+xml',
        '.pdf': 'application/pdf',
        '.mp4': 'video/mp4',
        '.webm': 'video/webm',
        '.mp3': 'audio/mpeg',
        '.wav': 'audio/wav',
        '.ogg': 'audio/ogg',
        '.m4a': 'audio/mp4',
        '.aac': 'audio/aac',
      };

      let contentType = mimeTypes[ext] || 'application/octet-stream';
      if (filename.includes('voice_')) {
        contentType = (ext === '.mp4' || ext === '.m4a') ? 'audio/mp4' : (ext === '.ogg' ? 'audio/ogg' : 'audio/webm');
      } else if (filename.includes('video_note')) {
        contentType = ext === '.mp4' ? 'video/mp4' : 'video/webm';
      }

      // Check magic bytes for precise Content-Type
      try {
        if (stats.size >= 8) {
          const fd = fs.openSync(filePath, 'r');
          const buffer = Buffer.alloc(12);
          fs.readSync(fd, buffer, 0, 12, 0);
          fs.closeSync(fd);
          const isWebm = buffer[0] === 0x1A && buffer[1] === 0x45 && buffer[2] === 0xDF && buffer[3] === 0xA3;
          const isFtyp = (buffer[4] === 0x66 && buffer[5] === 0x74 && buffer[6] === 0x79 && buffer[7] === 0x70) ||
                         (buffer[0] === 0x66 && buffer[1] === 0x74 && buffer[2] === 0x79 && buffer[3] === 0x70);
          const isOgg = buffer[0] === 0x4F && buffer[1] === 0x67 && buffer[2] === 0x67 && buffer[3] === 0x53;
          if (isWebm) {
            contentType = (filename.includes('video_note') || ext === '.webm') && !filename.includes('voice_') ? 'video/webm' : 'audio/webm';
          } else if (isFtyp) {
            contentType = (filename.includes('video_note') || ext === '.mp4') && !filename.includes('voice_') ? 'video/mp4' : 'audio/mp4';
          } else if (isOgg) {
            contentType = 'audio/ogg';
          }
        }
      } catch (_) {}

      // Set security headers for media
      res.setHeader('Cache-Control', 'private, no-cache');
      res.setHeader('Referrer-Policy', 'no-referrer');
      res.setHeader('X-Content-Type-Options', 'nosniff');

      // Handle Range Requests for video/audio streaming
      const range = req.headers.range;
      if (range) {
        const parts = range.replace(/bytes=/, "").split("-");
        const start = parseInt(parts[0], 10);
        const end = parts[1] ? parseInt(parts[1], 10) : stats.size - 1;

        if (start >= stats.size || end >= stats.size) {
          res.setHeader('Content-Range', `bytes */${stats.size}`);
          return res.status(416).json({ error: "Requested Range Not Satisfiable" });
        }

        const chunksize = (end - start) + 1;
        const fileStream = fs.createReadStream(filePath, { start, end });

        res.writeHead(206, {
          'Content-Range': `bytes ${start}-${end}/${stats.size}`,
          'Accept-Ranges': 'bytes',
          'Content-Length': chunksize,
          'Content-Type': contentType,
        });
        fileStream.pipe(res);
        return;
      }

      res.setHeader('Content-Type', contentType);
      res.setHeader('Content-Length', stats.size);
      res.setHeader('Accept-Ranges', 'bytes');

      const fileStream = fs.createReadStream(filePath);
      fileStream.pipe(res);

      fileStream.on('error', (err) => {
        logger.error({ err }, "[Media] File stream error");
        if (!res.headersSent) {
          res.status(500).json({ error: "Failed to stream file" });
        }
      });
    } catch (err: unknown) {
      logger.error({ err }, "[Media] Error");
      res.status(500).json({ error: err.message || "Media access failed" });
    }
  });
}