import dotenv from 'dotenv';
import path from 'path';
import logger from './services/logger.ts';

dotenv.config({ path: path.resolve('.env') });

// ========================================
// Required Secrets
// ========================================
export const JWT_SECRET = process.env.JWT_SECRET;
export const JWT_REFRESH_SECRET = process.env.JWT_REFRESH_SECRET;
export const SESSION_SECRET = process.env.SESSION_SECRET;
export const CSRF_SECRET = process.env.CSRF_SECRET;
export const MEDIA_SECRET = process.env.MEDIA_SECRET || CSRF_SECRET;

if (!JWT_SECRET || !JWT_REFRESH_SECRET || !SESSION_SECRET || !CSRF_SECRET) {
  logger.error("[FATAL] One or more required secrets are not set in environment variables");
  if (!JWT_SECRET) logger.error("  - JWT_SECRET is missing");
  if (!JWT_REFRESH_SECRET) logger.error("  - JWT_REFRESH_SECRET is missing");
  if (!SESSION_SECRET) logger.error("  - SESSION_SECRET is missing");
  if (!CSRF_SECRET) logger.error("  - CSRF_SECRET is missing");
  logger.error("[FATAL] Generate secrets with: node -e \"console.log(require('crypto').randomBytes(32).toString('hex'))\"");
  process.exit(1);
}

// ========================================
// Server
// ========================================
export const PORT = Number(process.env.PORT) || 3000;

// ========================================
// CORS
// ========================================
export const ALLOWED_ORIGINS = (process.env.ALLOWED_ORIGINS || "")
  .split(",")
  .map((o) => o.trim())
  .filter(Boolean);

// ========================================
// Uploads
// ========================================
export const UPLOADS_DIR = path.join(process.cwd(), "uploads");

// ========================================
// QR Login
// ========================================
export const QR_TOKEN_TTL = 60_000; // 60 seconds
export const QR_POLL_INTERVAL = 2_000; // poll every 2s

// ========================================
// Media Signed URLs
// ========================================
export const MEDIA_SIGNED_URL_TTL = 60 * 60 * 1000; // 1 час

// ========================================
// File size limits
// ========================================
export const FILE_SIZE_LIMITS: Record<string, number> = {
  image: 10 * 1024 * 1024,    // 10 MB
  video: 100 * 1024 * 1024,   // 100 MB
  audio: 20 * 1024 * 1024,    // 20 MB
};

export const DEFAULT_MAX_SIZE = 50 * 1024 * 1024; // 50 MB

// ========================================
// Allowed MIME types
// ========================================
export const ALLOWED_MIMETYPES = new Set([
  'image/jpeg',
  'image/png',
  'image/gif',
  'image/webp',
  'video/mp4',
  'video/webm',
  'audio/webm',
  'audio/ogg',
  'audio/mpeg',
  'audio/mp3',
  'audio/wav',
  'audio/x-wav',
  'audio/flac',
  'audio/aac',
  'audio/m4a',
  'audio/x-m4a',
  'application/pdf',
]);

// ========================================
// Magic bytes signatures
// ========================================
export const MAGIC_SIGNATURES: Array<{ mime: string; match: (b: Buffer) => boolean }> = [
  { mime: 'image/jpeg',       match: b => b[0] === 0xFF && b[1] === 0xD8 && b[2] === 0xFF },
  { mime: 'image/png',        match: b => b[0] === 0x89 && b[1] === 0x50 && b[2] === 0x4E && b[3] === 0x47 },
  { mime: 'image/gif',        match: b => b[0] === 0x47 && b[1] === 0x49 && b[2] === 0x46 && (b[3] === 0x37 || b[3] === 0x39) },
  { mime: 'image/webp',       match: b => b.length >= 12 && b[0] === 0x52 && b[1] === 0x49 && b[2] === 0x46 && b[3] === 0x46 && b[8] === 0x57 && b[9] === 0x45 && b[10] === 0x42 && b[11] === 0x50 },
  { mime: 'video/mp4',        match: b => b.length >= 8 && b[4] === 0x66 && b[5] === 0x74 && b[6] === 0x79 && b[7] === 0x70 },
  { mime: 'video/webm',       match: b => b[0] === 0x1A && b[1] === 0x45 && b[2] === 0xDF && b[3] === 0xA3 },
  { mime: 'audio/webm',       match: b => b[0] === 0x1A && b[1] === 0x45 && b[2] === 0xDF && b[3] === 0xA3 },
  { mime: 'audio/ogg',        match: b => b[0] === 0x4F && b[1] === 0x67 && b[2] === 0x67 && b[3] === 0x53 },
  { mime: 'audio/mpeg',       match: b => (b[0] === 0x49 && b[1] === 0x44 && b[2] === 0x33) || (b[0] === 0xFF && (b[1] & 0xE0) === 0xE0) },
  { mime: 'audio/mp3',        match: b => (b[0] === 0x49 && b[1] === 0x44 && b[2] === 0x33) || (b[0] === 0xFF && (b[1] & 0xE0) === 0xE0) },
  { mime: 'audio/wav',        match: b => b.length >= 12 && b[0] === 0x52 && b[1] === 0x49 && b[2] === 0x46 && b[3] === 0x46 && b[8] === 0x57 && b[9] === 0x41 && b[10] === 0x56 && b[11] === 0x45 },
  { mime: 'audio/x-wav',      match: b => b.length >= 12 && b[0] === 0x52 && b[1] === 0x49 && b[2] === 0x46 && b[3] === 0x46 && b[8] === 0x57 && b[9] === 0x41 && b[10] === 0x56 && b[11] === 0x45 },
  { mime: 'audio/flac',       match: b => b[0] === 0x66 && b[1] === 0x4C && b[2] === 0x61 && b[3] === 0x43 },
  { mime: 'audio/aac',        match: b => b[0] === 0xFF && (b[1] & 0xF0) === 0xF0 },
  { mime: 'audio/m4a',        match: b => b.length >= 8 && b[4] === 0x66 && b[5] === 0x74 && b[6] === 0x79 && b[7] === 0x70 },
  { mime: 'audio/x-m4a',      match: b => b.length >= 8 && b[4] === 0x66 && b[5] === 0x74 && b[6] === 0x79 && b[7] === 0x70 },
  { mime: 'application/pdf',  match: b => b[0] === 0x25 && b[1] === 0x50 && b[2] === 0x44 && b[3] === 0x46 },
];

// ========================================
// Helper functions
// ========================================
export function getMaxSizeForMime(mimeType: string): number {
  const category = mimeType.split('/')[0];
  return FILE_SIZE_LIMITS[category] || DEFAULT_MAX_SIZE;
}

export function validateMagicBytes(mimeType: string, header: Buffer): boolean {
  if (header.length < 4) return false;
  const sig = MAGIC_SIGNATURES.find(s => s.mime === mimeType);
  if (!sig) return true; // no known signature — allow
  return sig.match(header);
}