import nodemailer from 'nodemailer';
import { logger } from './logger.ts';

// SMTP транспорт — создаётся один раз
const transporter = nodemailer.createTransport({
  host: process.env.SMTP_HOST || 'smtp.gmail.com',
  port: Number(process.env.SMTP_PORT) || 587,
  secure: false, // STARTTLS на порту 587
  auth: {
    user: process.env.SMTP_USER,
    pass: process.env.SMTP_PASS,
  },
});

/**
 * Проверяет, настроен ли SMTP
 */
export function isSmtpConfigured(): boolean {
  return !!(process.env.SMTP_USER && process.env.SMTP_PASS);
}

/**
 * Отправляет OTP-код на указанную почту
 */
export async function sendOtpEmail(
  to: string,
  code: string,
  purpose: 'recovery' | 'verify' = 'recovery'
): Promise<boolean> {
  if (!isSmtpConfigured()) {
    logger.warn('[MAIL] SMTP not configured — cannot send email');
    return false;
  }

  const subject =
    purpose === 'recovery'
      ? 'QWERcrool — Код восстановления пароля'
      : 'QWERcrool — Код подтверждения';

  const html =
    purpose === 'recovery'
      ? `
        <div style="font-family:Arial,sans-serif;max-width:480px;margin:0 auto;padding:32px;">
          <h2 style="color:#6C5CE7;">QWERcrool</h2>
          <p>Вы запросили восстановление пароля.</p>
          <div style="background:#f5f5f5;border-radius:12px;padding:20px;text-align:center;margin:24px 0;">
            <p style="font-size:14px;color:#666;margin:0 0 8px;">Ваш код:</p>
            <p style="font-size:32px;font-weight:bold;letter-spacing:8px;color:#333;margin:0;">${code}</p>
          </div>
          <p style="font-size:13px;color:#999;">Код действителен в течение 10 минут.<br/>Если вы не запрашивали сброс пароля — просто проигнорируйте это письмо.</p>
        </div>
      `
      : `
        <div style="font-family:Arial,sans-serif;max-width:480px;margin:0 auto;padding:32px;">
          <h2 style="color:#6C5CE7;">QWERcrool</h2>
          <p>Код подтверждения вашей почты:</p>
          <div style="background:#f5f5f5;border-radius:12px;padding:20px;text-align:center;margin:24px 0;">
            <p style="font-size:32px;font-weight:bold;letter-spacing:8px;color:#333;margin:0;">${code}</p>
          </div>
          <p style="font-size:13px;color:#999;">Код действителен в течение 10 минут.</p>
        </div>
      `;

  try {
    const info = await transporter.sendMail({
      from: process.env.SMTP_FROM || process.env.SMTP_USER,
      to,
      subject,
      html,
    });
    logger.info({ to, messageId: info.messageId }, '[MAIL] Email sent');
    return true;
  } catch (err) {
    logger.error({ err, to }, '[MAIL] Failed to send email');
    return false;
  }
}