import { Express } from 'express';
import { JwtRequest } from '../../src/middleware/jwtAuth.ts';
import { requireAuth } from '../../src/middleware/jwtAuth.ts';
import { validate, ReportSchema, UserReportSchema, BlockSchema } from '../../src/middleware/validate.ts';
import {
  blockUser,
  unblockUser,
  getBlockedUsers,
  getBlockDirection,
  createReport,
  getReports,
  resolveReportWithNotification,
  createUserReport,
  getUserReports,
  resolveUserReportWithNotification,
  dismissUserReport,
} from '../../src/db/admin.ts';
import { notifyReportSubmitted } from '../services/admin-notify.ts';

export function setupReportRoutes(app: Express) {
  // ========================================
  // REPORTS (Жалобы)
  // ========================================
  app.post("/api/reports", requireAuth, validate(ReportSchema), async (req: JwtRequest, res) => {
    try {
      const uid = req.user!.uid;
      const { messageId, reason } = req.body;
      const { getUserByUid } = await import("../../src/db/auth.ts");
      const user = await getUserByUid(uid);
      if (!user) {
        return res.status(404).json({ error: "User not found" });
      }
      const { msgUid } = req.body;
      const report = await createReport(parseInt(messageId), user.id, reason, msgUid);
      // Отправляем уведомление админу
      notifyReportSubmitted(uid, `msg:${msgUid || messageId}`, reason, 'message');
      res.json(report);
    } catch (err: any) {
      res.status(500).json({ error: err.message });
    }
  });

  // ========================================
  // БЛОКИРОВКИ ПОЛЬЗОВАТЕЛЕЙ
  // ========================================
  app.post("/api/blocks", requireAuth, validate(BlockSchema), async (req: JwtRequest, res) => {
    try {
      const uid = req.user!.uid;
      const { blockedUid } = req.body;
      if (uid === blockedUid) return res.status(400).json({ error: "Cannot block yourself" });
      const result = await blockUser(uid, blockedUid);
      res.json({ success: true, block: result });
    } catch (err: any) {
      res.status(500).json({ error: err.message });
    }
  });

  app.delete("/api/blocks/:blockedUid", requireAuth, async (req: JwtRequest, res) => {
    try {
      const uid = req.user!.uid;
      const blockedUid = req.params.blockedUid;
      const result = await unblockUser(uid, blockedUid);
      res.json({ success: true, block: result });
    } catch (err: any) {
      res.status(500).json({ error: err.message });
    }
  });

  app.get("/api/blocks", requireAuth, async (req: JwtRequest, res) => {
    try {
      const uid = req.user!.uid;
      const blocked = await getBlockedUsers(uid);
      res.json(blocked);
    } catch (err: any) {
      res.status(500).json({ error: err.message });
    }
  });

  app.get("/api/blocks/check/:otherUid", requireAuth, async (req: JwtRequest, res) => {
    try {
      const uid = req.user!.uid;
      const otherUid = req.params.otherUid;
      const direction = await getBlockDirection(uid, otherUid);
      res.json({ direction });
    } catch (err: any) {
      res.status(500).json({ error: err.message });
    }
  });

  // ========================================
  // ЖАЛОБЫ НА ПОЛЬЗОВАТЕЛЕЙ
  // ========================================
  app.post("/api/user-reports", requireAuth, validate(UserReportSchema), async (req: JwtRequest, res) => {
    try {
      const uid = req.user!.uid;
      const { targetUid, reason, description } = req.body;
      if (uid === targetUid) return res.status(400).json({ error: "Cannot report yourself" });
      const result = await createUserReport(targetUid, uid, reason, description);
      // Отправляем уведомление админу
      notifyReportSubmitted(uid, targetUid, reason, 'user');
      res.json({ success: true, report: result });
    } catch (err: any) {
      res.status(500).json({ error: err.message });
    }
  });
}