/**
 * Middleware: генерирует уникальный requestId для каждого запроса
 * и привязывает его к AsyncLocalStorage-контексту логгера.
 */
import { Request, Response, NextFunction } from 'express';
import { randomUUID } from 'crypto';
import { asyncLocalStorage, type LogContext } from '../services/logger.ts';

export interface RequestIdRequest extends Request {
  requestId: string;
}

export function requestIdMiddleware(req: RequestIdRequest, _res: Response, next: NextFunction) {
  const requestId = (req.headers['x-request-id'] as string) || randomUUID();
  req.requestId = requestId;

  // Привязываем контекст к AsyncLocalStorage для логгера
  const ctx: LogContext = { requestId };
  asyncLocalStorage.run(ctx, () => {
    next();
  });
}