/**
 * QR login tokens store — Redis-backed с fallback на in-memory.
 *
 * Key scheme: qr:{token} → JSON(QrTokenEntry)
 * TTL: QR_TOKEN_TTL (60 секунд)
 */
import { QR_TOKEN_TTL } from '../config.ts';
import { getRedis } from './redis.ts';

export interface QrTokenEntry {
  token: string;
  created: number;
  status: 'pending' | 'scanned' | 'confirmed' | 'expired';
  scannedBy?: string;
  confirmedBy?: string;
  deviceInfo?: string;
  loginToken?: string;
  loginRefreshToken?: string;
}

const PREFIX = 'qr:';
const TTL_SECONDS = Math.ceil(QR_TOKEN_TTL / 1000) + 60; // TTL + minute buffer

export async function getQrToken(token: string): Promise<QrTokenEntry | undefined> {
  const redis = getRedis();
  const raw = await redis.get(`${PREFIX}${token}`);
  if (!raw) return undefined;
  try {
    return JSON.parse(raw);
  } catch {
    return undefined;
  }
}

export async function setQrToken(token: string, entry: QrTokenEntry): Promise<void> {
  const redis = getRedis();
  await redis.set(`${PREFIX}${token}`, JSON.stringify(entry), 'EX', TTL_SECONDS);
}

export async function updateQrToken(token: string, updates: Partial<QrTokenEntry>): Promise<void> {
  const redis = getRedis();
  const raw = await redis.get(`${PREFIX}${token}`);
  if (!raw) return;
  try {
    const entry: QrTokenEntry = JSON.parse(raw);
    Object.assign(entry, updates);
    await redis.set(`${PREFIX}${token}`, JSON.stringify(entry), 'EX', TTL_SECONDS);
  } catch {}
}

export async function deleteQrToken(token: string): Promise<void> {
  const redis = getRedis();
  await redis.del(`${PREFIX}${token}`);
}