/**
 * Admin routes — жалобы, аудит, broadcast, статистика
 */
import { Express } from 'express';
import { JwtRequest } from '../../src/middleware/jwtAuth.ts';
import { requireAdmin } from '../../src/middleware/adminAuth.ts';
import { logger } from '../services/logger.ts';

export async function setupAdminReportRoutes(app: Express) {
  const {
    getDetailedStats,
    broadcastMessage,
    getAuditLogs,
    getAuditLogsCount,
    createAuditLog,
    getReports,
    resolveReportWithNotification,
    getUserReports,
    resolveUserReportWithNotification,
    dismissUserReport,
    sendAdminMessageToUser,
  } = await import('../../src/db/admin.ts');

  // ========================================
  // STATS (расширенные)
  // ========================================
  app.get('/api/admin/stats/detailed', requireAdmin, async (req: JwtRequest, res) => {
    try {
      const stats = await getDetailedStats();
      res.json(stats);
    } catch (err: unknown) {
      res.status(500).json({ error: err.message });
    }
  });

  // ========================================
  // REPORTS
  // ========================================
  app.get('/api/admin/reports', requireAdmin, async (req, res) => {
    try {
      const reports = await getReports();
      res.json(reports);
    } catch (err: unknown) {
      res.status(500).json({ error: err.message });
    }
  });

  app.post('/api/admin/reports/:id/resolve', requireAdmin, async (req, res) => {
    try {
      const reportId = parseInt(req.params.id);
      if (isNaN(reportId)) return res.status(400).json({ error: 'Invalid report id' });
      const result = await resolveReportWithNotification(reportId);
      res.json(result);
    } catch (err: unknown) {
      res.status(500).json({ error: err.message });
    }
  });

  app.get('/api/admin/user-reports', requireAdmin, async (req, res) => {
    try {
      const reports = await getUserReports();
      res.json(reports);
    } catch (err: unknown) {
      res.status(500).json({ error: err.message });
    }
  });

  app.post('/api/admin/user-reports/:id/resolve', requireAdmin, async (req, res) => {
    try {
      const reportId = parseInt(req.params.id);
      if (isNaN(reportId)) return res.status(400).json({ error: 'Invalid report id' });
      const { adminNote } = req.body;
      const result = await resolveUserReportWithNotification(reportId, adminNote);
      res.json(result);
    } catch (err: unknown) {
      res.status(500).json({ error: err.message });
    }
  });

  app.post('/api/admin/user-reports/:id/dismiss', requireAdmin, async (req, res) => {
    try {
      const reportId = parseInt(req.params.id);
      if (isNaN(reportId)) return res.status(400).json({ error: 'Invalid report id' });
      const result = await dismissUserReport(reportId);
      res.json(result);
    } catch (err: unknown) {
      res.status(500).json({ error: err.message });
    }
  });

  // ========================================
  // BROADCAST
  // ========================================
  app.post('/api/admin/broadcast', requireAdmin, async (req: JwtRequest, res) => {
    try {
      const { text } = req.body;
      if (!text || typeof text !== 'string' || !text.trim()) {
        return res.status(400).json({ error: 'Text is required' });
      }
      const senderUid = req.user?.uid || (req as any).adminUser?.uid || 'admin';
      const result = await broadcastMessage(text, senderUid);
      res.json(result);
    } catch (err: unknown) {
      res.status(500).json({ error: err.message });
    }
  });

  // ========================================
  // SEND MESSAGE TO USER
  // ========================================
  app.post('/api/admin/send-message', requireAdmin, async (req: JwtRequest, res) => {
    try {
      const { target, text } = req.body;
      if (!target || typeof target !== 'string' || !target.trim()) {
        return res.status(400).json({ error: 'Target (uid или @username) обязателен' });
      }
      if (!text || typeof text !== 'string' || !text.trim()) {
        return res.status(400).json({ error: 'Текст сообщения обязателен' });
      }
      const senderUid = req.user?.uid || (req as any).adminUser?.uid;
      const result = await sendAdminMessageToUser(target.trim(), text.trim(), senderUid);
      res.json(result);
    } catch (err: unknown) {
      logger.error({ err }, "[Admin] Send message error");
      res.status(500).json({ error: err.message });
    }
  });

  // ========================================
  // AUDIT LOGS
  // ========================================
  app.get('/api/admin/audit-logs', requireAdmin, async (req, res) => {
    try {
      const limit = parseInt(req.query.limit as string) || 100;
      const offset = parseInt(req.query.offset as string) || 0;
      const logs = await getAuditLogs(limit, offset);
      const total = await getAuditLogsCount();
      res.json({ logs, total });
    } catch (err: unknown) {
      res.status(500).json({ error: err.message });
    }
  });

  app.post('/api/admin/audit-logs', requireAdmin, async (req: JwtRequest, res) => {
    try {
      const { action, details, targetUid } = req.body;
      if (!action) return res.status(400).json({ error: 'Action is required' });
      const adminUid = req.user?.uid || (req as any).adminUser?.uid || 'admin-secret';
      await createAuditLog(action, adminUid, details, targetUid);
      res.json({ success: true });
    } catch (err: unknown) {
      res.status(500).json({ error: err.message });
    }
  });
}