import express from 'express';
import { createServer as createViteServer } from 'vite';
import { timingSafeEqual } from 'crypto';
import fs from 'fs';
import path from 'path';
import helmet from 'helmet';
import cors from 'cors';
import cookieParser from 'cookie-parser';
import cron from 'node-cron';
import { db, ensureDbReady } from '../src/db/index.ts';
import { sql, eq, and } from 'drizzle-orm';
import { authenticateToken, requireAuth, JwtRequest } from '../src/middleware/jwtAuth.ts';
import {
  securityHeaders,
  defaultApiRateLimit,
} from '../src/middleware/security.ts';

// Config
import { PORT, ALLOWED_ORIGINS, SESSION_SECRET, UPLOADS_DIR } from './config.ts';
import { PUBLIC_API_PATHS } from './middleware/auth.ts';

// Middleware
import { doubleCsrfProtection, setCsrfCookie } from './middleware/csrf.ts';

// Routes
import { setupAuthRoutes } from './routes/auth.ts';
import { setupUserRoutes } from './routes/users.ts';
import { setupChatRoutes } from './routes/chats.ts';
import { setupMessageRoutes } from './routes/messages.ts';
import { setupUploadRoutes } from './routes/upload.ts';
import { setupAdminRoutes } from './routes/admin.ts';
import { setupPushRoutes } from './routes/push.ts';
import { setupCallRoutes } from './routes/calls.ts';
import { setupQrRoutes } from './routes/qr.ts';
import { setupSessionRoutes } from './routes/sessions.ts';
import { setupBotRoutes } from './routes/bots.ts';
import { setupReportRoutes } from './routes/reports.ts';
import { setupThemeRoutes } from './routes/themes.ts';
import { setupGifRoutes } from './routes/gifs.ts';
import { setupHealthRoutes } from './routes/health.ts';
import { setupStickerRoutes } from './routes/stickers.ts';
import { setupAccountsRoutes } from './routes/accounts.ts';
import { setupMusicRoutes } from './routes/music.ts';

// Services
import { setupWebSocket, broadcastStatusUpdate, closeAllWebSocketConnections, wsEvents } from './services/websocket.ts';
import { logger } from './services/logger.ts';
import { requestIdMiddleware } from './middleware/requestId.ts';
import { errorHandler } from './middleware/errorHandler.ts';

async function startServer() {
  const app = express();
  const scheduledTasks: cron.ScheduledTask[] = [];

  // ========================================
  // Helmet — secure HTTP headers
  // ========================================
  app.use(helmet({
    contentSecurityPolicy: false,
    crossOriginEmbedderPolicy: false,
  }));

  // ========================================
  // CORS — whitelist from ALLOWED_ORIGINS env & local LAN
  // ========================================
  const isLanOrLocalhost = (originStr: string) => {
    return /^https?:\/\/(localhost|127\.0\.0\.1|192\.168\.\d+\.\d+|10\.\d+\.\d+\.\d+|172\.(1[6-9]|2\d|3[0-1])\.\d+\.\d+)(:\d+)?$/.test(originStr);
  };

  app.use(cors({
    origin: (origin, callback) => {
      if (
        !origin || 
        ALLOWED_ORIGINS.length === 0 ||
        ALLOWED_ORIGINS.includes('*') ||
        ALLOWED_ORIGINS.includes(origin) ||
        isLanOrLocalhost(origin)
      ) {
        callback(null, true);
      } else {
        logger.warn(`[CORS] Blocked request from origin: ${origin}`);
        callback(new Error(`Origin ${origin} not allowed by CORS`));
      }
    },
    credentials: true,
  }));

  // Security Headers
  app.use(securityHeaders);
  app.use(cookieParser(SESSION_SECRET));
  app.use(requestIdMiddleware);
  app.use(express.json({ limit: "10mb" }));

  // ========================================
  // Global Error Handler (must be after all routes, but we place it before routes
  // and use next(err) pattern — or after routes. For safety, register at end.)
  // ========================================

  // ========================================
  // Rate Limiting — глобальный лимит для всех API (60 запросов в минуту)
  // ========================================
  app.use("/api", defaultApiRateLimit);

  // ========================================
  // Global JWT Authentication
  // ========================================
  app.use("/api", (req: JwtRequest, res, next) => {
    const requestPath = req.path;
    if (PUBLIC_API_PATHS.some(p => requestPath.startsWith(p))) {
      return next();
    }
    const adminSecret = req.headers['x-admin-secret'];
    const expectedSecret = process.env.ADMIN_SECRET;
    if (adminSecret && expectedSecret) {
      const a = Buffer.from(String(adminSecret));
      const b = Buffer.from(expectedSecret);
      if (a.length === b.length && timingSafeEqual(a, b)) {
        return next();
      }
    }
    authenticateToken(req, res, next);
  });

  // Ensure uploads directory exists
  if (!fs.existsSync(UPLOADS_DIR)) {
    fs.mkdirSync(UPLOADS_DIR, { recursive: true });
  }

  // Serve static files from uploads directory with Content-Disposition: attachment
  app.use("/uploads", (req, res, next) => {
    const safeFilename = path.basename(req.path);
    if (safeFilename !== req.path.slice(1)) {
      return res.status(403).json({ error: "Access denied" });
    }
    res.setHeader('Content-Disposition', `attachment; filename="${encodeURIComponent(safeFilename)}"`);
    express.static(UPLOADS_DIR)(req, res, next);
  });

  // Проверка готовности и структуры БД
  try {
    await ensureDbReady();
    logger.info('[Server] DB ready and verified');
  } catch (err) {
    logger.error({ err }, "[Server] DB initialization failed");
    logger.error('[Server] Server continuing but DB may not work properly');
  }

  // ========================================
  // CRON: Автоматическая очистка
  // ========================================

  // 1) Каждый час — удаляем сессии старше 7 дней
  scheduledTasks.push(cron.schedule('0 * * * *', async () => {
    try {
      logger.info('[Cron] Cleaning sessions older than 7 days...');
      const { sessions: sessionsTable } = await import('../src/db/schema.ts');
      const deleted = await db.delete(sessionsTable)
        .where(
          and(
            sql`${sessionsTable.lastActive} < NOW() - INTERVAL '7 days'`,
            eq(sessionsTable.revoked, false)
          )
        )
        .returning();
      if (deleted.length > 0) {
        logger.info(`[Cron] Removed ${deleted.length} expired sessions`);
      }
    } catch (err: unknown) {
      logger.error({ err }, '[Cron] Session cleanup error');
    }
  }));

  // 2) Каждый день в 3:00 — удаляем orphan-файлы в uploads/
  scheduledTasks.push(cron.schedule('0 3 * * *', async () => {
    try {
      logger.info('[Cron] Cleaning orphan files in uploads/...');
      const { messages: messagesTable } = await import('../src/db/schema.ts');

      const rows = await db.select({ fileUrl: messagesTable.fileUrl }).from(messagesTable);
      const referencedFiles = new Set<string>();
      for (const row of rows) {
        if (row.fileUrl) {
          const match = row.fileUrl.match(/\/api\/download\/(.+)$/);
          if (match) {
            referencedFiles.add(match[1]);
          }
          const basename = path.basename(row.fileUrl);
          if (basename && basename !== row.fileUrl) {
            referencedFiles.add(basename);
          }
        }
      }

      if (!fs.existsSync(UPLOADS_DIR)) {
        return logger.info('[Cron] uploads/ directory does not exist, skipping');
      }

      const files = fs.readdirSync(UPLOADS_DIR);
      let removedCount = 0;
      for (const file of files) {
        if (!referencedFiles.has(file)) {
          const filePath = path.join(UPLOADS_DIR, file);
          try {
            if (file === 'pgdata') continue;
            fs.unlinkSync(filePath);
            removedCount++;
          } catch (err: unknown) {
            logger.warn(`[Cron] Failed to remove ${file}:`, err.message);
          }
        }
      }
      logger.info(`[Cron] Removed ${removedCount} orphan files (${files.length} total, ${referencedFiles.size} referenced)`);
    } catch (err: unknown) {
      logger.error({ err }, '[Cron] Orphan files cleanup error');
    }
  }));

  // 3) Каждый день — инвалидируем refresh-токены с истёкшим expires_at
  scheduledTasks.push(cron.schedule('0 4 * * *', async () => {
    try {
      logger.info('[Cron] Invalidating expired refresh sessions (> 30 days)...');
      const { sessions: sessionsTable } = await import('../src/db/schema.ts');
      const deleted = await db.delete(sessionsTable)
        .where(
          and(
            sql`${sessionsTable.createdAt} < NOW() - INTERVAL '30 days'`,
            eq(sessionsTable.revoked, false)
          )
        )
        .returning();
      if (deleted.length > 0) {
        logger.info(`[Cron] Revoked ${deleted.length} expired refresh sessions`);
      }
    } catch (err: unknown) {
      logger.error({ err }, '[Cron] Refresh token invalidation error');
    }
  }));

  // 4) Каждую неделю (воскресенье 2:00) — очищаем audit_logs старше 30 дней
  scheduledTasks.push(cron.schedule('0 2 * * 0', async () => {
    try {
      logger.info('[Cron] Cleaning audit_logs older than 30 days...');
      await db.execute(sql`
        DELETE FROM audit_logs WHERE created_at < NOW() - INTERVAL '30 days'
      `);
      logger.info('[Cron] Audit logs cleaned');
    } catch (err: unknown) {
      logger.error({ err }, '[Cron] Audit logs cleanup error');
    }
  }));

  logger.info('[Cron] Cron jobs scheduled:');
  logger.info('  - Sessions cleanup: every hour');
  logger.info('  - Orphan files cleanup: daily at 03:00');
  logger.info('  - Expired refresh sessions: daily at 04:00');
  logger.info('  - Audit logs cleanup: weekly (Sunday at 02:00)');

  // ========================================
  // ROUTES — setup all route modules
  // ========================================
  await setupAuthRoutes(app);
  setupUserRoutes(app);
  setupChatRoutes(app);
  setupMessageRoutes(app);
  await setupUploadRoutes(app);
  await setupAdminRoutes(app);
  setupPushRoutes(app);
  setupCallRoutes(app);
  setupQrRoutes(app);
  setupSessionRoutes(app);
  setupBotRoutes(app);
  setupReportRoutes(app);
  setupThemeRoutes(app);
  setupGifRoutes(app);
  setupHealthRoutes(app);
  setupStickerRoutes(app);
  await setupAccountsRoutes(app);
  setupMusicRoutes(app);

  // ========================================
  // Global Error Handler (после всех routes)
  // ========================================
  app.use(errorHandler);

  // ========================================
  // VITE DEV MIDDLEWARE vs PRODUCTION STATIC
  // ========================================
  const isProd = process.env.NODE_ENV === 'production' || process.env.PROD === 'true';
  const distExists = fs.existsSync(path.resolve('dist', 'index.html'));

  if (isProd && distExists) {
    const distPath = path.resolve('dist');
    app.use(express.static(distPath));
    app.get('*', (req, res) => {
      if (req.path.startsWith('/api/') || req.path.startsWith('/uploads/')) {
        return res.status(404).json({ error: 'Not found' });
      }
      res.sendFile(path.join(distPath, 'index.html'));
    });
    logger.info('[Server] Serving static production build from dist/');
  } else {
    const vite = await createViteServer({
      server: { 
        middlewareMode: true,
        host: '0.0.0.0',
        allowedHosts: true,
        watch: {
          ignored: [
            '**/.tmp*/**',
            '**/uploads/**',
            '**/dist/**',
            '**/node_modules/**',
            '**/.git/**',
            '**/*.sqlite*',
            '**/pgdata/**'
          ]
        }
      },
      appType: 'spa',
    });
    app.use(vite.middlewares);

    // SPA fallback
    app.get('*', (req, res) => {
      if (req.path.startsWith('/api/') || req.path.startsWith('/uploads/')) {
        return res.status(404).json({ error: 'Not found' });
      }
      res.sendFile(path.resolve('index.html'));
    });
  }

  // ========================================
  // START SERVER (HTTP + WebSocket)
  // ========================================
  const httpServer = app.listen(PORT, '0.0.0.0', () => {
    logger.info(`[Server] Server running on port ${PORT} (0.0.0.0:${PORT})`);
  });

  // ========================================
  // WebSocket — Real-time message status updates
  // ========================================
  setupWebSocket(httpServer);

  // Broadcast через EventEmitter (вместо globalThis)
  (globalThis as any).__broadcastStatusUpdate = broadcastStatusUpdate;
  (globalThis as any).__broadcastPinnedMessagesUpdate = broadcastStatusUpdate;
  // Альтернативно — через wsEvents
  wsEvents.on('broadcast', (targetUids: string[], data: any) => {
    // Дополнительные listener'ы могут подписаться здесь
  });

  // ========================================
  // GRACEFUL SHUTDOWN
  // ========================================
  const SHUTDOWN_TIMEOUT = 10_000; // 10 секунд максимум на завершение
  let isShuttingDown = false;

  async function gracefulShutdown(signal: string) {
    if (isShuttingDown) return;
    isShuttingDown = true;

    logger.info(`[Shutdown] Received ${signal}. Starting graceful shutdown...`);

    // Таймаут — если shutdown не завершился за N секунд, принудительно выходим
    const forceExit = setTimeout(() => {
      logger.error(`[Shutdown] Forced exit after ${SHUTDOWN_TIMEOUT}ms timeout`);
      process.exit(1);
    }, SHUTDOWN_TIMEOUT);
    forceExit.unref(); // Не мешаем процессу завершиться

    try {
      // 1) Останавливаем cron задачи
      logger.info('[Shutdown] Stopping cron tasks...');
      for (const task of scheduledTasks) {
        task.stop();
      }
      logger.info(`[Shutdown] Stopped ${scheduledTasks.length} cron tasks`);

      // 2) Закрываем все WebSocket соединения
      logger.info('[Shutdown] Closing WebSocket connections...');
      await closeAllWebSocketConnections();

      // 3) Закрываем HTTP сервер (прекращаем принимать новые соединения,
      //    ждём завершения текущих запросов)
      logger.info('[Shutdown] Closing HTTP server...');
      await new Promise<void>((resolve, reject) => {
        httpServer.close((err) => {
          if (err) {
            logger.error({ err }, '[Shutdown] HTTP server close error');
            reject(err);
          } else {
            logger.info('[Shutdown] HTTP server closed');
            resolve();
          }
        });
      });

      // 4) Закрываем пул соединений PostgreSQL
      logger.info('[Shutdown] Closing database connections...');
      try {
        const pgPool = (db as any).$client?.pool || (db as any).pool;
        if (pgPool && typeof pgPool.end === 'function') {
          await pgPool.end();
          logger.info('[Shutdown] PostgreSQL pool closed');
        } else {
          logger.info('[Shutdown] No pool.end() available (PGlite embedded)');
        }
      } catch (dbErr) {
        logger.warn({ err: dbErr }, '[Shutdown] DB close warning (non-fatal)');
      }

      // Закрываем vite dev middleware
      try {
        await vite.close();
        logger.info('[Shutdown] Vite dev server closed');
      } catch {}

      clearTimeout(forceExit);
      logger.info('[Shutdown] Graceful shutdown complete');
      process.exit(0);
    } catch (err) {
      logger.error({ err }, '[Shutdown] Error during shutdown');
      clearTimeout(forceExit);
      process.exit(1);
    }
  }

  process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
  process.on('SIGINT', () => gracefulShutdown('SIGINT'));
}

startServer().catch((err) => {
  logger.error({ err }, "[Server] Failed to start server");
  process.exit(1);
});