import { db } from '../db/index.ts';
import { pushSubscriptions, chats } from '../db/schema.ts';
import { eq, and, inArray } from 'drizzle-orm';
import webpush from 'web-push';
import { getChat } from '../db/helpers.ts';

// ========================================
// VAPID Initialization
// ========================================

const VAPID_PUBLIC_KEY = process.env.VAPID_PUBLIC_KEY || '';
const VAPID_PRIVATE_KEY = process.env.VAPID_PRIVATE_KEY || '';
const VAPID_SUBJECT = process.env.VAPID_SUBJECT || 'mailto:admin@qwercrool.app';

// Only set VAPID details if keys are configured
if (VAPID_PUBLIC_KEY && VAPID_PRIVATE_KEY) {
  webpush.setVapidDetails(VAPID_SUBJECT, VAPID_PUBLIC_KEY, VAPID_PRIVATE_KEY);
} else {
  console.warn('[Push] ⚠️ VAPID keys not configured! Push notifications will not work.');
  console.warn('[Push] Run: node scripts/generate-vapid.js to generate keys');
}

export function getVapidPublicKey(): string {
  return VAPID_PUBLIC_KEY;
}

// ========================================
// Subscription Management
// ========================================

/**
 * Сохранить подписку пользователя.
 * Если уже есть подписка с таким endpoint — обновляет её.
 * Если у пользователя >5 подписок — удаляет самую старую (очистка multiple devices).
 */
export async function saveSubscription(
  userId: number,
  endpoint: string,
  subscription: object,
  userAgent?: string
) {
  try {
    // Удаляем старую подписку с таким же endpoint
    await db.delete(pushSubscriptions)
      .where(eq(pushSubscriptions.endpoint, endpoint));

    // Вставляем новую
    await db.insert(pushSubscriptions).values({
      userId,
      endpoint,
      subscription: subscription as any,
      userAgent: userAgent || null,
    });

    // Ограничиваем количество подписок пользователя (максимум 10)
    await cleanupOldSubscriptions(userId, 10);

    console.log(`[Push] Subscription saved for user ${userId}`);
  } catch (err) {
    console.error('[Push] Failed to save subscription:', err);
    throw err;
  }
}

/**
 * Удалить подписку по endpoint
 */
export async function removeSubscription(endpoint: string) {
  await db.delete(pushSubscriptions)
    .where(eq(pushSubscriptions.endpoint, endpoint));
}

/**
 * Удалить подписку по endpoint, если она принадлежит указанному пользователю
 */
export async function removeUserSubscription(userId: number, endpoint: string) {
  await db.delete(pushSubscriptions)
    .where(
      and(
        eq(pushSubscriptions.endpoint, endpoint),
        eq(pushSubscriptions.userId, userId)
      )
    );
}

/**
 * Получить все подписки пользователя
 */
export async function getUserSubscriptions(userId: number) {
  return db.select()
    .from(pushSubscriptions)
    .where(eq(pushSubscriptions.userId, userId));
}

/**
 * Проверить, существует ли подписка с указанным endpoint
 */
export async function validateSubscriptionExists(endpoint: string): Promise<boolean> {
  try {
    const result = await db.select({ id: pushSubscriptions.id })
      .from(pushSubscriptions)
      .where(eq(pushSubscriptions.endpoint, endpoint))
      .limit(1);
    return result.length > 0;
  } catch {
    return false;
  }
}

/**
 * Очистить старые подписки пользователя, оставляя только limit самых свежих
 */
async function cleanupOldSubscriptions(userId: number, limit: number) {
  try {
    const subs = await getUserSubscriptions(userId);
    if (subs.length <= limit) return;

    // Сортируем по дате создания (новые вверху), удаляем лишние
    const sorted = subs.sort((a: (typeof subs)[number], b: (typeof subs)[number]) => {
      const dateA = a.createdAt ? new Date(a.createdAt).getTime() : 0;
      const dateB = b.createdAt ? new Date(b.createdAt).getTime() : 0;
      return dateB - dateA;
    });

    const toDelete = sorted.slice(limit);
    for (const sub of toDelete) {
      await removeSubscription(sub.endpoint);
    }
    console.log(`[Push] Cleaned up ${toDelete.length} old subscriptions for user ${userId}`);
  } catch (err) {
    console.error('[Push] Cleanup failed:', err);
  }
}

// ========================================
// Push Sending — Core
// ========================================

interface PushPayload {
  title: string;
  body: string;
  tag?: string;
  url?: string;
  chatId?: number;
  icon?: string;
  badge?: string;
  requireInteraction?: boolean;
}

interface SendResult {
  endpoint: string;
  success: boolean;
  error?: string;
}

/**
 * Отправить уведомление одному пользователю.
 * Обрабатывает все подписки параллельно, удаляет невалидные (410/404).
 */
export async function sendPushToUser(
  userId: number,
  payload: PushPayload
): Promise<SendResult[]> {
  const subs = await getUserSubscriptions(userId);

  if (subs.length === 0) {
    console.log(`[Push] No subscriptions for user ${userId}`);
    return [];
  }

  // Отправляем всем подпискам параллельно
  const sendPromises = subs.map(async (sub: (typeof subs)[number]) => {
    try {
      const subscriptionObj = sub.subscription as webpush.PushSubscription;

      await webpush.sendNotification(subscriptionObj, JSON.stringify(payload), {
        TTL: 60 * 60, // 1 час — сообщение устареет если не доставлено
        urgency: 'high', // Высокий приоритет для мессенджера
      });

      console.log(`[Push] ✅ Sent to user ${userId} (endpoint: ${sub.endpoint.substring(0, 50)}...)`);
      return { endpoint: sub.endpoint, success: true };
    } catch (err: any) {
      // 410 Gone — подписка недействительна, удаляем
      // 404 Not Found — тоже удаляем
      if (err.statusCode === 410 || err.statusCode === 404) {
        console.log(`[Push] 🗑️ Removing invalid subscription (status ${err.statusCode})`);
        await removeSubscription(sub.endpoint).catch(() => {});
        return { endpoint: sub.endpoint, success: false, error: `Subscription expired (${err.statusCode})` };
      }

      // 429 Too Many Requests — временная ошибка
      if (err.statusCode === 429) {
        console.warn(`[Push] ⚠️ Rate limited for user ${userId}`);
        return { endpoint: sub.endpoint, success: false, error: 'Rate limited' };
      }

      console.error(`[Push] ❌ Send failed for user ${userId}:`, err.message);
      return { endpoint: sub.endpoint, success: false, error: err.message };
    }
  });

  return Promise.all(sendPromises);
}

// ========================================
// Chat Push — Broadcast to Members
// ========================================

/**
 * Отправить push-уведомление всем участникам чата (кроме отправителя и замьюченных).
 * Учитывает несколько подписок на пользователя (multiple devices).
 * @param chatId числовой ID или chatUid (строка UUID)
 */
export async function sendPushToChatMembers(
  chatId: number | string,
  senderId: number,
  senderUid: string,
  senderName: string,
  messageText: string,
  messageType?: string
): Promise<SendResult[]> {
  try {
    console.log(`[Push] 📤 sendPushToChatMembers called: chatId=${chatId}, senderId=${senderId}, senderUid=${senderUid}`);

    // Ищем чат по numeric ID или chatUid (UUID)
    const chatData: any = await getChat(chatId);
    if (!chatData) {
      console.warn(`[Push] ❌ Chat ${chatId} not found in database`);
      return [];
    }

    console.log(`[Push] Chat found: id=${chatData.id}, chatUid=${chatData.chatUid}, name=${chatData.name}`);

    // members хранит массив UID (строки) — так работает getChatsForUser
    const members: string[] = (chatData.members as string[]) || [];
    const mutedBy: string[] = (chatData.mutedBy as string[]) || [];

    console.log(`[Push] Members: [${members.join(', ')}], mutedBy: [${mutedBy.join(', ')}], senderUid: ${senderUid}`);

    // Цели: все участники кроме отправителя и замьюченных (сравниваем как строки/UID)
    const targets = [...new Set(
      members.filter((uid) => String(uid) !== String(senderUid) && !mutedBy.includes(String(uid)))
    )];

    console.log(`[Push] Targets after filtering: [${targets.join(', ')}] (${targets.length} users)`);

    if (targets.length === 0) {
      console.log(`[Push] ⚠️ No targets to send push in chat ${chatId}`);
      return [];
    }

    // Ищем подписки целевых пользователей
    const targetUserIds: number[] = [];
    const { getUser } = await import('../db/helpers.ts');
    for (const targetUid of targets) {
      const targetUser = await getUser(String(targetUid));
      if (targetUser) {
        targetUserIds.push(targetUser.id);
        console.log(`[Push] Target ${targetUid} → numeric ID ${targetUser.id}`);
      } else {
        console.warn(`[Push] ⚠️ User ${targetUid} not found in DB`);
      }
    }

    if (targetUserIds.length === 0) {
      console.warn(`[Push] ❌ No valid user IDs found for targets`);
      return [];
    }

    const chatName = chatData.name || 'Чат';
    const typeLabel = messageType === 'image' ? '📷 Фото' :
                      messageType === 'file' ? '📎 Файл' :
                      messageType === 'voice' ? '🎤 Голосовое' :
                      messageType === 'video' ? '📹 Видео' :
                      '';

    const body = typeLabel
      ? `${senderName}: ${typeLabel}`
      : `${senderName}: ${messageText?.slice(0, 150) || ''}`;

    const tagId = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    const payload: PushPayload = {
      title: chatName,
      body,
      tag: `chat-${chatData.id}-msg-${tagId}`,
      url: `/chat/${chatData.chatUid || chatData.id}`,
      chatId: chatData.id,
    };

    console.log(`[Push] 📨 Sending push to ${targetUserIds.length} users in chat ${chatData.id} (${chatName})`);
    console.log(`[Push] Payload:`, JSON.stringify(payload));

    // Отправляем всем целям параллельно
    const allResults = await Promise.all(
      targetUserIds.map(async (numericUserId) => {
        console.log(`[Push] → Sending to user ${numericUserId}...`);
        const memberResults = await sendPushToUser(numericUserId, payload);
        console.log(`[Push] ← User ${numericUserId} results:`, JSON.stringify(memberResults));
        return memberResults;
      })
    );

    const flatResults = allResults.flat();
    const successCount = flatResults.filter(r => r.success).length;
    const failCount = flatResults.filter(r => !r.success).length;

    console.log(`[Push] ✅ Chat ${chatId}: ${successCount} sent, ${failCount} failed`);

    return flatResults;
  } catch (err) {
    console.error('[Push] ❌ sendPushToChatMembers error:', err);
    return [];
  }
}

/**
 * Отправить push-уведомление о звонке
 */
export async function sendPushForCall(
  chatId: number,
  callerName: string,
  callerAvatar: string,
  isVideo: boolean
): Promise<SendResult[]> {
  try {
    const chat = await db.select().from(chats).where(eq(chats.id, chatId)).limit(1);
    if (!chat.length) return [];

    const chatData = chat[0];
    const members: number[] = (chatData.members as number[]) || [];
    const mutedBy: number[] = (chatData.mutedBy as number[]) || [];

    const targets = [...new Set(
      members.filter((uid) => !mutedBy.includes(uid))
    )];

    if (targets.length === 0) return [];

    const payload: PushPayload = {
      title: `📞 ${callerName}`,
      body: isVideo ? 'Видеозвонок...' : 'Голосовой звонок...',
      tag: `call-${chatId}`,
      url: `/chat/${chatId}`,
      chatId,
      icon: callerAvatar,
      requireInteraction: true, // Важно для звонков — уведомление не пропадёт
    };

    const allResults = await Promise.all(
      targets.map((memberId) => sendPushToUser(memberId, payload))
    );

    return allResults.flat();
  } catch (err) {
    console.error('[Push] sendPushForCall error:', err);
    return [];
  }
}