function getMessageCondition(msgId: string | number) {
  // Если строка состоит только из цифр — это числовой ID
  if (typeof msgId === 'number' || (typeof msgId === 'string' && /^\d+$/.test(msgId))) {
    return eq(messages.id, Number(msgId));
  }
  return eq(messages.msgUid, msgId as string);
}

export async function flagMessage(msgId: string | number, flag: string | null) {
  try {
    const condition = getMessageCondition(msgId);

    const result = await db.update(messages)
      .set({ flagged: flag as any })
      .where(condition)
      .returning();

    return result[0] || null;
  } catch (error) {
    console.error("Error in flagMessage:", error);
    throw new Error("Failed to flag message");
  }
}

export async function deleteMessageAdmin(msgId: string | number) {
  try {
    const condition = getMessageCondition(msgId);

    const result = await db.delete(messages).where(condition).returning();
    return result[0] || null;
  } catch (error) {
    console.error("Error in deleteMessageAdmin:", error);
    throw new Error("Failed to delete message");
  }
}

