export async function createReport(messageId: number, reporterId: number, reason: string, msgUid?: string) {
  try {
    // Check if message exists before creating report
    const existingMessage = await db.select().from(messages).where(eq(messages.id, messageId)).limit(1);
    // Fallback: find by msgUid if numeric ID not found
    let resolvedMessageId = messageId;
    if (!existingMessage.length && msgUid) {
      const byUid = await db.select({ id: messages.id }).from(messages).where(sql`${messages.msgUid} = ${msgUid}`).limit(1);
      if (byUid.length > 0) resolvedMessageId = byUid[0].id;
    }
    
    // Generate explicit ID because PGlite doesn't support bigserial auto-increment with default
    const reportId = Math.floor(Math.random() * 2147483647);
    
    // Используем PGlite клиент напрямую (минуя Drizzle кэш prepared statements)
    const pgliteClient = (db as any).$client;
    if (pgliteClient) {
      const result = await pgliteClient.query(
        'INSERT INTO reports (id, message_id, reporter_id, reason) VALUES ($1, $2, $3, $4) RETURNING *',
        [reportId, resolvedMessageId, reporterId, reason]
      );
      return result.rows?.[0] || result[0];
    } else {
      // fallback если $client недоступен
      const result = await db.execute(
        sql`INSERT INTO reports (id, message_id, reporter_id, reason) VALUES (${reportId}, ${messageId}, ${reporterId}, ${reason}) RETURNING *`
      );
      return (result as any).rows?.[0] || result[0];
    }
  } catch (error) {
    console.error("Error in createReport:", error);
    throw error;
    throw new Error("Failed to create report");
  }
}

export async function getReports() {
  try {
    const result = await db.select({
      id: reports.id,
      messageId: reports.messageId,
      reporterId: reports.reporterId,
      reason: reports.reason,
      createdAt: reports.createdAt,
      resolved: reports.resolved,
      messageText: messages.text,
      messageSenderId: messages.senderId,
      messageSenderName: messages.senderName,
      messageChatId: messages.chatId,
      messageCreatedAt: messages.createdAt,
      reporterName: users.displayName,
      reporterUid: users.uid,
    })
      .from(reports)
      .leftJoin(messages, eq(reports.messageId, messages.id))
      .leftJoin(users, eq(reports.reporterId, users.id))
      .orderBy(desc(reports.createdAt));

    return result;
  } catch (error) {
    console.error("Error in getReports:", error);
    throw new Error("Failed to fetch reports");
  }
}

