// ========================================

export async function blockUser(blockerUid: string, blockedUid: string) {
  const pgliteClient = (db as any).$client;
  // Check if already blocked
  const checkResult = await pgliteClient.query(
    'SELECT * FROM user_blocks WHERE blocker_uid = $1 AND blocked_uid = $2 LIMIT 1',
    [blockerUid, blockedUid]
  );
  if (checkResult.rows && checkResult.rows.length > 0) return checkResult.rows[0];

  const id = Math.floor(Math.random() * 2147483647);
  const result = await pgliteClient.query(
    'INSERT INTO user_blocks (id, blocker_uid, blocked_uid) VALUES ($1, $2, $3) RETURNING *',
    [id, blockerUid, blockedUid]
  );
  return result.rows?.[0] || result[0];
}

export async function unblockUser(blockerUid: string, blockedUid: string) {
  const pgliteClient = (db as any).$client;
  const result = await pgliteClient.query(
    'DELETE FROM user_blocks WHERE blocker_uid = $1 AND blocked_uid = $2 RETURNING *',
    [blockerUid, blockedUid]
  );
  return result.rows?.[0] || result[0];
}

export async function getBlockedUsers(uid: string): Promise<string[]> {
  const pgliteClient = (db as any).$client;
  const result = await pgliteClient.query(
    'SELECT blocked_uid FROM user_blocks WHERE blocker_uid = $1',
    [uid]
  );
  return (result.rows || []).map((r: any) => r.blocked_uid);
}

export async function isUserBlockedBy(blockerUid: string, blockedUid: string): Promise<boolean> {
  const pgliteClient = (db as any).$client;
  const result = await pgliteClient.query(
    'SELECT 1 FROM user_blocks WHERE blocker_uid = $1 AND blocked_uid = $2 LIMIT 1',
    [blockerUid, blockedUid]
  );
  return (result.rows || []).length > 0;
}

export async function getBlockDirection(uid1: string, uid2: string): Promise<'none' | 'by_me' | 'by_them' | 'both'> {
  const a = await isUserBlockedBy(uid1, uid2);
  const b = await isUserBlockedBy(uid2, uid1);
  if (a && b) return 'both';
  if (a) return 'by_me';
  if (b) return 'by_them';
  return 'none';
}

