// ========================================
// Рассылка сообщений
// ========================================

export async function broadcastMessage(text: string, senderUid: string) {
  try {
    const allUsers = await db.select({ id: users.id, uid: users.uid }).from(users);
    // Если senderUid не настоящий UID (например, 'admin' из админки), ищем первого реального admin-пользователя
    let sender = await db.select({ displayName: users.displayName, id: users.id }).from(users).where(eq(users.uid, senderUid)).limit(1);
    let senderName = sender[0]?.displayName || 'Admin';
    let senderId = sender[0]?.id;
    if (!senderId) {
      // Ищем первого пользователя с ролью admin как fallback
      const adminUser = await db.select({ id: users.id, displayName: users.displayName }).from(users).where(eq(users.role, 'admin')).limit(1);
      if (adminUser.length > 0) {
        senderId = adminUser[0].id;
        senderName = adminUser[0].displayName || 'Admin';
      } else {
        // Последний fallback — берём первого пользователя
        const anyUser = await db.select({ id: users.id, displayName: users.displayName }).from(users).limit(1);
        if (anyUser.length > 0) {
          senderId = anyUser[0].id;
          senderName = anyUser[0].displayName || 'Admin';
        } else {
          throw new Error("No users found to broadcast from");
        }
      }
    }
    
    // Используем Drizzle вместо raw SQL для совместимости с PGlite
    const allChats = await db.select({ id: chats.id, chatUid: chats.chatUid, type: chats.type, participants: chats.participants, creatorId: chats.creatorId }).from(chats).where(eq(chats.type, 'private'));
    
    let count = 0;
    for (const user of allUsers) {
      if (user.uid === senderUid) continue;
      
      // Ищем существующий личный чат между отправителем и получателем
      const existingChat = allChats.find(c => {
        const p = c.participants as any[];
        return Array.isArray(p) && p.includes(user.uid);
      });
      
      let chatId: number;
      if (existingChat) {
        chatId = existingChat.id;
      } else {
        // Создаём новый чат
        const chatUid = `broadcast_${Date.now()}_${user.uid}`;
        const result = await db.insert(chats).values({
          chatUid,
          type: 'private',
          name: 'Broadcast',
          participants: [senderUid, user.uid],
          members: [senderUid, user.uid],
          creatorId: senderId,
        }).returning();
        chatId = result[0].id;
      }
      
      const msgUid = `msg_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
      await db.insert(messages).values({
        msgUid,
        chatId,
        senderId: senderId,
        senderName: '🛡️ ' + senderName,
        text,
        type: 'admin_broadcast',
      });
      count++;
    }
    return { sent: count };
  } catch (error) {
    console.error("Error in broadcastMessage:", error);
    throw new Error("Failed to broadcast message");
  }
}

