// ========================================
// Расширенная статистика
// ========================================

export async function getDetailedStats() {
  try {
    const baseStats = await getStats();
    
    // Статистика по дням (последние 7 дней)
    const pgliteClient = (db as any).$client;
    let dailyMessages: any[] = [];
    let dailyUsers: any[] = [];
    let chatTypes: any[] = [];
    let messageTypes: any[] = [];
    let topChatters: any[] = [];
    
    try {
      const dm = await pgliteClient.query(
        `SELECT DATE(created_at) as day, COUNT(*)::int as count 
         FROM messages 
         WHERE created_at >= NOW() - INTERVAL '7 days' 
         GROUP BY DATE(created_at) ORDER BY day`
      );
      dailyMessages = dm.rows || [];
    } catch (_) {}
    
    try {
      const du = await pgliteClient.query(
        `SELECT DATE(created_at) as day, COUNT(*)::int as count 
         FROM users 
         WHERE created_at >= NOW() - INTERVAL '7 days' 
         GROUP BY DATE(created_at) ORDER BY day`
      );
      dailyUsers = du.rows || [];
    } catch (_) {}

    try {
      const ct = await pgliteClient.query(
        `SELECT type, COUNT(*)::int as count FROM chats GROUP BY type`
      );
      chatTypes = ct.rows || [];
    } catch (_) {}

    try {
      const mt = await pgliteClient.query(
        `SELECT COALESCE(type, 'text') as type, COUNT(*)::int as count FROM messages GROUP BY type`
      );
      messageTypes = mt.rows || [];
    } catch (_) {}

    try {
      const tc = await pgliteClient.query(
        `SELECT sender_name, COUNT(*)::int as count 
         FROM messages 
         WHERE sender_name IS NOT NULL 
         GROUP BY sender_name 
         ORDER BY count DESC 
         LIMIT 10`
      );
      topChatters = tc.rows || [];
    } catch (_) {}

    // Размер базы данных
    let dbSize = '0 MB';
    try {
      const sz = await pgliteClient.query(`SELECT pg_size_pretty(pg_database_size(current_database())) as size`);
      dbSize = sz.rows?.[0]?.size || '0 MB';
    } catch (_) {}

    return {
      ...baseStats,
      dailyMessages,
      dailyUsers,
      chatTypes,
      messageTypes,
      topChatters,
      dbSize,
    };
  } catch (error) {
    console.error("Error in getDetailedStats:", error);
    throw new Error("Failed to fetch detailed stats");
  }
}

