/**
 * Admin routes — CRUD пользователей, роли, сессии, проверка панели
 */
import { Express } from 'express';
import { JwtRequest } from '../../src/middleware/jwtAuth.ts';
import { requireAdmin } from '../../src/middleware/adminAuth.ts';
import { adminPanelHashRateLimit } from '../../src/middleware/security.ts';
import { deleteUserCompletely } from '../../src/db/helpers.ts';
import { validate, UserRoleSchema } from '../../src/middleware/validate.ts';
import { timingSafeEqual } from 'crypto';
import { logger } from '../services/logger.ts';
import { notifyAdminAccess, consumeAdminToken } from '../services/admin-notify.ts';

export async function setupAdminUserRoutes(app: Express) {
  const {
    getAllUsers,
    setUserRole,
    searchUsers,
    getAllSessions,
    revokeUserSession,
    revokeAllUserSessions,
    getStats,
    createAuditLog,
  } = await import('../../src/db/admin.ts');

  // ========================================
  // One-time Admin Token Verification (из email-ссылки)
  // ========================================
  app.post('/api/auth/verify-admin-token', (req, res) => {
    try {
      const { token } = req.body;
      if (!token || typeof token !== 'string') {
        return res.status(400).json({ valid: false, error: 'Token is required' });
      }
      const valid = consumeAdminToken(token);
      if (valid) {
        logger.info('[Admin] One-time token used successfully');
        notifyAdminAccess(req.ip || req.socket?.remoteAddress, undefined);
      } else {
        logger.warn('[Admin] Invalid or expired one-time token');
      }
      res.json({ valid });
    } catch (err: unknown) {
      logger.error({ err }, '[Admin] Verify token error');
      res.status(500).json({ valid: false, error: 'Internal server error' });
    }
  });

  // ========================================
  // Admin Panel Hash Verification
  // ========================================
  app.post('/api/admin/verify-panel-hash', adminPanelHashRateLimit, (req, res) => {
    try {
      const { hash } = req.body;
      if (!hash || typeof hash !== 'string') {
        return res.status(400).json({ valid: false, error: 'Hash is required' });
      }

      const expectedHash = process.env.VITE_ADMIN_PANEL_HASH;
      if (!expectedHash) {
        logger.error('[Admin Panel] VITE_ADMIN_PANEL_HASH is not set in environment');
        return res.status(500).json({ valid: false, error: 'Server configuration error' });
      }

      if (hash.length !== expectedHash.length) {
        res.json({ valid: false });
        return;
      }
      const isValid = timingSafeEqual(
        Buffer.from(hash, 'utf8'),
        Buffer.from(expectedHash, 'utf8')
      );

      if (!isValid) {
        logger.warn(`[Admin Panel] Invalid hash attempt from IP: ${req.ip || req.socket?.remoteAddress}`);
      } else {
        // Успешный вход в админку — отправляем уведомление
        notifyAdminAccess(req.ip || req.socket?.remoteAddress, undefined);
      }

      res.json({ valid: isValid });
    } catch (err: unknown) {
      logger.error({ err }, "[Admin Panel] Verify hash error");
      res.status(500).json({ valid: false, error: 'Internal server error' });
    }
  });

  app.get('/api/admin/check-auth', requireAdmin, async (req, res) => {
    res.json({ ok: true });
  });

  // ========================================
  // STATS (базовая)
  // ========================================
  app.get('/api/admin/stats', requireAdmin, async (req, res) => {
    try {
      const stats = await getStats();
      res.json(stats);
    } catch (err: unknown) {
      res.status(500).json({ error: err.message });
    }
  });

  // ========================================
  // USERS
  // ========================================
  app.get('/api/admin/users', requireAdmin, async (req, res) => {
    try {
      const usersList = await getAllUsers();
      res.json(usersList);
    } catch (err: unknown) {
      res.status(500).json({ error: err.message });
    }
  });

  app.post('/api/admin/users/:uid/role', requireAdmin, validate(UserRoleSchema), async (req, res) => {
    try {
      const { uid } = req.params;
      const { role } = req.body;
      const updated = await setUserRole(uid, role);
      res.json(updated);
    } catch (err: unknown) {
      res.status(500).json({ error: err.message });
    }
  });

  app.delete('/api/admin/users/:uid', requireAdmin, async (req, res) => {
    try {
      const { uid } = req.params;
      const result = await deleteUserCompletely(uid);
      res.json(result);
    } catch (err: unknown) {
      res.status(500).json({ error: err.message });
    }
  });

  app.get('/api/admin/users/search', requireAdmin, async (req, res) => {
    try {
      const q = (req.query.q as string) || '';
      if (!q.trim()) return res.json([]);
      const results = await searchUsers(q);
      res.json(results);
    } catch (err: unknown) {
      res.status(500).json({ error: err.message });
    }
  });

  app.post('/api/admin/users/:uid/role-audit', requireAdmin, async (req: JwtRequest, res) => {
    try {
      const targetUid = req.params.uid;
      const { role } = req.body;
      if (!role || !['user', 'admin', 'banned'].includes(role)) {
        return res.status(400).json({ error: 'Invalid role' });
      }
      const result = await setUserRole(targetUid, role);
      const adminUid = req.user?.uid || (req as any).adminUser?.uid || 'admin-secret';
      await createAuditLog('role_change', adminUid, `Changed role to ${role}`, targetUid);
      res.json(result);
    } catch (err: unknown) {
      res.status(500).json({ error: err.message });
    }
  });

  app.delete('/api/admin/users/:uid/audit', requireAdmin, async (req: JwtRequest, res) => {
    try {
      const targetUid = req.params.uid;
      await deleteUserCompletely(targetUid);
      const adminUid = req.user?.uid || (req as any).adminUser?.uid || 'admin-secret';
      await createAuditLog('user_delete', adminUid, 'Deleted user', targetUid);
      res.json({ success: true });
    } catch (err: unknown) {
      res.status(500).json({ error: err.message });
    }
  });

  // ========================================
  // SESSIONS
  // ========================================
  app.get('/api/admin/sessions', requireAdmin, async (req, res) => {
    try {
      const sessions = await getAllSessions();
      res.json(sessions);
    } catch (err: unknown) {
      res.status(500).json({ error: err.message });
    }
  });

  app.delete('/api/admin/sessions/:sessionUid', requireAdmin, async (req, res) => {
    try {
      await revokeUserSession(req.params.sessionUid);
      res.json({ success: true });
    } catch (err: unknown) {
      res.status(500).json({ error: err.message });
    }
  });

  app.delete('/api/admin/users/:uid/sessions', requireAdmin, async (req, res) => {
    try {
      const { getUserByUid: getU } = await import('../../src/db/auth.ts');
      const user = await getU(req.params.uid);
      if (!user) return res.status(404).json({ error: 'User not found' });
      await revokeAllUserSessions(user.id);
      res.json({ success: true });
    } catch (err: unknown) {
      res.status(500).json({ error: err.message });
    }
  });
}