import { Express } from 'express';
import { randomUUID } from 'crypto';
import { JwtRequest } from '../../src/middleware/jwtAuth.ts';
import { requireAuth } from '../../src/middleware/jwtAuth.ts';
import { messageRateLimit } from '../../src/middleware/security.ts';
import {
  getMessagesForChat,
  createMessage,
  deleteMessage,
  getCommentsForMessage,
  createComment,
  toggleMessageReaction,
  getChat,
} from '../../src/db/helpers.ts';
import { sendPushToChatMembers } from '../../src/lib/push.ts';
import { validate, MessageSchema, EditMessageSchema, CommentSchema, ReactionSchema } from '../../src/middleware/validate.ts';
import { logger } from '../services/logger.ts';
import { db } from '../../src/db/index.ts';
import { messages as messagesTable } from '../../src/db/schema.ts';
import { eq } from 'drizzle-orm';

export function setupMessageRoutes(app: Express) {
  app.get("/api/chats/:chatId/messages", requireAuth, async (req: JwtRequest, res) => {
    try {
      const uid = req.user!.uid;
      const chatId = req.params.chatId;

      // Access control: verify user is authorized to read messages in this chat
      if (chatId !== 'global_chat') {
        const { getChat: getChatInfo } = await import("../../src/db/helpers.ts");
        const chatInfo: any = await getChatInfo(chatId);
        if (chatInfo) {
          const isPrivate = chatInfo.type === 'private';
          const isGroup = chatInfo.type === 'group';
          const pts = (chatInfo.participants as string[]) || [];
          const mbs = (chatInfo.members as string[]) || [];
          const isMember = pts.includes(uid) || mbs.includes(uid) || chatInfo.creatorUid === uid;
          const isSuperAdmin = req.user?.role === 'admin';

          if (isPrivate && !isMember && !isSuperAdmin) {
            return res.status(403).json({ error: "Access denied: you are not a participant in this chat" });
          }
          if (isGroup && !isMember && !isSuperAdmin && !chatInfo.username) {
            return res.status(403).json({ error: "Access denied: you are not a member of this group" });
          }
        }
      }

      const limit = parseInt(req.query.limit as string) || 50;
      const offset = parseInt(req.query.offset as string) || 0;
      const msgs = await getMessagesForChat(chatId, limit, offset);
      res.json(msgs);
    } catch (err: unknown) {
      logger.error({ err }, "Get messages error");
      res.status(500).json({ error: (err as any).message });
    }
  });

  app.post("/api/chats/:chatId/messages", requireAuth, messageRateLimit, validate(MessageSchema), async (req: JwtRequest, res) => {
    try {
      const uid = req.user!.uid;
      const chatId = req.params.chatId;

      const { getUserByUid } = await import("../../src/db/auth.ts");
      const sender = await getUserByUid(uid);
      if (!sender) {
        return res.status(404).json({ error: "User not found" });
      }
      if (sender.role === 'banned') {
        return res.status(403).json({ error: "Your account has been banned. You cannot send messages." });
      }

      const { getBlockDirection } = await import("../../src/db/admin.ts");
      const { getChat: getChatInfo } = await import("../../src/db/helpers.ts");
      const chatInfo: any = await getChatInfo(chatId);

      // Access control: verify user can send messages in this chat type
      if (chatInfo) {
        if (chatInfo.type === 'channel') {
          const isCreator = chatInfo.creatorUid === uid || chatInfo.creatorId === sender.id;
          const isAdmin = (chatInfo.admins as string[])?.includes(uid);
          if (!isCreator && !isAdmin && sender.role !== 'admin') {
            return res.status(403).json({ error: "Only channel admins can post in this channel" });
          }
        } else if (chatInfo.type === 'group') {
          const pts = (chatInfo.participants as string[]) || [];
          const mbs = (chatInfo.members as string[]) || [];
          const isMember = pts.includes(uid) || mbs.includes(uid) || chatInfo.creatorUid === uid;
          if (!isMember && sender.role !== 'admin') {
            return res.status(403).json({ error: "You must join this group to send messages" });
          }
        } else if (chatInfo.type === 'private') {
          const pts = (chatInfo.participants as string[]) || [];
          if (!pts.includes(uid) && sender.role !== 'admin') {
            return res.status(403).json({ error: "You are not a participant in this private chat" });
          }
        }
      }

      if (chatInfo && chatInfo.type === 'private') {
        const participants = chatInfo.participants || [];
        const otherUid = participants.find((p: string) => p !== uid);
        if (otherUid) {
          const blockDir = await getBlockDirection(uid, otherUid);
          if (blockDir === 'by_me' || blockDir === 'both') {
            return res.status(403).json({ error: "You have blocked this user" });
          }
          if (blockDir === 'by_them') {
            return res.status(403).json({ error: "This user has blocked you" });
          }

          // Check privacy settings: "messages" = 'nobody' or 'contacts'
          const { users } = await import("../../src/db/schema.ts");
          const { eq: eqOp } = await import("drizzle-orm");
          const targetUserResult = await db.select({ privacySettings: users.privacySettings }).from(users).where(eqOp(users.uid, otherUid)).limit(1);
          const targetPrivacy = targetUserResult[0]?.privacySettings as any;
          if (targetPrivacy?.messages) {
            const msgPrivacy = targetPrivacy.messages;
            if (msgPrivacy === 'nobody') {
              return res.status(403).json({ error: "This user does not accept messages" });
            }
            if (msgPrivacy === 'contacts') {
              // Check if sender is in target's contacts
              const { userContacts } = await import("../../src/db/schema.ts");
              const { and } = await import("drizzle-orm");
              const contactCheck = await db.select().from(userContacts)
                .where(and(eqOp(userContacts.ownerUid, otherUid), eqOp(userContacts.contactUid, uid)))
                .limit(1);
              if (contactCheck.length === 0) {
                return res.status(403).json({ error: "This user only accepts messages from contacts" });
              }
            }
          }
        }
      }

      const isChannel = chatInfo && ((chatInfo as any).type === 'channel' || chatInfo.type === 'channel');
      const messageId = randomUUID();
      const messageData = {
        msgUid: messageId,
        chatId,
        senderId: sender.id,
        senderName: isChannel ? String((chatInfo as any).name || 'Канал') : (sender.displayName || 'Anonymous'),
        senderAvatar: isChannel ? String((chatInfo as any).avatar || '') : (sender.photoURL || ''),
        text: req.body.text || null,
        fileUrl: req.body.fileUrl || null,
        fileName: req.body.fileName || null,
        fileType: req.body.fileType || null,
        type: isChannel ? 'channel_post' : (req.body.type || 'text'),
        duration: req.body.duration || null,
        replyTo: req.body.replyTo || null,
      };

      const msg = await createMessage(messageData);
      const outgoingMsg = {
        ...msg,
        senderId: isChannel ? `channel_${chatId}` : sender.uid,
        isChannelPost: isChannel,
      };

      // Auto-mirror post into linked discussion group chat if current chat is a channel
      if (isChannel && (chatInfo as any).linkedChatId) {
        try {
          const linkedIdNum = Number((chatInfo as any).linkedChatId);
          const mirrorUid = randomUUID();
          const mirrorMsg = await createMessage({
            msgUid: mirrorUid,
            chatId: linkedIdNum,
            senderId: sender.id,
            senderName: String((chatInfo as any).name || 'Канал'),
            senderAvatar: String((chatInfo as any).avatar || ''),
            text: req.body.text || null,
            fileUrl: req.body.fileUrl || null,
            fileName: req.body.fileName || null,
            fileType: req.body.fileType || null,
            type: 'channel_post',
            duration: req.body.duration || null,
            replyTo: null,
          });

          // Broadcast mirror message to discussion group
          const { getChat: getLinkedChat } = await import("../../src/db/helpers.ts");
          const linkedChatInfo = await getLinkedChat(linkedIdNum);
          if (linkedChatInfo) {
            const discRecipients = Array.from(new Set([
              ...((linkedChatInfo as any).participants || []),
              ...((linkedChatInfo as any).members || [])
            ]));
            const broadcastFn = (globalThis as any).__broadcastStatusUpdate;
            if (broadcastFn) {
              broadcastFn(discRecipients, {
                type: 'new_message',
                chatId: String((linkedChatInfo as any).chatUid || (linkedChatInfo as any).id),
                message: {
                  ...mirrorMsg,
                  senderId: `channel_${chatId}`,
                  isChannelPost: true,
                  channelId: chatId,
                },
              });
            }
          }
        } catch (mirrorErr) {
          logger.error({ err: mirrorErr }, "[Message] Failed to mirror post to linked discussion group");
        }
      }

      // WS broadcast: new_message
      setImmediate(() => {
        try {
          const broadcastFn = (globalThis as any).__broadcastStatusUpdate;
          if (broadcastFn && chatInfo) {
            const participants: string[] = chatInfo.participants || [];
            broadcastFn(participants, {
              type: 'new_message',
              chatId,
              message: outgoingMsg,
            });
          }
        } catch (e) {
          logger.error({ err: e }, '[Message] new_message broadcast error');
        }
      });
      // If replying to a channel post (or message in discussion group linked to a channel), register as comment
      if (req.body.replyTo) {
        try {
          let replyTargetMsgId: string | null = null;
          let replyParsed: any = null;
          try {
            replyParsed = typeof req.body.replyTo === 'string' ? JSON.parse(req.body.replyTo) : req.body.replyTo;
            replyTargetMsgId = replyParsed?.msgId;
          } catch {
            replyTargetMsgId = req.body.replyTo;
          }

          if (replyTargetMsgId) {
            const { messages: msgsTable, chats: chsTable } = await import("../../src/db/schema.ts");
            const { eq: eqOp } = await import("drizzle-orm");
            let repMsgRows = await db.select().from(msgsTable).where(eqOp(msgsTable.msgUid, replyTargetMsgId)).limit(1);
            if (!repMsgRows.length) {
              const parsedNum = parseInt(replyTargetMsgId);
              if (!isNaN(parsedNum)) {
                repMsgRows = await db.select().from(msgsTable).where(eqOp(msgsTable.id, parsedNum)).limit(1);
              }
            }

            if (repMsgRows.length > 0) {
              const repMsg = repMsgRows[0];
              const repChatRows = await db.select().from(chsTable).where(eqOp(chsTable.id, repMsg.chatId)).limit(1);
              const repChat = repChatRows[0];

              let channelMsgToComment: any = null;
              let channelChat: any = null;

              if (repChat?.type === 'channel') {
                channelMsgToComment = repMsg;
                channelChat = repChat;
              } else if (replyParsed?.isChannelPost && replyParsed?.msgId) {
                let rootRows = await db.select().from(msgsTable).where(eqOp(msgsTable.msgUid, replyParsed.msgId)).limit(1);
                if (rootRows.length) {
                  channelMsgToComment = rootRows[0];
                  const cRows = await db.select().from(chsTable).where(eqOp(chsTable.id, channelMsgToComment.chatId)).limit(1);
                  channelChat = cRows[0];
                }
              }

              if (channelMsgToComment && channelChat) {
                const commentId = randomUUID();
                const newCommentObj = await createComment({
                  commentUid: commentId,
                  messageId: channelMsgToComment.id,
                  chatId: channelMsgToComment.chatId,
                  userId: sender.id,
                  userName: sender.displayName || sender.username || 'Anonymous',
                  userAvatar: sender.photoURL || '',
                  text: req.body.text || '💬',
                });

                const broadcastFn = (globalThis as any).__broadcastStatusUpdate;
                if (broadcastFn && channelChat) {
                  const chanRecipients = Array.from(new Set([
                    ...(channelChat.participants || []),
                    ...(channelChat.members || []),
                  ]));
                  broadcastFn(chanRecipients, {
                    type: 'new_comment',
                    chatId: String(channelChat.chatUid || channelChat.id),
                    messageUid: channelMsgToComment.msgUid || String(channelMsgToComment.id),
                    comment: newCommentObj,
                  });
                }
              }
            }
          }
        } catch (replySyncErr) {
          logger.error({ err: replySyncErr }, "[Message] Failed to sync reply as channel comment");
        }
      }

      // WS broadcast: new_message
      setImmediate(() => {
        try {
          const broadcastFn = (globalThis as any).__broadcastStatusUpdate;
          if (broadcastFn && chatInfo) {
            const participants: string[] = chatInfo.participants || [];
            broadcastFn(participants, {
              type: 'new_message',
              chatId,
              message: msg,
            });
          }
        } catch (e) {
          logger.error({ err: e }, '[Message] new_message broadcast error');
        }
      });

      setImmediate(() => {
        logger.info(`[Message] 📤 Calling sendPushToChatMembers: chatId=${chatId}, senderId=${sender.id}, senderUid=${sender.uid}`);
        sendPushToChatMembers(
          chatId,
          sender.id,
          sender.uid,
          sender.displayName || 'Anonymous',
          req.body.text || '',
          req.body.type || 'text'
        ).catch(err => logger.error({ err }, "[Message] ❌ Push error"));
      });

      res.json(msg);
    } catch (err: unknown) {
      logger.error({ err }, "Create message error");
      res.status(500).json({ error: err.message });
    }
  });

  app.post("/api/messages/:messageId/comments", requireAuth, messageRateLimit, validate(CommentSchema), async (req: JwtRequest, res) => {
    try {
      const uid = req.user!.uid;
      const commentId = randomUUID();
      const msgParam = req.params.messageId;

      const { getUserByUid } = await import("../../src/db/auth.ts");
      const user = await getUserByUid(uid);
      if (!user) {
        return res.status(404).json({ error: "User not found" });
      }

      // Find the message by msgUid or numeric id
      const { messages: messagesTable, chats: chatsTable } = await import("../../src/db/schema.ts");
      const { eq: eqOp } = await import("drizzle-orm");

      let msgRows = await db.select().from(messagesTable).where(eqOp(messagesTable.msgUid, msgParam)).limit(1);
      if (!msgRows.length) {
        const numId = parseInt(msgParam);
        if (!isNaN(numId)) {
          msgRows = await db.select().from(messagesTable).where(eqOp(messagesTable.id, numId)).limit(1);
        }
      }

      if (!msgRows.length) {
        return res.status(404).json({ error: "Message not found" });
      }

      const targetMsg = msgRows[0];
      const chatRows = await db.select().from(chatsTable).where(eqOp(chatsTable.id, targetMsg.chatId)).limit(1);
      const parentChat = chatRows[0];

      // If chat is a channel, comments are STRICTLY allowed ONLY IF linkedChatId is set!
      if (parentChat && parentChat.type === 'channel' && !parentChat.linkedChatId) {
        return res.status(403).json({ error: "Комментарии к этому каналу отключены, так как не привязан чат обсуждений." });
      }

      const commentData = {
        commentUid: commentId,
        messageId: targetMsg.id,
        chatId: targetMsg.chatId,
        userId: user.id,
        userName: user.displayName || user.username || 'Anonymous',
        userAvatar: user.photoURL || '',
        text: req.body.text,
      };

      const comment = await createComment(commentData);

      // If channel has a linked discussion group, post comment into the discussion group (Telegram style)
      if (parentChat && parentChat.type === 'channel' && parentChat.linkedChatId) {
        try {
          const linkedChatIdNum = Number(parentChat.linkedChatId);
          const discMsgUid = randomUUID();
          const discMsg = await createMessage({
            msgUid: discMsgUid,
            chatId: linkedChatIdNum,
            senderId: user.id,
            senderName: user.displayName || user.username || 'Anonymous',
            senderAvatar: user.photoURL || '',
            text: req.body.text,
            type: 'text',
            replyTo: JSON.stringify({
              msgId: targetMsg.msgUid || String(targetMsg.id),
              isChannelPost: true,
              text: targetMsg.text || parentChat.name || 'Пост канала',
              senderName: parentChat.name || 'Канал'
            }),
          });

          // Broadcast discussion message to linked group members
          const { getChat: getLinkedChat } = await import("../../src/db/helpers.ts");
          const linkedChatInfo = await getLinkedChat(linkedChatIdNum);
          if (linkedChatInfo) {
            const discRecipients = Array.from(new Set([
              ...((linkedChatInfo as any).participants || []),
              ...((linkedChatInfo as any).members || [])
            ]));
            const broadcastFn = (globalThis as any).__broadcastStatusUpdate;
            if (broadcastFn) {
              broadcastFn(discRecipients, {
                type: 'new_message',
                chatId: String((linkedChatInfo as any).chatUid || (linkedChatInfo as any).id),
                message: discMsg,
              });
            }
          }
        } catch (discErr) {
          logger.error({ err: discErr }, "[Comment] Failed to mirror comment to linked discussion group");
        }
      }

      // WS broadcast: new_comment
      setImmediate(() => {
        try {
          const broadcastFn = (globalThis as any).__broadcastStatusUpdate;
          if (broadcastFn && parentChat) {
            const recipients = Array.from(new Set([
              ...(parentChat.participants || []),
              ...(parentChat.members || []),
            ]));
            broadcastFn(recipients, {
              type: 'new_comment',
              chatId: String(parentChat.chatUid || parentChat.id),
              messageUid: targetMsg.msgUid || String(targetMsg.id),
              comment,
            });
          }
        } catch (e) {
          logger.error({ err: e }, '[Comment] new_comment broadcast error');
        }
      });

      res.json(comment);
    } catch (err: unknown) {
      logger.error({ err }, "Create comment error");
      res.status(500).json({ error: err.message });
    }
  });

  app.post("/api/messages/:messageId/delete", requireAuth, messageRateLimit, async (req: JwtRequest, res) => {
    try {
      const uid = req.user!.uid;
      const msgId = req.params.messageId;

      const { db: dbConn } = await import("../../src/db/index.ts");
      const { messages: messagesTable } = await import("../../src/db/schema.ts");
      const { eq } = await import("drizzle-orm");

      const msgRows = await dbConn.select({ senderId: messagesTable.senderId, chatId: messagesTable.chatId })
        .from(messagesTable)
        .where(eq(messagesTable.msgUid, msgId))
        .limit(1);

      if (!msgRows.length) {
        return res.status(404).json({ error: "Message not found" });
      }

      const msgSenderId = msgRows[0].senderId;
      const msgChatId = msgRows[0].chatId;

      const { getUserByUid } = await import("../../src/db/auth.ts");
      const user = await getUserByUid(uid);
      if (!user) {
        return res.status(404).json({ error: "User not found" });
      }

      const isOwner = msgSenderId === user.id;
      if (!isOwner) {
        const { getChat } = await import("../../src/db/helpers.ts");
        const chat: Record<string, unknown> & { id?: number; type?: string; participants?: string[]; members?: string[]; admins?: string[]; creatorId?: number; creatorUid?: string } = await getChat(msgChatId);
        const isChatAdmin = chat?.admins?.includes(uid) || false;
        const isCreator = chat?.creatorId === user.id;
        const isSuperAdmin = user.role === 'admin';
        if (!isChatAdmin && !isCreator && !isSuperAdmin) {
          return res.status(403).json({ error: "You can only delete your own messages" });
        }
      }

      const result = await deleteMessage(msgId);

      // WS broadcast: message_deleted
      setImmediate(() => {
        try {
          const broadcastFn = (globalThis as any).__broadcastStatusUpdate;
          if (broadcastFn) {
            getChat(String(msgChatId)).then((chat: any) => {
              if (chat) {
                broadcastFn(chat.participants || [], {
                  type: 'message_deleted',
                  chatId: String(msgChatId),
                  messageUid: msgId,
                });
              }
            });
          }
        } catch (e) {
          logger.error({ err: e }, '[Message] message_deleted broadcast error');
        }
      });

      res.json({ success: true, deleted: result });
    } catch (err: unknown) {
      logger.error({ err }, "Delete message error");
      res.status(500).json({ error: err.message });
    }
  });

  // Редактирование сообщения
  app.patch("/api/messages/:messageId/edit", requireAuth, messageRateLimit, validate(EditMessageSchema), async (req: JwtRequest, res) => {
    try {
      const uid = req.user!.uid;
      const { text } = req.body;
      const { editMessage: editMessageFn } = await import("../../src/db/helpers.ts");
      const edited = await editMessageFn(req.params.messageId, uid, text.trim());

      // Рассылка WebSocket обновления
      try {
        const chatNumericId = (edited as any).chatId;
        const { getChat: getChatFn } = await import("../../src/db/helpers.ts");
        const chatInfo: Record<string, unknown> | null = await getChatFn(chatNumericId);
        if (chatInfo) {
          const participants: string[] = chatInfo.participants || [];
          const broadcastFn = (globalThis as any).__broadcastStatusUpdate;
          if (broadcastFn) {
            broadcastFn(participants, {
              type: 'message_edited',
              message: {
                msgUid: (edited as any).msgUid,
                text: (edited as any).text,
                editedAt: (edited as any).editedAt,
                chatId: chatInfo.chatUid || String(chatNumericId),
              },
            });
          }
        }
      } catch (broadcastErr) {
        logger.error({ err: broadcastErr }, "[Edit Message] Broadcast error");
      }

      res.json({ success: true, message: edited });
    } catch (err: unknown) {
      logger.error({ err }, "Edit message error");
      res.status(500).json({ error: err.message });
    }
  });

      app.post("/api/messages/:messageId/react", requireAuth, messageRateLimit, validate(ReactionSchema), async (req: JwtRequest, res) => {
    try {
      const { emoji } = req.body;
      const uid = req.user!.uid;
      const messageId = req.params.messageId;
      const reactions = await toggleMessageReaction(messageId, uid, emoji);

      // WS broadcast: message_reaction
      setImmediate(() => {
        try {
            const broadcastFn = (globalThis as any).__broadcastStatusUpdate;
            if (broadcastFn) {
              db.select({ chatId: messagesTable.chatId }).from(messagesTable)
                .where(eq(messagesTable.msgUid, messageId)).limit(1)
                .then((rows: any[]) => {
                  if (rows.length) {
                    getChat(String(rows[0].chatId)).then((chat: any) => {
                      if (chat) {
                        broadcastFn(chat.participants || [], {
                          type: 'message_reaction',
                          chatId: String(rows[0].chatId),
                          messageUid: messageId,
                          reactions,
                        });
                      }
                    });
                  }
                });
            }
        } catch (e) {
          logger.error({ err: e }, '[Message] message_reaction broadcast error');
        }
      });

      res.json({ success: true, reactions });
    } catch (err: unknown) {
      logger.error({ err }, "Toggle message reaction error");
      res.status(500).json({ error: err.message });
    }
  });

  app.get("/api/messages/:messageId/comments", requireAuth, async (req: JwtRequest, res) => {
    try {
      const cmts = await getCommentsForMessage(req.params.messageId);
      res.json(cmts);
    } catch (err: unknown) {
      logger.error({ err }, "Get comments error");
      res.status(500).json({ error: err.message });
    }
  });

  // ========================================
  // СТАТУСЫ СООБЩЕНИЙ
  // ========================================
  app.post("/api/messages/:messageId/status/delivered", requireAuth, async (req: JwtRequest, res) => {
    try {
      const { getUserByUid } = await import("../../src/db/auth.ts");
      const user = await getUserByUid(req.user!.uid);
      if (!user) return res.status(404).json({ error: "User not found" });

      const { db: dbConn } = await import("../../src/db/index.ts");
      const { sql } = await import("drizzle-orm");

      const messageResult = await dbConn.execute(sql`SELECT id FROM messages WHERE msg_uid = ${req.params.messageId}`);
      const messageRows = messageResult?.rows || [];
      if (!messageRows.length) return res.status(404).json({ error: "Message not found" });
      const messageId = messageRows[0].id;

      await dbConn.execute(sql`
        INSERT INTO message_statuses (message_id, user_id, status, push_delivered_at, updated_at)
        VALUES (${messageId}, ${user.id}, 'delivered', NOW(), NOW())
        ON CONFLICT (message_id, user_id)
        DO UPDATE SET status = 'delivered', push_delivered_at = NOW(), updated_at = NOW()
        WHERE message_statuses.status NOT IN ('opened', 'read')
      `);
      res.json({ success: true });
    } catch (err: unknown) {
      logger.error({ err }, "Delivered status error");
      res.status(500).json({ error: err.message });
    }
  });

  // Отметить сообщение как "открытое"
  app.post("/api/messages/:messageId/status/opened", requireAuth, async (req: JwtRequest, res) => {
    try {
      const { getUserByUid } = await import("../../src/db/auth.ts");
      const user = await getUserByUid(req.user!.uid);
      if (!user) return res.status(404).json({ error: "User not found" });

      const { db: dbConn } = await import("../../src/db/index.ts");
      const { sql } = await import("drizzle-orm");

      const messageResult = await dbConn.execute(sql`SELECT id FROM messages WHERE msg_uid = ${req.params.messageId}`);
      const messageRows = messageResult?.rows || [];
      if (!messageRows.length) return res.status(404).json({ error: "Message not found" });
      const messageId = messageRows[0].id;

      await dbConn.execute(sql`
        INSERT INTO message_statuses (message_id, user_id, status, opened_at, updated_at)
        VALUES (${messageId}, ${user.id}, 'opened', NOW(), NOW())
        ON CONFLICT (message_id, user_id)
        DO UPDATE SET status = 'opened', opened_at = NOW(), updated_at = NOW()
        WHERE message_statuses.status NOT IN ('read')
      `);
      res.json({ success: true });
    } catch (err: unknown) {
      logger.error({ err }, "Opened status error");
      res.status(500).json({ error: err.message });
    }
  });

  app.post('/api/messages/:messageId/view', requireAuth, async (req: JwtRequest, res) => {
    try {
      const uid = req.user.uid;
      const param = req.params.messageId;
      const numId = parseInt(param);
      const isNum = !isNaN(numId) && String(numId) === param;
      
      const msg = isNum
        ? await db.select().from(messagesTable).where(eq(messagesTable.id, numId)).limit(1)
        : await db.select().from(messagesTable).where(eq(messagesTable.msgUid, param)).limit(1);

      if (!msg[0]) return res.status(404).json({ error: 'Not found' });
      const viewedBy = (msg[0].viewedBy as string[]) || [];
      if (!viewedBy.includes(uid)) {
        viewedBy.push(uid);
        await db.update(messagesTable).set({ viewedBy }).where(eq(messagesTable.id, msg[0].id));
      }
      res.json({ success: true, viewedBy });
    } catch (err) {
      logger.error({ err }, 'View error');
      res.status(500).json({ error: 'Server error' });
    }
  });
  app.post("/api/chats/:chatId/status/read", requireAuth, async (req: JwtRequest, res) => {
    try {
      const chatIdParam = req.params.chatId;
      const uid = req.user!.uid;
      const { getUserByUid } = await import("../../src/db/auth.ts");
      const user = await getUserByUid(uid);
      if (!user) return res.status(404).json({ error: "User not found" });

      const { db: dbConn } = await import("../../src/db/index.ts");
      const { sql } = await import("drizzle-orm");

      let chatNumericId = parseInt(chatIdParam);
      if (isNaN(chatNumericId)) {
        const chatResult = await dbConn.execute(sql`SELECT id FROM chats WHERE chat_uid = ${chatIdParam}`);
        const chatRows = chatResult?.rows || [];
        if (!chatRows.length) {
          logger.info(`[StatusRead] ⚠️ Chat ${chatIdParam} not found`);
          return res.json({ success: true, updated: 0 });
        }
        chatNumericId = chatRows[0].id;
      }

      logger.info(`[StatusRead] 📖 Marking read: chatIdParam=${chatIdParam}, chatNumericId=${chatNumericId}, userId=${user.id}, uid=${uid}`);

      await dbConn.execute(sql`
        INSERT INTO message_statuses (message_id, user_id, status, read_at, updated_at)
        SELECT m.id, ${user.id}, 'read', NOW(), NOW()
        FROM messages m
        WHERE m.chat_id = ${chatNumericId}
        AND m.sender_id != ${user.id}
        ON CONFLICT (message_id, user_id)
        DO UPDATE SET status = 'read', read_at = NOW(), updated_at = NOW()
        WHERE message_statuses.status != 'read'
      `);

      await dbConn.execute(sql`
        UPDATE messages SET read_by =
          CASE
            WHEN read_by IS NULL THEN ${JSON.stringify([uid])}::jsonb
            WHEN read_by @> ${JSON.stringify([uid])}::jsonb THEN read_by
            ELSE read_by || ${JSON.stringify([uid])}::jsonb
          END
        WHERE chat_id = ${chatNumericId}
        AND sender_id != ${user.id}
      `);

      logger.info(`[StatusRead] ✅ Read status updated for chat ${chatNumericId}`);

        // Рассылаем обновление статуса отправителям чата через WebSocket
        // Batch-запрос: все sender_uids за один SELECT (N+1 fix)
        try {
          const chatResult = await dbConn.execute(sql`
            SELECT DISTINCT u.uid
            FROM messages m
            JOIN users u ON u.id = m.sender_id
            WHERE m.chat_id = ${chatNumericId} AND m.sender_id != ${user.id}
          `);
          const senderUids = (chatResult?.rows || []).map((r: any) => r.uid).filter(Boolean);

          if (senderUids.length > 0) {
            const broadcastFn = (globalThis as any).__broadcastStatusUpdate;
            if (broadcastFn) {
              broadcastFn(senderUids, {
                type: 'message_status_update',
                chatId: chatNumericId,
                chatUid: chatIdParam,
                readerUid: uid,
                status: 'read',
              });
              logger.info(`[StatusRead] Broadcast read to ${senderUids.length} senders`);
            }
          }
        } catch (broadcastErr) {
        logger.warn({ err: broadcastErr }, '[StatusRead] ⚠️ Broadcast failed');
      }

      res.json({ success: true });
    } catch (err: unknown) {
      logger.error({ err }, "Read status error");
      res.status(500).json({ error: err.message });
    }
  });
}