/**
 * Chat routes — фасад, подключающий подмодули:
 *   - chats-crud.ts     (list, create, update, delete, invite, join)
 *   - chats-pins.ts     (pin, unpin, reorder, get pins)
 *   - chats-statuses.ts (media, statuses, my-statuses)
 *   - chats-members.ts  (add member, remove member, leave)
 */
import { Express } from 'express';
import { setupChatCrudRoutes } from './chats-crud.ts';
import { setupChatPinRoutes } from './chats-pins.ts';
import { setupChatStatusRoutes } from './chats-statuses.ts';
import { setupChatMemberRoutes } from './chats-members.ts';
import { setupChatAdvancedRoutes } from './chats-advanced.ts';

export function setupChatRoutes(app: Express) {
  setupChatCrudRoutes(app);
  setupChatPinRoutes(app);
  setupChatStatusRoutes(app);
  setupChatMemberRoutes(app);
  setupChatAdvancedRoutes(app);
}
