import { Express } from 'express';
import { createHash, createHmac, randomBytes, timingSafeEqual } from 'crypto';
import { pgTable, text, timestamp, integer, boolean, jsonb, index } from 'drizzle-orm/pg-core';
import { eq, sql } from 'drizzle-orm';
import { JwtRequest } from '../../src/middleware/jwtAuth.ts';
import { requireAuth } from '../../src/middleware/jwtAuth.ts';
import { logger } from '../services/logger.ts';
import { db } from '../../src/db/index.ts';
import { SESSION_SECRET } from '../config.ts';

// ========================================
// Bot Types & Interfaces
// ========================================
export interface SafeBot {
  id: number;
  ownerUid: string;
  username: string;
  displayName: string;
  description: string | null;
  avatar: string | null;
  tokenPrefix: string;
  webhookUrl: string | null;
  privacyMode: boolean | null;
  isActive: boolean | null;
  botPermissions: unknown;
  createdAt: Date | string | null;
  updatedAt: Date | string | null;
}

export interface BotRecord extends SafeBot {
  tokenHash: string;
}

// ========================================
// Database Schema for Bots
// ========================================
export const botsTable = pgTable(
  'bots',
  {
    id: integer('id').primaryKey().generatedAlwaysAsIdentity(),
    ownerUid: text('owner_uid').notNull(),
    username: text('username').unique().notNull(),
    displayName: text('display_name').notNull(),
    description: text('description').default(''),
    avatar: text('avatar').default(''),
    tokenHash: text('token_hash').notNull(),
    tokenPrefix: text('token_prefix').notNull(),
    webhookUrl: text('webhook_url').default(''),
    privacyMode: boolean('privacy_mode').default(true),
    isActive: boolean('is_active').default(true),
    botPermissions: jsonb('bot_permissions').default(['send_messages', 'read_messages']),
    createdAt: timestamp('created_at').defaultNow(),
    updatedAt: timestamp('updated_at').defaultNow(),
  },
  (table) => [
    index('idx_bots_owner_uid_drizzle').on(table.ownerUid),
    index('idx_bots_token_hash_drizzle').on(table.tokenHash),
  ]
);

export const bots = botsTable;

export const safeBotFields = {
  id: botsTable.id,
  ownerUid: botsTable.ownerUid,
  username: botsTable.username,
  displayName: botsTable.displayName,
  description: botsTable.description,
  avatar: botsTable.avatar,
  tokenPrefix: botsTable.tokenPrefix,
  webhookUrl: botsTable.webhookUrl,
  privacyMode: botsTable.privacyMode,
  isActive: botsTable.isActive,
  botPermissions: botsTable.botPermissions,
  createdAt: botsTable.createdAt,
  updatedAt: botsTable.updatedAt,
};

let tableInitialized = false;

export async function ensureBotsTable(): Promise<void> {
  if (tableInitialized) return;
  try {
    await db.execute(sql`
      CREATE TABLE IF NOT EXISTS bots (
        id SERIAL PRIMARY KEY,
        owner_uid TEXT NOT NULL,
        username TEXT UNIQUE NOT NULL,
        display_name TEXT NOT NULL,
        description TEXT DEFAULT '',
        avatar TEXT DEFAULT '',
        token_hash TEXT NOT NULL,
        token_prefix TEXT NOT NULL,
        webhook_url TEXT DEFAULT '',
        privacy_mode BOOLEAN DEFAULT true,
        is_active BOOLEAN DEFAULT true,
        bot_permissions JSONB DEFAULT '["send_messages", "read_messages"]'::jsonb,
        created_at TIMESTAMP DEFAULT NOW(),
        updated_at TIMESTAMP DEFAULT NOW()
      )
    `);
    try {
      await db.execute(sql`CREATE INDEX IF NOT EXISTS idx_bots_owner_uid_drizzle ON bots(owner_uid)`);
      await db.execute(sql`CREATE INDEX IF NOT EXISTS idx_bots_token_hash_drizzle ON bots(token_hash)`);
    } catch {
      // Index may already exist
    }
    tableInitialized = true;
  } catch (err: unknown) {
    logger.warn({ err }, "[Bots] Notice: Auto-ensure bots table encountered an error");
  }
}

// ========================================
// Token Generation & Security Helpers
// ========================================

/**
 * Generates a cryptographically secure bot token.
 * Format: 64-char hex or `${botId}:${secret}` if botId is provided.
 */
export function generateBotToken(botId?: number): string {
  const secret = randomBytes(32).toString('hex');
  return botId !== undefined ? `${botId}:${secret}` : secret;
}

/**
 * Extracts prefix from bot token for safe identification.
 */
export function extractTokenPrefix(token: string): string {
  if (!token) return '';
  if (token.includes(':')) {
    return token.split(':')[0];
  }
  return token.substring(0, 10);
}

/**
 * Computes SHA-256 hash of a bot token. Tokens are never stored in plaintext.
 */
export function hashBotToken(token: string): string {
  return createHash('sha256').update(token.trim()).digest('hex');
}

/**
 * Signs a bot token with HMAC-SHA256 for integrity checks.
 */
export function signBotToken(token: string, secret: string = SESSION_SECRET || 'qwercrool_bot_secret'): string {
  return createHmac('sha256', secret).update(token.trim()).digest('hex');
}

/**
 * Validates HMAC signature for a bot token in constant time.
 */
export function verifyBotTokenSignature(
  token: string,
  signature: string,
  secret: string = SESSION_SECRET || 'qwercrool_bot_secret'
): boolean {
  if (!token || !signature) return false;
  const expected = signBotToken(token, secret);
  try {
    const bufA = Buffer.from(signature, 'hex');
    const bufB = Buffer.from(expected, 'hex');
    if (bufA.length !== bufB.length) return false;
    return timingSafeEqual(bufA, bufB);
  } catch {
    return false;
  }
}

// ========================================
// Bot Data Access Functions
// ========================================

/**
 * Verifies a bot token against stored hashes.
 */
export async function verifyBotToken(token: string): Promise<SafeBot | null> {
  if (!token || typeof token !== 'string') {
    return null;
  }
  const cleanToken = token.trim();
  if (cleanToken.length < 16) {
    return null;
  }
  const tokenHash = hashBotToken(cleanToken);
  return getBotByTokenHash(tokenHash);
}

/**
 * Retrieves bot by token SHA-256 hash (constant-time verification).
 */
export async function getBotByTokenHash(tokenHash: string): Promise<SafeBot | null> {
  if (!tokenHash || typeof tokenHash !== 'string') {
    return null;
  }
  const cleanHash = tokenHash.trim();
  if (!cleanHash) return null;

  await ensureBotsTable();
  try {
    const rows = await db
      .select({
        ...safeBotFields,
        tokenHash: botsTable.tokenHash,
      })
      .from(botsTable)
      .where(eq(botsTable.tokenHash, cleanHash));

    if (!rows || rows.length === 0) {
      return null;
    }

    const bot = rows[0];
    try {
      const bufGiven = Buffer.from(cleanHash, 'hex');
      const bufStored = Buffer.from(bot.tokenHash, 'hex');
      if (bufGiven.length !== bufStored.length || !timingSafeEqual(bufGiven, bufStored)) {
        return null;
      }
    } catch {
      if (bot.tokenHash !== cleanHash) {
        return null;
      }
    }

    const { tokenHash: _th, ...safeBot } = bot;
    return safeBot as SafeBot;
  } catch (err: unknown) {
    logger.error({ err }, "[Bots] Error fetching bot by token hash");
    return null;
  }
}

/**
 * Retrieves bot by numeric ID.
 */
export async function getBotById(botId: number): Promise<SafeBot | null> {
  if (typeof botId !== 'number' || isNaN(botId) || botId <= 0) {
    return null;
  }
  await ensureBotsTable();
  try {
    const rows = await db
      .select(safeBotFields)
      .from(botsTable)
      .where(eq(botsTable.id, botId));

    if (!rows || rows.length === 0) {
      return null;
    }
    return rows[0] as SafeBot;
  } catch (err: unknown) {
    logger.error({ err }, "[Bots] Error fetching bot by ID");
    return null;
  }
}

/**
 * Retrieves list of bots owned by user UID.
 */
export async function getBotsByOwner(ownerUid: string): Promise<SafeBot[]> {
  if (!ownerUid || typeof ownerUid !== 'string') {
    return [];
  }
  await ensureBotsTable();
  try {
    const rows = await db
      .select(safeBotFields)
      .from(botsTable)
      .where(eq(botsTable.ownerUid, ownerUid));

    return (rows || []) as SafeBot[];
  } catch (err: unknown) {
    logger.error({ err }, "[Bots] Error fetching bots by owner");
    return [];
  }
}

// ========================================
// Route Setup
// ========================================
export function setupBotRoutes(app: Express) {
  // Ensure table exists asynchronously in background
  ensureBotsTable().catch(() => {});

  /**
   * GET /api/bots — список ботов текущего пользователя
   */
  app.get("/api/bots", requireAuth, async (req: JwtRequest, res) => {
    try {
      const uid = req.user!.uid;
      const botsList = await getBotsByOwner(uid);
      res.json(botsList);
    } catch (err: unknown) {
      logger.error({ err }, "[API] /api/bots error");
      res.status(500).json({ error: "Internal server error" });
    }
  });

  /**
   * POST /api/bots — создать нового бота
   */
  app.post("/api/bots", requireAuth, async (req: JwtRequest, res) => {
    try {
      const uid = req.user!.uid;
      const { username, displayName, description, avatar, webhookUrl, botPermissions } = req.body || {};

      if (!username || typeof username !== 'string' || !username.trim()) {
        res.status(400).json({ error: "username is required" });
        return;
      }
      if (!displayName || typeof displayName !== 'string' || !displayName.trim()) {
        res.status(400).json({ error: "displayName is required" });
        return;
      }

      await ensureBotsTable();
      const rawToken = generateBotToken();
      const tokenHash = hashBotToken(rawToken);
      const tokenPrefix = extractTokenPrefix(rawToken);

      const inserted = await db
        .insert(botsTable)
        .values({
          ownerUid: uid,
          username: username.trim().toLowerCase(),
          displayName: displayName.trim(),
          description: typeof description === 'string' ? description.trim() : '',
          avatar: typeof avatar === 'string' ? avatar.trim() : '',
          tokenHash,
          tokenPrefix,
          webhookUrl: typeof webhookUrl === 'string' ? webhookUrl.trim() : '',
          botPermissions: botPermissions || ['send_messages', 'read_messages'],
        })
        .returning();

      if (!inserted || inserted.length === 0) {
        res.status(500).json({ error: "Failed to create bot" });
        return;
      }

      const { tokenHash: _th, ...safeBot } = inserted[0];
      res.status(201).json({
        bot: safeBot,
        token: rawToken,
      });
    } catch (err: any) {
      logger.error({ err }, "[API] POST /api/bots error");
      if (err?.code === '23505') {
        res.status(409).json({ error: "Bot username already exists" });
        return;
      }
      res.status(500).json({ error: "Internal server error" });
    }
  });

  /**
   * GET /api/bots/token/:token — получить данные бота по токену
   */
  app.get("/api/bots/token/:token", requireAuth, async (req: JwtRequest, res) => {
    try {
      const { token } = req.params;
      const bot = await verifyBotToken(token);
      if (!bot) {
        res.status(404).json({ error: "Bot not found or invalid token" });
        return;
      }
      res.json(bot);
    } catch (err: unknown) {
      logger.error({ err }, "[API] /api/bots/token/:token error");
      res.status(500).json({ error: "Internal server error" });
    }
  });

  /**
   * GET /api/bots/by-hash — получить данные бота по хешу токена
   */
  app.get("/api/bots/by-hash", requireAuth, async (req: JwtRequest, res) => {
    try {
      const tokenHash = req.headers["x-token-hash"] as string | undefined;
      if (!tokenHash) {
        res.status(400).json({ error: "Missing X-Token-Hash header" });
        return;
      }
      const bot = await getBotByTokenHash(tokenHash);
      if (!bot) {
        res.status(404).json({ error: "Bot not found" });
        return;
      }
      res.json(bot);
    } catch (err: unknown) {
      logger.error({ err }, "[API] /api/bots/by-hash error");
      res.status(500).json({ error: "Internal server error" });
    }
  });

  /**
   * GET /api/bots/id/:botId — получить данные бота по ID
   */
  app.get("/api/bots/id/:botId", requireAuth, async (req: JwtRequest, res) => {
    try {
      const botId = parseInt(req.params.botId, 10);
      if (isNaN(botId)) {
        res.status(400).json({ error: "Invalid bot ID" });
        return;
      }
      const bot = await getBotById(botId);
      if (!bot) {
        res.status(404).json({ error: "Bot not found" });
        return;
      }
      res.json(bot);
    } catch (err: unknown) {
      logger.error({ err }, "[API] /api/bots/id/:botId error");
      res.status(500).json({ error: "Internal server error" });
    }
  });

  /**
   * POST /api/bots/id/:botId/token — перегенерировать токен бота
   */
  app.post("/api/bots/id/:botId/token", requireAuth, async (req: JwtRequest, res) => {
    try {
      const uid = req.user!.uid;
      const botId = parseInt(req.params.botId, 10);
      if (isNaN(botId)) {
        res.status(400).json({ error: "Invalid bot ID" });
        return;
      }

      await ensureBotsTable();
      const existing = await db
        .select()
        .from(botsTable)
        .where(eq(botsTable.id, botId));

      if (!existing || existing.length === 0) {
        res.status(404).json({ error: "Bot not found" });
        return;
      }

      if (existing[0].ownerUid !== uid && req.user?.role !== 'admin') {
        res.status(403).json({ error: "Access denied" });
        return;
      }

      const rawToken = generateBotToken(botId);
      const tokenHash = hashBotToken(rawToken);
      const tokenPrefix = extractTokenPrefix(rawToken);

      const updated = await db
        .update(botsTable)
        .set({
          tokenHash,
          tokenPrefix,
          updatedAt: new Date(),
        })
        .where(eq(botsTable.id, botId))
        .returning();

      if (!updated || updated.length === 0) {
        res.status(500).json({ error: "Failed to update bot token" });
        return;
      }

      const { tokenHash: _th, ...safeBot } = updated[0];
      res.json({
        bot: safeBot,
        token: rawToken,
      });
    } catch (err: unknown) {
      logger.error({ err }, "[API] /api/bots/id/:botId/token error");
      res.status(500).json({ error: "Internal server error" });
    }
  });
}