/**
 * Pino structured logger с поддержкой контекста (requestId, userId).
 *
 * Использование:
 *   import { logger } from '../services/logger.ts';
 *   logger.info({ requestId, userId }, 'User logged in');
 *   logger.error({ err }, 'Something broke');
 *
 * Или с AsyncLocalStorage-контекстом (автоматически из middleware):
 *   import { ctx } from '../services/logger.ts';
 *   const log = ctx(req);
 *   log.info('User logged in'); // requestId и userId подставятся автоматически
 */
import pino from 'pino';
import { AsyncLocalStorage } from 'async_hooks';

// ── Context ────────────────────────────────────────────────────────────────

export interface LogContext {
  requestId?: string;
  userId?: string;
  [key: string]: unknown;
}

export const asyncLocalStorage = new AsyncLocalStorage<LogContext>();

/**
 * Создаёт логгер привязанный к контексту запроса.
 * Подставляет requestId и userId из AsyncLocalStorage.
 */
export function ctx(req?: { requestId?: string; user?: { uid?: string } }): pino.Logger {
  const store = asyncLocalStorage.getStore() || {};
  const extra: LogContext = {};
  if (req?.requestId) extra.requestId = req.requestId;
  if (req?.user?.uid) extra.userId = req.user.uid;
  return logger.child(extra);
}

// ── Logger ─────────────────────────────────────────────────────────────────

const isDev = process.env.NODE_ENV !== 'production';

export const logger = pino({
  level: process.env.LOG_LEVEL || (isDev ? 'debug' : 'info'),
  // В dev — человекочитаемый формат с цветами
  ...(isDev
    ? {
        transport: {
          target: 'pino-pretty',
          options: {
            colorize: true,
            translateTime: 'HH:MM:ss',
            ignore: 'pid,hostname',
          },
        },
      }
    : {}),
  base: { service: 'qwcrool-server' },
  serializers: {
    err: pino.stdSerializers.err,
    error: pino.stdSerializers.err,
  },
});

export default logger;