import jwt from 'jsonwebtoken';
import { AppUser } from './types.ts';

const JWT_EXPIRES_IN = '1h';

function getJwtSecret(): string {
  if (!process.env.JWT_SECRET) {
    console.error('[FATAL] JWT_SECRET environment variable is not set. Refusing to start with insecure default.');
    throw new Error('JWT_SECRET environment variable is required');
  }
  return process.env.JWT_SECRET;
}

function getRefreshSecret(): string {
  if (!process.env.JWT_REFRESH_SECRET) {
    console.error('[FATAL] JWT_REFRESH_SECRET environment variable is not set.');
    throw new Error('JWT_REFRESH_SECRET environment variable is required');
  }
  return process.env.JWT_REFRESH_SECRET;
}

export interface JwtPayload {
  uid: string;
  email: string;
  sessionUid?: string;
  iat: number;
  exp: number;
}

export function signJwt(user: AppUser, sessionUid?: string) {
  const payload: Record<string, any> = { uid: user.uid, email: user.email };
  if (sessionUid) payload.sessionUid = sessionUid;
  return jwt.sign(payload, getJwtSecret(), {
    expiresIn: JWT_EXPIRES_IN,
  });
}

/**
 * Проверяет JWT access token.
 * Если передан expectedSessionUid — additionally проверяет,
 * что токен был выдан для этой конкретной сессии.
 */
export function verifyJwt(token: string, expectedSessionUid?: string) {
  const decoded = jwt.verify(token, getJwtSecret(), { algorithms: ['HS256'] }) as JwtPayload;
  if (expectedSessionUid && decoded.sessionUid && decoded.sessionUid !== expectedSessionUid) {
    throw new Error('Session UID mismatch: token was issued for a different session');
  }
  return decoded;
}

// ========================================
// Refresh Token (3 дня — достаточно для
// автоматического обновления без риска
// длительной компрометации)
// ========================================
const REFRESH_EXPIRES_IN = '3d';

export function signRefreshJwt(user: AppUser, sessionUid?: string) {
  const payload: Record<string, any> = { uid: user.uid, email: user.email, type: 'refresh' };
  if (sessionUid) payload.sessionUid = sessionUid;
  return jwt.sign(payload, getRefreshSecret(), {
    expiresIn: REFRESH_EXPIRES_IN,
  });
}

/**
 * Проверяет refresh token.
 * Если передан expectedSessionUid — additionally проверяет,
 * что токен был выдан для этой конкретной сессии.
 */
export function verifyRefreshJwt(token: string, expectedSessionUid?: string) {
  const decoded = jwt.verify(token, getRefreshSecret(), { algorithms: ['HS256'] }) as JwtPayload & { type?: string };
  if (expectedSessionUid && decoded.sessionUid && decoded.sessionUid !== expectedSessionUid) {
    throw new Error('Session UID mismatch: refresh token was issued for a different session');
  }
  return decoded;
}
