/**
 * Chat Members routes — add, remove, leave
 *
 * POST   /api/chats/:chatId/members          — добавить участника (admin/creator only)
 * DELETE /api/chats/:chatId/members/:uid      — удалить участника (admin/creator only)
 * POST   /api/chats/:chatId/leave             — выйти из чата (нельзя из private)
 */
import { Express } from 'express';
import { JwtRequest } from '../../src/middleware/jwtAuth.ts';
import { requireAuth } from '../../src/middleware/jwtAuth.ts';
import { chatsRateLimit } from '../../src/middleware/security.ts';
import { logger } from '../services/logger.ts';

type ChatRow = {
  id?: number;
  chatUid?: string;
  type?: string;
  participants?: string[];
  members?: string[];
  admins?: string[];
  creatorId?: number;
  creatorUid?: string;
};

function getBroadcast() {
  return (globalThis as any).__broadcastStatusUpdate as
    | ((targetUids: string[], data: any) => void)
    | undefined;
}

export function setupChatMemberRoutes(app: Express) {
  // ========================================
  // POST /api/chats/:chatId/members — добавить участника
  // Body: { uid: string } или { uids: string[] }
  // Доступно: admin чата, creator чата, глобальный admin
  // ========================================
  app.post(
    '/api/chats/:chatId/members',
    requireAuth,
    chatsRateLimit,
    async (req: JwtRequest, res) => {
      try {
        const requesterUid = req.user!.uid;
        const { chatId } = req.params;
        const { uid: singleUid, uids: multipleUids } = req.body;

        const uidsToAdd: string[] = singleUid
          ? [singleUid]
          : Array.isArray(multipleUids)
            ? multipleUids
            : [];

        if (uidsToAdd.length === 0) {
          return res
            .status(400)
            .json({ error: 'Provide uid or uids array in body.' });
        }

        const { getChat } = await import('../../src/db/helpers.ts');
        const chat: ChatRow | null = await getChat(chatId);
        if (!chat) {
          return res.status(404).json({ error: 'Chat not found' });
        }

        if (chat.type === 'private') {
          return res
            .status(400)
            .json({ error: 'Cannot add members to a private chat.' });
        }

        // Проверяем права: admin/creator чата или глобальный admin
        const { getUserByUid } = await import('../../src/db/auth.ts');
        const requester = await getUserByUid(requesterUid);
        const isChatAdmin = chat.admins?.includes(requesterUid);
        const isCreator =
          chat.creatorUid === requesterUid || chat.creatorId === requester?.id;
        const isGlobalAdmin = requester?.role === 'admin';

        if (!isChatAdmin && !isCreator && !isGlobalAdmin) {
          return res.status(403).json({ error: 'Only chat administrators can add members.' });
        }

        const participants = [...(chat.participants || [])];
        const members = [...(chat.members || [])];
        let addedCount = 0;

        for (const uid of uidsToAdd) {
          if (!participants.includes(uid)) {
            participants.push(uid);
            addedCount++;
          }
          if (!members.includes(uid)) {
            members.push(uid);
          }
        }

        if (addedCount === 0) {
          return res.json({ success: true, added: 0, message: 'All users are already members.' });
        }

        const { updateChat, logAdminAction, createMessage } = await import('../../src/db/helpers.ts');
        await updateChat(chatId, { participants, members });

        // Создаём системные сообщения о присоединении
        for (const addedUid of uidsToAdd) {
          try {
            const { getUserByUid } = await import('../../src/db/auth.ts');
            const addedUser = await getUserByUid(addedUid);
            const senderUser = await getUserByUid(requesterUid);
            const addedName = addedUser?.displayName || addedUser?.username || addedUid;
            const actorName = senderUser?.displayName || senderUser?.username || requesterUid;
            const isSelfAdd = addedUid === requesterUid;

            await createMessage({
              msgUid: `sys_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
              chatId,
              senderId: senderUser?.id || 0,
              senderName: 'system',
              text: isSelfAdd
                ? `👋 ${addedName} присоединился к чату`
                : `👋 ${actorName} добавил(а) ${addedName} в чат`,
              type: 'text',
            });
          } catch (msgErr) {
            logger.warn({ err: msgErr }, 'Failed to create system message on member add');
          }
        }

        // Логируем действие
        logAdminAction({
          chatId: chat.id || undefined,
          actorUid: requesterUid,
          action: 'members_added',
          details: { addedUids: uidsToAdd, addedCount },
        });

        logger.info(
          `[MEMBERS] ${requesterUid} added ${addedCount} member(s) to chat ${chatId}`,
        );

        // Broadcast обновления участников чата
        const broadcast = getBroadcast();
        if (broadcast) {
          const allParticipantUids = participants.filter(
            (p) => !uidsToAdd.includes(p) || uidsToAdd.includes(p),
          );
          broadcast([...new Set(allParticipantUids)], {
            type: 'chat_members_updated',
            chatId,
            participants,
            members,
            addedBy: requesterUid,
            addedUids: uidsToAdd,
          });
        }

        res.json({ success: true, added: addedCount, participants, members });
      } catch (err: unknown) {
        logger.error({ err }, 'Add member error');
        res.status(500).json({ error: err.message });
      }
    },
  );

  // ========================================
  // DELETE /api/chats/:chatId/members/:uid — удалить участника
  // Доступно: admin чата, creator чата, глобальный admin
  // ========================================
  app.delete(
    '/api/chats/:chatId/members/:uid',
    requireAuth,
    chatsRateLimit,
    async (req: JwtRequest, res) => {
      try {
        const requesterUid = req.user!.uid;
        const { chatId, uid } = req.params;

        if (!uid) {
          return res.status(400).json({ error: 'uid param is required.' });
        }

        const { getChat } = await import('../../src/db/helpers.ts');
        const chat: ChatRow | null = await getChat(chatId);
        if (!chat) {
          return res.status(404).json({ error: 'Chat not found' });
        }

        const { getUserByUid } = await import('../../src/db/auth.ts');
        const requester = await getUserByUid(requesterUid);
        const isChatAdmin = chat.admins?.includes(requesterUid);
        const isCreator =
          chat.creatorUid === requesterUid || chat.creatorId === requester?.id;
        const isGlobalAdmin = requester?.role === 'admin';

        if (!isChatAdmin && !isCreator && !isGlobalAdmin) {
          return res
            .status(403)
            .json({ error: 'Only chat administrators can remove members.' });
        }

        // Нельзя удалить creator из чата
        if (chat.creatorUid === uid) {
          return res
            .status(400)
            .json({ error: 'Cannot remove the chat creator.' });
        }

        const participants = (chat.participants || []).filter((p) => p !== uid);
        const members = (chat.members || []).filter((m) => m !== uid);
        const admins = (chat.admins || []).filter((a) => a !== uid);

        const { updateChat, logAdminAction, createMessage } = await import('../../src/db/helpers.ts');
        await updateChat(chatId, { participants, members, admins });

        // Создаём системное сообщение об исключении
        try {
          const { getUserByUid } = await import('../../src/db/auth.ts');
          const removedUser = await getUserByUid(uid);
          const actorUser = await getUserByUid(requesterUid);
          const removedName = removedUser?.displayName || removedUser?.username || uid;
          const actorName = actorUser?.displayName || actorUser?.username || requesterUid;

          await createMessage({
            msgUid: `sys_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
            chatId,
            senderId: actorUser?.id || 0,
            senderName: 'system',
            text: `🚪 ${actorName} исключил(а) ${removedName} из чата`,
            type: 'text',
          });
        } catch (msgErr) {
          logger.warn({ err: msgErr }, 'Failed to create system message on member remove');
        }

        logAdminAction({
          chatId: chat.id || undefined,
          actorUid: requesterUid,
          action: 'member_removed',
          targetUid: uid,
        });

        logger.info(
          `[MEMBERS] ${requesterUid} removed ${uid} from chat ${chatId}`,
        );

        // Broadcast
        const broadcast = getBroadcast();
        if (broadcast) {
          broadcast([...new Set([...participants, uid])], {
            type: 'chat_members_updated',
            chatId,
            participants,
            members,
            removedBy: requesterUid,
            removedUid: uid,
          });
        }

        res.json({ success: true, participants, members });
      } catch (err: unknown) {
        logger.error({ err }, 'Remove member error');
        res.status(500).json({ error: err.message });
      }
    },
  );

  // ========================================
  // POST /api/chats/:chatId/leave — выйти из чата
  // Нельзя выйти из private-чата
  // ========================================
  app.post(
    '/api/chats/:chatId/leave',
    requireAuth,
    chatsRateLimit,
    async (req: JwtRequest, res) => {
      try {
        const uid = req.user!.uid;
        const { chatId } = req.params;

        const { getChat } = await import('../../src/db/helpers.ts');
        const chat: ChatRow | null = await getChat(chatId);
        if (!chat) {
          return res.status(404).json({ error: 'Chat not found' });
        }

        if (chat.type === 'private') {
          return res
            .status(400)
            .json({ error: 'Cannot leave a private chat.' });
        }

        // Creator не может покинуть свой чат — только удалить
        if (chat.creatorUid === uid) {
          return res
            .status(400)
            .json({ error: 'Chat creator cannot leave. Delete the chat instead.' });
        }

        const participants = (chat.participants || []).filter((p) => p !== uid);
        const members = (chat.members || []).filter((m) => m !== uid);
        const admins = (chat.admins || []).filter((a) => a !== uid);

        const { updateChat, logAdminAction, createMessage } = await import('../../src/db/helpers.ts');
        await updateChat(chatId, { participants, members, admins });

        // Создаём системное сообщение о выходе
        try {
          const { getUserByUid } = await import('../../src/db/auth.ts');
          const leavingUser = await getUserByUid(uid);
          const leavingName = leavingUser?.displayName || leavingUser?.username || uid;

          await createMessage({
            msgUid: `sys_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
            chatId,
            senderId: leavingUser?.id || 0,
            senderName: 'system',
            text: `🚪 ${leavingName} покинул(а) чат`,
            type: 'text',
          });
        } catch (msgErr) {
          logger.warn({ err: msgErr }, 'Failed to create system message on member leave');
        }

        logAdminAction({
          chatId: chat.id || undefined,
          actorUid: uid,
          action: 'member_left',
        });

        logger.info(`[MEMBERS] ${uid} left chat ${chatId}`);

        // Broadcast оставшимся участникам + покинувшему
        const broadcast = getBroadcast();
        if (broadcast) {
          broadcast([...new Set([...participants, uid])], {
            type: 'chat_members_updated',
            chatId,
            participants,
            members,
            leftUid: uid,
          });
        }

        res.json({ success: true, participants, members });
      } catch (err: unknown) {
        logger.error({ err }, 'Leave chat error');
        res.status(500).json({ error: err.message });
      }
    },
  );
}